text:
/* The information pages share a bound cover, a paper leaf, and one place marker. */
#dialog-layer {
  position:absolute; inset:0; z-index:50; overflow:hidden; pointer-events:none;
}
#dialog-layer:empty { display:none; }
#dialog-layer.dlg-open { display:block; }
#dialog-layer *, #dialog-layer *::before, #dialog-layer *::after { box-sizing:border-box; }
.dlg-shade {
  position:absolute; inset:0; pointer-events:auto;
  background:radial-gradient(ellipse at 50% 45%,#162a2d5c,#111d22ae); backdrop-filter:blur(2px); -webkit-backdrop-filter:blur(2px);
}
.dlg-frame {
  position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
  --folio-frame-y:clamp(11px,3.4vmin,28px); --folio-safe-top:var(--edge-top); --folio-safe-bottom:var(--edge-bottom);
  padding-inline:max(clamp(16px,4.5vmin,40px),calc(var(--side-inset) + 5px));
  padding-block:max(var(--folio-frame-y),calc(var(--folio-safe-top) + 5px)) max(var(--folio-frame-y),calc(var(--folio-safe-bottom) + 5px)); pointer-events:none;
}
.dlg-panel, #cover-dialog {
  --folio-ink:#30291f; --folio-muted:#625849; --folio-gold:#886638; --folio-accent:#335367;
  --folio-margin:clamp(20px,4.5vmin,37px); --folio-binding:clamp(35px,7.7vmin,61px);
  --folio-page-bg:linear-gradient(100deg,#cbb68e 0,#ead9b8 5%,#f3e6cb 11%,#f4e7ca 71%,#ead8b5 100%);
  position:relative; isolation:isolate; color:var(--folio-ink); color-scheme:light;
  font:15px/1.48 var(--sans); letter-spacing:normal; text-align:start; text-transform:none;
}
.dlg-panel {
  display:flex; flex-direction:column; width:min(100%,601px); max-height:100%; min-width:0; min-height:0;
  container:dialogpanel / inline-size; overflow:visible; pointer-events:auto; user-select:none;
}
.dlg-panel[data-folio="rules"] { --folio-accent:#405d4b; }
.dlg-panel[data-folio="noble"] { --folio-accent:#784a47; }
.dlg-panel[data-folio="resetConfirm"] { --folio-accent:#844a39; width:min(100%,483px); }
.dlg-panel[data-folio="result"] { --folio-accent:#775238; width:min(100%,553px); }
.dlg-panel[data-folio="player"][data-player="1"] { --folio-accent:#844c43; }
.dlg-panel::before, #cover-dialog::before {
  content:""; position:absolute; z-index:-3; pointer-events:none; inset:4px 8px 0 2px; transform:rotate(-.36deg); border-radius:6px 12px 11px 6px;
  border:1px solid #392d23; background:linear-gradient(110deg,#1e3538d1,#334c49d1 45%,#423728b8),var(--weave) center/60px,#37443c;
  box-shadow:1px 3px 1px #61482c,2px 8px 13px #211c174a,3px 17px 37px #0e161b6b;
}
.dlg-panel::after, #cover-dialog::after {
  content:""; position:absolute; z-index:-2; pointer-events:none; inset:0;
  border:15px solid transparent; border-image:var(--folio-paper,none) 10% 9% 10% 11% fill / 18px 15px 21px 27px / 0 stretch;
  background:var(--folio-page-bg); background-clip:padding-box;
  filter:drop-shadow(1px 1.5px 1px #4b351d73);
}
.dlg-title-symbol {
  position:absolute; z-index:2; top:clamp(18px,4.7vmin,35px); left:-9px; display:grid; place-items:center;
  width:clamp(36px,7.5vmin,48px); height:29px; color:#f5e0ad;
  background:linear-gradient(180deg,#ffffff30,transparent 27% 81%,#17201d3c),var(--folio-accent);
  clip-path:polygon(0 3%,100% 0,91% 51%,100% 100%,0 96%);
}
.dlg-title-symbol::after { content:""; position:absolute; inset:3px 4px; border-block:1px dashed #e3c6a166; pointer-events:none; }
.dlg-panel .dlg-title-symbol svg { width:17px; height:17px; }
.dlg-panel:focus { outline:0; }
.dlg-panel button, .dlg-panel input, .dlg-panel summary { font:inherit; color:inherit; }
.dlg-panel button {
  appearance:none; -webkit-appearance:none; padding:0; margin:0; border:0; background:none; cursor:pointer;
}
.dlg-panel button, .dlg-panel summary, #cover-dialog button { touch-action:manipulation; }
.dlg-panel svg:where(:not(.card-stock *)) { display:inline-block; flex:none; width:18px; height:18px; vertical-align:middle; }
.dlg-panel :is(button,input,summary):focus-visible, #cover-dialog :is(button,input):focus-visible {
  outline:2px solid #155970; outline-offset:2px;
}
.dlg-panel button:disabled { opacity:.5; cursor:default; }
.dlg-header, .dlg-body, .dlg-foot { padding-inline:var(--folio-binding) var(--folio-margin); }
.dlg-header {
  position:relative; display:flex; align-items:center; gap:7px; flex:none;
  min-height:62px; padding-top:clamp(9px,2.4vmin,18px); padding-bottom:5px;
}
.dlg-header h2, .cover-dialog-body h2 {
  flex:1; min-width:0; margin:0; color:var(--folio-ink); font:740 clamp(23px,5.2vmin,33px)/1.23 var(--serif);
  letter-spacing:.045em; overflow-wrap:anywhere;
}
.dlg-header .dlg-icon-button {
  display:grid; place-items:center; flex:none; width:42px; height:42px; color:#685941; border-radius:50%;
}
.screen-toggle, .dlg-header .screen-toggle {
  display:inline-flex; align-items:center; justify-content:center; gap:5px; flex:none;
  min-height:44px; padding:0 5px; border:0; background:transparent;
  color:#634b2d; font:650 14px/1 var(--serif); white-space:nowrap;
}
.screen-toggle .icon { width:16px; height:16px; }
.screen-toggle[aria-disabled="true"] { opacity:.65; }
.screen-note { color:#704528; font:550 12px/1.45 var(--sans); margin:0 0 6px; }
.screen-note:empty { display:none; }
.dlg-icon-button > svg { width:21px; height:21px; padding:1px; stroke-width:1.45; }
.dlg-back svg { transform:rotate(180deg); }
.dlg-body {
  position:relative; min-height:0; flex:0 1 auto; overflow:auto; overscroll-behavior:contain; touch-action:pan-x pan-y;
  -webkit-overflow-scrolling:touch; scrollbar-width:thin; scrollbar-color:#ad966d transparent;
  padding-top:clamp(7px,1.6vmin,13px); padding-bottom:clamp(8px,1.8vmin,16px);
}
.dlg-body > :first-child { margin-top:0; }
.dlg-body > :last-child { margin-bottom:0; }
.dlg-foot { display:flex; align-items:center; justify-content:flex-end; flex:none; flex-wrap:wrap; gap:8px 14px; padding-top:2px; padding-bottom:clamp(10px,2.4vmin,20px); }
.dlg-panel .dlg-button, .cover-dialog-actions button {
  position:relative; isolation:isolate; display:inline-flex; justify-content:center; align-items:center; gap:7px;
  min-height:43px; min-width:62px; padding:6px 9px; border:0; border-radius:2px; color:#4b4b3f;
  background:none; font:670 15px/1.25 var(--serif); letter-spacing:.03em;
}
.dlg-button > svg { width:17px; height:17px; }
.dlg-panel .dlg-secondary > span, .cover-dialog-actions button:not(.cover-dialog-primary) {
  text-decoration:underline; text-underline-offset:4px; text-decoration-color:#957b567d;
}
.dlg-panel .dlg-primary, .cover-dialog-actions .cover-dialog-primary {
  min-width:104px; padding-inline:17px 24px; color:#fff1cf; filter:drop-shadow(0 1.5px 1px #513c2742);
}
.dlg-panel .dlg-primary::before, .cover-dialog-actions .cover-dialog-primary::before {
  content:""; position:absolute; z-index:-1; inset:4px 0;
  background:linear-gradient(180deg,#d9c99f46,transparent 20% 78%,#1c211f36),var(--folio-accent);
  clip-path:polygon(2% 6%,100% 0,94% 50%,100% 94%,0 100%,0 15%);
}
.dlg-panel .dlg-primary::after, .cover-dialog-actions .cover-dialog-primary::after {
  content:""; position:absolute; pointer-events:none; inset:8px 10px 8px 5px; border-block:1px dashed #f0d8a873; transform:rotate(-.6deg);
}
.dlg-primary > svg { color:#ecd29a; }
.dlg-panel button:enabled:active, .cover-dialog-actions button:active { transform:translateY(1px); }
@media (hover:hover) {
  .dlg-panel button:enabled:hover, .cover-dialog-actions button:hover { filter:brightness(1.10); }
  .dlg-panel .dlg-icon-button:hover { background:#9e875c15; }
}
.dlg-note, .dlg-rule p, .dlg-rule li { color:var(--folio-muted); margin:0 0 9px; font:400 14px/1.65 var(--sans); }
.dlg-highlight { color:#784732; }
.dlg-error { margin:0 var(--folio-margin) 5px var(--folio-binding); color:#8b3d2b; font-size:13px; }
.dlg-subtitle, .dlg-fieldset legend, .pack-list legend, .lobby-first legend {
  margin:0 0 5px; padding:0; color:#67553c; font:700 14px/1.4 var(--serif); letter-spacing:.04em;
}
.dlg-subtitle { margin-top:13px; }
.dlg-row, .dlg-need { display:flex; align-items:center; gap:9px; min-height:39px; }
.dlg-row { justify-content:space-between; border-bottom:1px solid #9d805039; }
.dlg-row-label { flex:none; font:650 14px var(--serif); }
.dlg-row-content, .dlg-mini-prices { display:flex; flex-wrap:wrap; align-items:center; gap:6px; }
.dlg-price { display:inline-flex; align-items:center; gap:3px; color:var(--folio-ink); font:650 18px/1 var(--digits); white-space:nowrap; }
.dlg-price svg { width:21px; height:21px; }
.dlg-free { color:var(--folio-muted); font-size:13px; }

/* The settings book opens on facing pages. Seat seals are also the first-player controls. */
.dlg-panel[data-folio="settings"] { width:min(100%,641px); --folio-binding:clamp(35px,7.1vmin,54px); }
.dlg-center-fold {
  position:absolute; z-index:-1; left:calc((100% + var(--folio-binding) - var(--folio-margin)) / 2); top:2.5%; bottom:2%; width:21px; transform:translateX(-50%); pointer-events:none;
  background:linear-gradient(90deg,transparent,#7958301a 34%,#72532c43 49%,#ffeecf77 57%,#fff2d72b 67%,transparent);
}
.dlg-settings { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); grid-template-areas:"actions sounds" "seats sounds"; gap:10px clamp(33px,8.2cqi,54px); align-items:start; }
.dlg-settings .dlg-settings-start { grid-area:actions; display:flex; align-items:center; flex-wrap:wrap; gap:0 3px; margin:0; }
.dlg-settings .dlg-settings-start .dlg-button { flex:none; min-width:0; }
.dlg-settings .dlg-settings-start .dlg-primary { padding-inline:16px 22px; }.dlg-settings-start .dlg-secondary { font-size:14px; }
.dlg-fieldset { border:0; padding:0; min-width:0; margin:0; }
.opening-choice {
  display:flex; align-items:center; gap:8px; min-height:37px; margin:3px 0;
  color:#494032; font:650 14px/1.35 var(--serif); cursor:pointer; touch-action:manipulation;
}
.opening-choice small { margin-right:5px; color:#736449; font:650 12px var(--serif); }
.dlg-settings > .opening-choice { grid-column:1 / -1; margin:0; }
.dlg-seats-page > .opening-choice { gap:5px; font-size:13px; }
.opening-choice:has(input:focus-visible) { outline:2px solid #155970; outline-offset:1px; }
.dlg-fieldset legend { padding:0; }
.dlg-seats-page { grid-area:seats; }
.dlg-seats-page legend, .dlg-sound-page legend { padding:0; margin:0 0 7px; color:#635239; font:700 16px/1.4 var(--serif); letter-spacing:.08em; }
.dlg-seats-page > legend { max-width:100%; }
.dlg-seats-page > legend small { display:inline-block; max-width:100%; color:var(--folio-muted); font:500 12px/1.4 var(--sans); letter-spacing:0; overflow-wrap:anywhere; }
.dlg-seat-sign { min-width:0; display:grid; grid-template-columns:clamp(43px,9cqi,57px) minmax(0,1fr); align-items:center; gap:5px; margin:2px 0 6px; }
.dlg-seat-order { display:grid; place-items:center; position:relative; width:100%; min-height:49px; cursor:pointer; }
.dlg-seat-order input, .dlg-instrument input, .dlg-first-options input { position:absolute; width:1px; height:1px; margin:0; opacity:0; }
.dlg-order-seal { position:relative; display:grid; place-items:start center; width:100%; height:49px; }
.dlg-seat-order input:checked + .dlg-order-seal::before {
  content:""; position:absolute; left:50%; top:-1px; width:45px; height:45px; transform:translateX(-50%);
  border:1px solid #aa8751; outline:1px solid #c8a46a80; outline-offset:1px; border-radius:50%; pointer-events:none;
}
.dlg-order-seal img { width:43px; aspect-ratio:1; object-fit:contain; opacity:.69; transform:rotate(-6deg) scale(.88); }
.dlg-seat-sign[data-seat="1"] .dlg-order-seal img { transform:rotate(6deg) scale(.88); }
.dlg-order-seal i { position:absolute; bottom:0; left:50%; transform:translateX(-50%); white-space:nowrap; font:650 11px/1.2 var(--serif); color:#73634a; }
.dlg-order-seal .on { padding:1px 7px; color:#513f26; background:linear-gradient(145deg,#e9d5a1,#c7ab70); clip-path:polygon(0 0,100% 4%,95% 48%,100% 96%,0 100%,5% 50%); }
.dlg-order-seal .on, .dlg-seat-order input:checked + .dlg-order-seal .off, .dlg-dial-state .on, .dlg-instrument input:checked ~ .dlg-dial-state .off { display:none; }
.dlg-seat-order input:checked + .dlg-order-seal .on, .dlg-instrument input:checked ~ .dlg-dial-state .on { display:inline-block; }
.dlg-seat-order input:checked + .dlg-order-seal img { opacity:1; transform:rotate(-3deg) scale(1.08); filter:drop-shadow(0 1px 1px #644e2e59); }
.dlg-seat-sign[data-seat="1"] input:checked + .dlg-order-seal img { transform:rotate(3deg) scale(1.08); }
.dlg-name-field { display:flex; flex-direction:column; min-width:0; }
.dlg-name-field > span { color:var(--folio-muted); font:500 11px/1.15 var(--sans); }
.dlg-name-field input {
  min-width:0; width:100%; min-height:34px; padding:1px 3px 0; border:0; border-bottom:1px solid #9a7d54; border-radius:0;
  color:#294653; background:transparent; font:650 18px/1.3 var(--serif); user-select:text; -webkit-user-select:text;
}
.dlg-seat-sign[data-seat="1"] .dlg-name-field input { color:#764333; }
.dlg-sound-page { grid-area:sounds; min-width:0; }
.dlg-sound-keys { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:6px; margin:4px auto 12px; }
.dlg-instrument { display:grid; justify-items:center; align-content:start; gap:5px; position:relative; cursor:pointer; min-width:0; padding:2px; }
.dlg-instrument b { color:#443b2d; font:700 15px/1.4 var(--serif); }
.dlg-dial {
  position:relative; display:block; width:32px; height:32px; margin:2px 0; border:1px solid #876738; border-radius:50%;
  background:radial-gradient(ellipse at 29% 24%,#f3e0b0,#c2a073 50%,#9b794c 69%,#ecd8a9 77%,#977b53 82%);
  box-shadow:0 2px 2px #6e542e66,0 0 0 2px #ddd0ac,0 0 0 3px #ab946d;
}
.dlg-dial::after { content:""; position:absolute; left:calc(50% - 1.5px); top:2px; width:3px; height:11px; border-radius:3px; transform-origin:50% 13px; transform:rotate(-56deg); background:#6d543a; box-shadow:1px 0 0 #fbdda1; }
.dlg-instrument input:checked + .dlg-dial::after { transform:rotate(56deg); background:#284b4c; }
.dlg-instrument:active .dlg-dial { box-shadow:0 0 0 2px #d4c098,0 0 0 3px #a18a60; }
@media (prefers-reduced-motion:no-preference) {
  .dlg-dial::after { transition:transform .16s ease-out; }
  .dlg-order-seal img { transition:opacity .15s,transform .15s ease-out; }
}
.dlg-dial-state { color:#685b46; font:650 11px/1.25 var(--serif); }.dlg-dial-state i { font-style:normal; }
.dlg-seat-order input:focus-visible + span, .dlg-instrument input:focus-visible + i { outline:2px solid #155970; outline-offset:3px; }
.dlg-first-options { display:flex; flex-wrap:wrap; gap:0 12px; }
.dlg-first-options label { display:flex; align-items:center; position:relative; min-width:0; max-width:100%; cursor:pointer; }
.dlg-first-options label > span { display:flex; align-items:center; gap:7px; min-height:38px; color:var(--folio-muted); font:600 14px/1.4 var(--serif); overflow-wrap:anywhere; }
.dlg-first-options span::before {
  content:""; flex:none; width:14px; height:14px; border:1px solid #948363; border-radius:50%; background:#d7c69f; box-shadow:inset 1px 1px 1px #92806966,0 1px #fff2cd;
}
.dlg-first-options input:checked + span { color:var(--folio-accent); font-weight:750; }
.dlg-first-options input:checked + span::before { background:radial-gradient(circle,#435950 0 37%,#dfc99a 45% 66%,#a9905f 69%); }
.dlg-first-options input:focus-visible + span { outline:2px solid #155970; outline-offset:3px; }
.dlg-music-level { display:grid; grid-template-columns:1fr auto; align-items:center; gap:0 7px; margin:4px 0; color:var(--folio-muted); font:12px/1.4 var(--sans); }
.dlg-music-level > span { grid-row:1; }.dlg-music-level output { grid-area:1/2; font:650 13px var(--digits); }
.dlg-music-level input {
  grid-area:2/1/3/-1; appearance:none; -webkit-appearance:none; width:100%; min-width:40px; height:31px; margin:1px 0;
  border:0; cursor:pointer; touch-action:none; background:repeating-linear-gradient(90deg,#957e58 0 1px,transparent 1px 12.5%) center calc(50% + 6px)/calc(100% - 15px) 4px no-repeat;
}
.dlg-music-level input::-webkit-slider-runnable-track { height:4px; border-radius:3px; background:linear-gradient(#66583e 0 1px,#f7e4b4 1px 2px,#a58b59 2px 3px,#f3dfae 3px); }
.dlg-music-level input::-webkit-slider-thumb { -webkit-appearance:none; width:16px; height:18px; margin-top:-7px; border:1px solid #866638; border-radius:7px; background:linear-gradient(90deg,#9b7a49,#ead39a 34%,#987745 50%,#d4b681 64%,#ae8b54); box-shadow:0 1px 2px #59493266; }
.dlg-music-level input::-moz-range-track { height:4px; background:#88744e; }
.dlg-music-level input::-moz-range-thumb { width:15px; height:17px; border:1px solid #866638; border-radius:7px; background:#c8aa74; }
.dlg-settings + .dlg-note { margin-top:7px; }

/* The rule index, portraits, and item accounts use the same sheet in different ways. */
.dlg-rules-intro { display:flex; align-items:center; gap:14px; margin:0 0 9px; }
.dlg-goal-mark {
  flex:none; width:50px; height:55px; display:flex; align-items:center; justify-content:center; flex-direction:column; gap:1px;
  color:#7e5b29; border:1px solid #b69762; border-radius:48% 48% 44% 44%; outline:1px solid #ad8e5a78; outline-offset:-4px;
}
.dlg-goal-mark > svg { width:16px; height:14px; } .dlg-goal-mark b { font:650 25px/1 var(--digits); }
.dlg-rules-intro strong { color:#3e4637; font:740 20px/1.35 var(--serif); }
.dlg-rules-intro p { margin:2px 0 0; font-size:13px; color:var(--folio-muted); }
.dlg-rule { padding:0; border-top:1px solid #a68d623c; }
.dlg-rule summary { display:flex; align-items:center; gap:11px; min-height:41px; list-style:none; color:#394c3e; font:700 16px/1.4 var(--serif); cursor:pointer; }
.dlg-rule summary::-webkit-details-marker { display:none; }
.dlg-rule summary::before { content:""; width:7px; height:7px; margin-left:2px; border-right:1.5px solid #856c40; border-bottom:1.5px solid #856c40; transform:rotate(-45deg); }
.dlg-rule[open] summary::before { transform:translateY(-2px) rotate(45deg); }
.dlg-rule ul { margin:0 0 8px; padding-left:22px; }.dlg-rule li { padding-left:2px; margin:3px 0 7px; }.dlg-rule li::marker { color:#a68550; }.dlg-rule b { font-weight:700; color:#433d2e; }
.dlg-rule p { margin-left:20px; }
.dlg-credits { margin:13px 0 0; color:var(--folio-muted); font-size:12px; line-height:1.55; }
.dlg-noble-intro { display:flex; align-items:center; gap:clamp(13px,3.6cqi,26px); margin-bottom:13px; }
.dlg-portrait {
  display:block; flex:none; width:clamp(68px,18.5cqi,112px); aspect-ratio:.83; padding:4px; border:1px solid #8d683d; border-radius:49% 49% 44% 44%;
  background:linear-gradient(125deg,#785e3b,#dfc68e 27%,#a68a5c 47%,#ecdbac 64%,#775832); box-shadow:0 2px 3px #5e492b55;
}
.dlg-portrait img { width:100%; height:100%; display:block; border:1px solid #9a835b; border-radius:inherit; object-fit:cover; object-position:50% 27%; }
.dlg-noble-intro h3 { margin:3px 0; color:#413127; font:740 clamp(23px,5.1cqi,32px)/1.3 var(--serif); }
.dlg-noble-intro p { margin:2px 0; color:var(--folio-muted); font-size:14px; }
.dlg-reward { display:inline-flex; align-items:center; gap:5px; color:#815c2b; font:680 14px/1.4 var(--serif); }
.dlg-reward svg { width:17px; height:17px; }
.dlg-need { border-top:1px solid #ae966745; font-size:14px; }
.dlg-need > span, .dlg-need strong { display:flex; align-items:center; gap:7px; }.dlg-need > span:first-child { flex:1; }.dlg-need strong { min-width:44px; justify-content:flex-end; font:650 16px var(--digits); }.dlg-need strong svg { width:14px; }
.dlg-need .dlg-need-marks { gap:4px; }.dlg-need-marks i { width:7px; height:7px; border:1px solid #9e875c; transform:rotate(45deg); }.dlg-need-marks .filled { background:var(--folio-accent); }.dlg-need.met strong { color:#36523e; }
.dlg-account-head { display:flex; align-items:center; gap:clamp(12px,4cqi,28px); }
.dlg-account-seal { flex:none; width:clamp(45px,12cqi,75px); aspect-ratio:1; object-fit:contain; filter:drop-shadow(0 1px 1px #55352457); }
.dlg-player-totals { flex:1; display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:5px; }
.dlg-player-totals span { display:flex; align-items:center; gap:3px; color:var(--folio-muted); font-size:12px; }
