}

/* A lacquered wooden profile and its printed windows remain legible at chip scale. */
.keep-pawn {
  display:block; position:relative; flex:none; width:auto; height:auto; aspect-ratio:var(--keep-proportion);
  pointer-events:none; filter:drop-shadow(-.025rem -.04rem .025rem #f8dfaa94) drop-shadow(.045rem .11rem .065rem #352818a8);
}
.keep-pawn::before, .keep-pawn::after {
  position:absolute; content:""; inset:1% 4% 3% 0; clip-path:var(--keep-profile);
}
.keep-pawn::before { transform:translate(5%,2%); background:var(--keep-edge); }
.keep-pawn::after {
  background:repeating-linear-gradient(6deg,transparent 0 2px,#f2d2a013 2px 2.6px,transparent 2.7px 4px),
    linear-gradient(116deg,var(--keep-light) 2%,var(--keep-paint) 38% 68%,var(--keep-shade) 97%);
}
.keep-windows {
  --keep-lattice:repeating-linear-gradient(90deg,var(--keep-print) 0 16%,transparent 16% 25%);
  position:absolute; inset:1% 4% 3% 0; z-index:1; pointer-events:none;
  background:var(--keep-lattice) 50% 21% / 19% 4% no-repeat,
    var(--keep-lattice) 50% 37% / 25% 4% no-repeat,
    var(--keep-lattice) 50% 53% / 35% 4% no-repeat,
    var(--keep-lattice) 50% 67% / 41% 3% no-repeat,
    var(--keep-lattice) 50% 88% / 58% 5% no-repeat;
}
.keep-windows::after {
  content:""; position:absolute; left:45%; bottom:10%; width:11%; height:10%; background:var(--keep-print);
  border-radius:50% 50% 0 0;
}
.keep-seat-1 > .keep-windows {
  background:var(--keep-lattice) 50% 19% / 24% 4% no-repeat,
    var(--keep-lattice) 50% 33% / 25% 4% no-repeat,
    var(--keep-lattice) 50% 48% / 28% 4% no-repeat,
    var(--keep-lattice) 50% 64% / 34% 4% no-repeat;
}
.keep-seat-1 > .keep-windows::after { width:15%; height:9%; left:42%; bottom:13%; }

.seat-prestige:has(.keep-stock) {
  grid-template-columns:max-content minmax(0,1fr) max-content; column-gap:.13rem;
}
.keep-stock {
  position:relative; justify-self:center; display:flex; justify-content:center; align-items:flex-end; gap:.07rem;
  max-width:100%; padding:0 .09rem .07rem; border:0; border-radius:.22rem; background:transparent;
