  width:clamp(7px,.85rem,17px); height:clamp(10px,1.23rem,25px); flex:0 1 auto;
}
.keep-socket::before {
  content:""; position:absolute; left:2%; right:2%; bottom:-2%; height:17%; border-radius:50%;
  background:#7e705849; box-shadow:0 1px #f3deb39c,inset 0 1px 1px #67523954;
}
.keep-stock .keep-pawn { height:100%; max-width:100%; }
.keep-stock.keep-ready { background:#d4b6664a; box-shadow:0 0 0 1px #94692e8c; }
.keep-stock:enabled::after { content:""; position:absolute; inset:-5px -2px; }
.keep-stock:enabled:hover { background:#d4b6664a; }

.keep-garrison {
  position:absolute; right:7%; top:41%; width:47%; height:32%; display:flex; justify-content:flex-end;
  align-items:flex-end; z-index:4; pointer-events:none; transform-origin:60% 65%;
  transition:transform .18s var(--lower-ease);
}
.keep-garrison .keep-pawn { height:100%; max-width:52%; }
.keep-garrison .keep-pawn + .keep-pawn { margin-left:-13%; }
.keep-garrison[data-count="3"] { right:4%; width:45%; height:29%; }
.keep-garrison[data-count="3"] .keep-pawn { max-width:47%; }
.keep-garrison .keep-pawn:nth-child(2) { top:3%; }
.keep-garrison .keep-pawn:nth-child(3) { top:6%; }
.market-card.is-chosen .keep-garrison { transform:translateY(calc(-1 * var(--piece-lift))) scale(1.06); }
.keep-commanding .market-card:not([data-keep-offer]) .card-stock { opacity:.63; }
.market-card[data-keep-offer] { --keep-ring:#e2bc73; }
.market-card:is([data-keep-offer="source"],[data-keep-offer="target"]) { --keep-ring:#eacb87; }
.market-card[data-keep-offer="remove"] { --keep-ring:#d88773; }
.market-card[data-keep-offer="selected"] { --keep-ring:#f8dd91; }
.market-card[data-keep-offer="conquer"] { --keep-ring:#fff0ac; }
.market-card[data-keep-offer]:not(.affordable) .card-stock { outline:clamp(1px,.12rem,2px) solid var(--keep-ring); outline-offset:1px; }
.market-card:is([data-keep-offer="selected"],[data-keep-offer="conquer"]):not(.affordable) .card-stock {
  box-shadow:var(--paper-edge),var(--paper-shadow),0 0 .65rem .18rem #f4d483a8;
}
