  max-width:100%; text-align:center;
}
.keep-instruction { font:600 max(.78rem,10px)/1.4 var(--sans); }
.keep-modes { display:inline-flex; justify-content:center; flex-wrap:wrap; gap:.23rem; }
.keep-mode {
  border:1px solid #9b8153; border-radius:.3rem; color:#473722; background:#f0e1be;
  padding:.16rem .43rem; font:650 max(.78rem,10px)/1.35 var(--sans); white-space:nowrap;
}
