.keep-mode:focus-visible, .keep-stock:focus-visible { outline:2px solid #b6742a; outline-offset:2px; }
@container tabletop (width < 780px) or (height < 480px) {
  .keep-garrison:not([data-count="1"])::after {
    content:attr(data-count); position:absolute; right:-7%; bottom:-12%; padding:0 .16em;
    border-radius:.2em; color:#fff5d4; background:#3b362df2; font:700 max(.75rem,8px)/1.08 var(--digits);
  }
  .keep-socket { width:clamp(5px,.75rem,10px); height:clamp(8px,1.13rem,16px); }
