/* A single-player viewpoint: the market has one reading direction and both
   players' inventories stay on their own edge when the turn changes. */
@media (orientation:portrait) {
  :root {
    --surface-w:100vw; --surface-h:100vh;
    font-size:clamp(8px,min(2.42vw,1.8vh),25px);
  }
  @supports (height:100dvh) {
    :root { --surface-w:100dvw; --surface-h:100dvh; }
  }
  #surface::before {
    /* Crop the landscape painting as a single image; buildings and ships stay upright. */
    background-position:var(--portrait-mat-focus,50%) center;
    background-size:cover;
  }
  #surface[data-mat="canal-arcade"] { --portrait-mat-focus:16%; }
  #surface[data-mat="night-port"] { --portrait-mat-focus:75%; }
  #surface[data-mat="stone-workshop"] { --portrait-mat-focus:82%; }
  #surface::after {
    border:clamp(3px,.85cqw,9px) solid transparent;
    border-image:var(--mat-image,var(--table-map)) 10 / 1 stretch;
  }
  #playfield, #playfield.with-orient, #playfield.silk-with-posts {
    --opponent-height:clamp(48px,10.5cqh,118px);
    --player-height:clamp(55px,12.2cqh,140px);
    --goals-height:clamp(33px,7.3cqh,85px);
    --rack-height:clamp(42px,9.6cqh,108px);
    --tool-size:clamp(29px,8cqw,54px);
    --action-space:clamp(43px,12.6cqw,84px);
    --middle-max:none;
    padding:1.7cqh 2.8cqw 1.9cqh;
    grid-template-columns:var(--tool-size) minmax(0,1fr) var(--tool-size);
    grid-template-rows:var(--opponent-height) var(--goals-height) minmax(0,1fr) var(--rack-height) var(--player-height);
    grid-template-areas:"right right right" ". nobles ." "market market market" "bank bank bank" "left left left";
    gap:clamp(3px,.82cqh,10px) clamp(3px,1.15cqw,12px);
  }
  #playfield.silk-with-posts {
    grid-template-rows:var(--opponent-height) var(--goals-height) clamp(28px,5.3cqh,62px) minmax(0,1fr) var(--rack-height) var(--player-height);
    grid-template-areas:"right right right" ". nobles ." "posts posts posts" "market market market" "bank bank bank" "left left left";
  }
  #playfield::before { inset:1.2% 1.9%; }
  #toolbar { display:contents; }
  #toolbar button { grid-row:2; width:var(--tool-size); height:var(--tool-size); align-self:center; justify-self:center; }
  #toolbar [data-open="rules"] { grid-column:1; }
  #toolbar [data-open="settings"] { grid-column:3; }
  #toolbar button::after { inset:-3px; }
  #toolbar .icon { width:47%; height:47%; }
  .noble-tray, .silk-city-tray { width:100%; height:90%; max-height:none; }
  .noble-tray { --noble-gap:clamp(3px,1.3cqw,13px); }
  .portrait-wrap {
    width:min(43%,calc(var(--goals-height) * .86)); height:auto; aspect-ratio:1; border-radius:50%;
  }
  .noble-name { font-size:clamp(8px,2.05cqw,18px); }
  .noble-needs { --pip:clamp(8px,2.26cqw,21px); gap:1px; }
  .silk-post-tray { width:98%; height:100%; max-height:none; }
  #playfield.silk-with-posts:has(.silk-city-tray) .silk-post-vignette img {
    opacity:.65; filter:saturate(.76);
  }
  #playfield.silk-with-posts:has(.silk-city-tray) .silk-post-caption .silk-pip {
    color:#30291e; font-size:clamp(10px,2.55vw,17px);
  }
  #playfield.silk-with-posts:has(.silk-city-tray) .silk-post-caption .silk-pip > :is(.gicon,.icon) {
    width:clamp(10px,2.65vw,17px);
  }
  .silk-city-score {
    padding:1px 3px; border-radius:2px; background:#30291ceb; box-shadow:inset 0 0 0 1px #d4b175;
  }
  .silk-city-score b { font-size:clamp(12px,2.85vw,20px); }

  #market-table { width:100%; }
  .development-market {
    --piece-lift:clamp(6px,1.72cqw,14px);
    --row-gap:calc(var(--piece-lift) + clamp(4px,1.3cqw,12px));
    --column-gap:clamp(4px,1.85cqw,18px);
    --card-width:min(calc((100cqw - 4 * var(--column-gap) - 4px) / 5),calc((100cqh - 2 * var(--row-gap) - var(--piece-lift) - 4px) / 3 * var(--card-ratio)));
    padding-top:var(--piece-lift);
  }
  :is(.market-row,.dlg-owned-card) .card-points { font-size:min(1.5rem,19cqh); }
  :is(.market-row,.dlg-owned-card) .card-price { --pip-limit:min(1.32rem,14.5cqh); }
  :is(.market-row,.dlg-owned-card) .card-bonus { width:25cqw; height:25cqw; }

  /* Six face-up cards still fit side by side. Both draw piles keep their
     cover artwork in the narrow column on the left, one above the other. */
  .development-market[data-orient="true"] {
    --column-gap:clamp(2px,1.05cqw,9px);
    --wing-gap:clamp(4px,1.85cqw,15px);
    --deck-track:clamp(22px,7.8cqw,66px);
    --card-width:min(calc((100cqw - var(--deck-track) - 6 * var(--column-gap) - var(--wing-gap) - 3px) / 6),calc((100cqh - 2 * var(--row-gap) - var(--piece-lift) - 4px) / 3 * var(--card-ratio)));
  }
  .development-market[data-orient="true"] .market-row {
    grid-template-columns:var(--deck-track) repeat(4,var(--card-width)) calc(var(--card-width) + var(--wing-gap)) var(--card-width);
    grid-template-rows:repeat(2,calc(var(--card-width) / var(--card-ratio) / 2));
    row-gap:0;
  }
  .development-market[data-orient="true"] .market-row > :not(.deck) { grid-row:1 / span 2; }
  .development-market[data-orient="true"] .market-row > :nth-child(2) { grid-column:2; }
  .development-market[data-orient="true"] .market-row > :nth-child(3) { grid-column:3; }
  .development-market[data-orient="true"] .market-row > :nth-child(4) { grid-column:4; }
  .development-market[data-orient="true"] .market-row > :nth-child(5) { grid-column:5; }
  .development-market[data-orient="true"] .market-row > :nth-child(6) { grid-column:6; }
  .development-market[data-orient="true"] .market-row > :nth-child(7) { grid-column:7; }
  .development-market[data-orient="true"] .deck {
    grid-column:1; justify-self:center; width:min(100%,calc(var(--card-width) * .44));
  }
  .development-market[data-orient="true"] .deck[data-pile="base"] { grid-row:1; }
  .development-market[data-orient="true"] .deck[data-pile="orient"] { grid-row:2; }
  .development-market[data-orient="true"] .deck::after {
    /* Give each small cover its whole half-column as a stationary hit target. */
    inset:auto; top:50%; left:50%; width:128%; height:113%;
    transform:translate(-50%,-50%); pointer-events:auto;
    opacity:0; box-shadow:none; background:none;
  }
  .development-market[data-orient="true"] .deck-print { font-size:min(24cqw,1.1rem); top:56%; }
  .development-market[data-orient="true"] .deck-roman { top:1px; left:2px; font-size:min(28cqw,1rem); }
  .development-market[data-orient="true"] .deck-count { font-size:0; top:auto; right:0; bottom:0; padding:0 1px; }
  .development-market[data-orient="true"] .deck-count b { font-size:min(30cqw,1rem); }
  .development-market[data-orient="true"] .deck-pips { display:none; }
  .with-orient :is(.market-row,.dlg-owned-card) .card-bonus { width:26cqw; height:26cqw; }

  #bank-station {
    justify-self:end; width:calc(100% - var(--action-space) - 1.4cqw); padding:.22rem .08rem .24rem;
  }
