  #turn-controls, #playfield.silk-with-posts #turn-controls {
    grid-area:bank; width:var(--action-space); justify-self:start; grid-template-columns:1fr; column-gap:0;
  }
  #action-anchor, #surface[data-seat="1"] #action-anchor {
    grid-column:1; width:min(100%,95cqh);
  }
}

/* Tall phones can spend their spare height on bigger face cards and separate tiers. */
@media (max-aspect-ratio:2/3) {
  .development-market { align-content:space-evenly; }
  .development-market[data-orient="false"] {
