(() => {
  "use strict";
  const root = document.documentElement;
  const preference = "splendor-renaissance.fullscreen";
  let autoEnter = true, triedOnEntry = false, pending = null;
  try { autoEnter = localStorage.getItem(preference) !== "off"; } catch { /* File viewers may disable storage. */ }

  function active() {
    return !!(document.fullscreenElement || document.webkitFullscreenElement ||
      document.webkitCurrentFullScreenElement || document.webkitIsFullScreen);
  }

  function sync() {
    const on = active(), action = on ? "exit" : "enter";
    for (const button of document.querySelectorAll("button[data-fullscreen]")) {
      if (button.dataset.fullscreen !== action) {
        button.dataset.fullscreen = action;
        button.innerHTML = BoardGraphics.icon(on ? "contract" : "expand") + "<span>" + (on ? "退出全屏" : "进入全屏") + "</span>";
      }
      button.setAttribute("aria-disabled",String(!!pending));
    }
  }

  function note(button, message) {
    const line = button?.closest("#game-cover, .dlg-panel")?.querySelector("[data-screen-note]");
    if (line) line.textContent = message;
  }

  function settle(request) {
    if (pending !== request) return;
    clearTimeout(request.timer);
    pending = null;
    if (request.button) {
      if (active() === request.enter) {
        autoEnter = request.enter;
        try {
          if (autoEnter) localStorage.removeItem(preference);
          else localStorage.setItem(preference,"off");
        } catch { /* Retain the choice for this session. */ }
      } else {
        note(request.button, request.enter ? "当前打开方式未允许全屏。可用系统浏览器直接打开游戏后重试。" : "可用系统返回键或 Esc 退出全屏。");
      }
    }
    sync();
  }

  function change(enter, button) {
    if (pending || active() === enter) return;
    const method = enter ? root.requestFullscreen || root.webkitRequestFullscreen || root.webkitRequestFullScreen :
      document.exitFullscreen || document.webkitExitFullscreen || document.webkitCancelFullScreen;
    const enabled = root.requestFullscreen ? document.fullscreenEnabled : document.webkitFullscreenEnabled;
    note(button,"");
    const request = {enter, button, timer:0};
    pending = request;
    if (!method || (enter && enabled === false)) { settle(request); return; }
    sync();
    try {
      // Call the native method inside the tap handler, while user activation is still available.
      const result = enter && method === root.requestFullscreen ? root.requestFullscreen({navigationUI:"hide"}) :
        method.call(enter ? root : document);
      if (result?.then) result.then(() => settle(request), () => settle(request));
      else if (active() === enter) settle(request);
      else request.timer = setTimeout(() => settle(request), 1800); // Older WebKit reports completion through events.
    } catch { settle(request); }
  }

  function onEntry() {
    if (!autoEnter || triedOnEntry || !matchMedia("(pointer: coarse)").matches || navigator.userActivation?.isActive === false) return;
    triedOnEntry = true;
    change(true);
  }

  document.addEventListener("click",event => {
    const button = event.target.closest?.("button[data-fullscreen]");
    if (button) {
      triedOnEntry = true;
      change(!active(),button);
    }
  });
  for (const name of ["fullscreenchange","webkitfullscreenchange"]) {
    document.addEventListener(name,() => {
      for (const line of document.querySelectorAll("[data-screen-note]")) line.textContent = "";
      if (pending && active() === pending.enter) settle(pending);
      else sync();
    });
  }
  for (const name of ["fullscreenerror","webkitfullscreenerror"]) {
    document.addEventListener(name,() => { if (pending?.timer) settle(pending); });
  }
  document.addEventListener("visibilitychange",() => { if (!document.hidden) sync(); });
  window.addEventListener("pageshow",sync);
  sync();
  globalThis.BoardFullscreen = Object.freeze({onEntry,sync});
})();

/* Splendor: The Silk Road, 2025 Space Cowboys rules (two players).
   Rules and pictured powers: https://cdn.svc.asmodee.net/production-spacecowboys/uploads/2025/10/SCSPL03EN_SILKROAD_RULES_20241002_WEB.pdf
   City face pairs: https://bodoge.hoobby.net/games/splendor-silk-road/instructions/53066
   Madrid printing correction: https://forum.boardgamearena.com/viewtopic.php?t=42978
   Box contents and photographed noble: https://www.spacecowboys-games.com/game/the-silk-road/
   Noble identity: https://cdn.svc.asmodee.net/production-spacecowboys/uploads/2026/08/2606_Splendor_nobles_doc_EN.pdf */
(function (root) {
  "use strict";

  // Each physical tile has two faces. Numbers are prestige, five specific card
  // colors (white, blue, green, red, black), then cards of one different color.
  const tiles = [
    ["amboise", "昂布瓦斯", [13,0,0,3,0,4,0], [13,0,0,0,4,3,0]],
    ["delhi", "德里", [13,0,3,4,0,0,0], [14,2,2,2,2,2,0]],
