      node.classList.remove("has-advice");
      delete node.dataset.advice;
      node.removeAttribute("aria-describedby");
      halo?.remove();
      shown.delete(node);
    }
    for (const [node,count] of targets) {
      if (!shown.has(node)) {
        const stack = node.querySelector(".chip-stack, .wallet-stack");
        let halo = null;
        if (stack) {
          halo = document.createElement("span");
          halo.className = "advice-halo";
          halo.setAttribute("aria-hidden","true");
          stack.append(halo);
        }
        node.classList.add("has-advice");
        node.setAttribute("aria-describedby","advice-status");
        shown.set(node,halo);
      }
      const kind = recommendation.action?.type || "unavailable";
      if (node.dataset.advice !== kind) node.dataset.advice = kind;
      const halo = shown.get(node);
      if (halo) {
        const resting = halo.parentElement.querySelectorAll("img:not(.is-raised):not(.is-returning)");
        halo.style.setProperty("--halo-depth",resting.length ? resting[resting.length-1].dataset.layer : 0);
        const dots = count > 1 ? count : 0;
        if (halo.childElementCount !== dots)
          halo.replaceChildren(...Array.from({length:dots},()=>document.createElement("i")));
      }
    }
    const status = document.getElementById("advice-status");
    if (status.textContent !== description) status.textContent = description;
  }
  function clear() {
    recommendation = null;
    display(new Map(),"");
  }
  function set(state,action) { recommendation = {state,action}; }

  function draw(bank,card,returned,visitor,reading) {
    if (!recommendation) return;
    const {state,action} = recommendation;
    if (Table.state !== state || Table.mode !== "solo" || Table.computerTurn || Table.passingTurn || !Table.options.assist) {
      clear(); return;
    }
    const targets = new Map();
    const mark = (selector,count = 1) => {
      const node = find(selector);
      if (node) targets.set(node,count);
    };
    const hand = ReserveHand.owner;
    const confirm = () => mark("#turn-action");
    let text = "";
    if (reading || (hand !== null && !(hand === state.active && action?.type === "buy" && state.players[hand].reserved.includes(action.id)))) {
      display(targets,""); return;
    }
    if (!action) {
      mark('[data-open="settings"]');
      text = "此局面暂时无法取得困难棋手建议，可继续自行行动。";
