      const take = action.type === "take";
      const picked = (take ? bank : returned)?.tokens || empty;
      if (!card && !picked.some((n,c)=>n > action.tokens[c])) {
        const names = [];
        action.tokens.forEach((n,c) => {
          if (!n) return;
          names.push(colors[c]+n+"枚");
