      confirm(); text = "跳过这个回合。";
    } else if (!bank && (action.type === "reserve" || action.type === "buy")) {
      const held = state.players[0].reserved.includes(action.id);
      const reserve = action.type === "reserve";
      let piece = '.market-card[data-value="'+action.id+'"]';
      if (held) piece = hand === null ? "#seat-0 .holdings-button" : '[data-hand-card="'+action.id+'"]';
      if (action.tier) piece = '.deck[data-pile="base"][data-value="'+action.tier+'"]';
      const selectionMatches = card && card.type === action.type &&
        (action.id ? card.id === action.id : card.tier === action.tier);
      const name = action.id ? Table.artName(action.id) : ["","Ⅰ","Ⅱ","Ⅲ"][action.tier]+"级牌堆";
      text = (reserve ? "预留" : "购买")+name+"。";
      if (selectionMatches && action.pay && card.pay.slice(0,5).some((n,c)=>n < action.pay[c])) {
        // The player chose a different gold substitution. Respect that payment draft.
        display(targets,""); return;
