  const bankPile = color => select('#bank .bank-pile[data-value="' + color + '"]');
  const wallet = (player, color) => seat(player)?.querySelector('[data-token-color="' + color + '"]');
  const bonusPile = (player, color) => seat(player)?.querySelector('[data-bonus-color="' + color + '"]');
  const mix = (a, b, t) => a + (b - a) * t;
  const clamp = (x, min, max) => Math.min(max, Math.max(min, x));

  function deckTop(tier, pile = "base") {
    const stack = select('.deck[data-pile="' + pile + '"][data-value="' + tier + '"]');
    return stack?.querySelector(".deck-top") || stack;
  }

  function heldSpot(player, id) {
    const index = Table.state.players[player].reserved.indexOf(id);
    const slot = seat(player)?.querySelectorAll(".reserve-fan > i.held")[index];
    return slot?.querySelector(".pocket-paper") || slot || null;
  }

  function supported() {
    return !document.hidden && !motionPreference?.matches && !!document.body &&
      typeof globalThis.Element?.prototype.animate === "function";
  }

  // The board and the fixed flight layer share screen axes in both orientations.
  function place(node) {
    if (!node) return null;
    const r = node.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return {x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width, h: r.height};
  }

  function overlay() {
    if (!layer) {
      layer = document.createElement("div");
      layer.setAttribute("aria-hidden", "true");
      layer.dataset.boardMotion = "";
      layer.style.cssText = "position:fixed;inset:0;z-index:70;overflow:hidden;pointer-events:none;user-select:none;contain:strict";
      document.body.appendChild(layer);
    }
    return layer;
  }

  function mount(node) {
    (batch || overlay()).appendChild(node);
  }

  function writeBatch(write) {
    const fragment = document.createDocumentFragment();
    batch = fragment;
    try { write(); } finally {
      batch = null;
      if (fragment.childNodes.length) overlay().appendChild(fragment);
    }
  }

  function restore(run) {
    for (const saved of run.hidden) {
      if (holders.get(saved.node) !== run) continue;
      holders.delete(saved.node);
      if (saved.chip) { saved.node.classList.remove("in-transit"); continue; }
      if (saved.value) saved.node.style.setProperty("visibility", saved.value, saved.priority);
      else saved.node.style.removeProperty("visibility");
    }
    run.hidden.length = 0;
  }

  function queueChipCounts() {
    if (chipCountsQueued) return;
    chipCountsQueued = true;
    queueMicrotask(() => {
      chipCountsQueued = false;
      globalThis.Table?.refreshChipCounts?.();
    });
  }

  function finish(run, landed = false) {
    if (!run || flights.get(run.key) !== run) return;
    flights.delete(run.key);
    // Release the existing chip or exchange a moving paper/portrait for its destination.
    for (const a of run.animations) { a.onfinish = null; a.cancel(); }
    for (const n of run.nodes) n.remove();
    restore(run);
    if (run.kind === "chip") {
      delete run.destination.dataset.piece;
      queueChipCounts();
      if (landed) seatChip(run);
    }
    if (run.receipt) finishBonus(run, landed);
    if (run.points) {
      const label = Table.refreshScore(run.scorer);
      if (landed && label && supported())
        track(label, [{transform:"perspective(80px) rotateX(-26deg) scale(1.08)"}, {transform:"none"}], 150);
    }
    if (landed && run.kind === "noble" && Table.options.sound)
      BoardFeedback.play("noble-land",true);
    if (!flights.size) {
      layer?.remove();
      layer = null;
    }
    run.onSettled?.();
  }

  function conceal(run, node) {
    if (!node || holders.get(node) === run) return;
    const prior = holders.get(node);
    if (prior) finish(prior);
    const chip = run.kind === "chip" && node.matches("img.chip, img.wallet-chip");
    run.hidden.push({node, value: node.style.getPropertyValue("visibility"),
      priority: node.style.getPropertyPriority("visibility"), chip});
    holders.set(node, run);
    if (chip) node.classList.add("in-transit");
    if (!chip) node.style.setProperty("visibility", "hidden", "important");
  }

  function cancelAccent(a) {
    if (!a) return;
    accents.delete(a);
    a.onfinish = null;
    a.cancel();
  }

  function clear() {
    epoch++;
    for (const run of Array.from(flights.values())) finish(run);
    for (const a of Array.from(accents)) cancelAccent(a);
  }

  function track(node, frames, duration, delay = 0) {
    const a = node.animate(frames, {duration, delay, fill: "both"});
    accents.add(a);
    a.onfinish = () => cancelAccent(a);
    return a;
  }

  function releaseChip(coin) {
    cancelAccent(chipAccents.get(coin));
    chipAccents.delete(coin);
  }

  function startRun(key, find, kind, destination, maskDestination = true) {
    finish(flights.get(key));
    if (!destination) return null;
    const run = {key, find, kind, destination, maskDestination, hidden: [], nodes: [], animations: [], main: null};
    flights.set(key, run);
    if (maskDestination) conceal(run, destination);
    return run;
  }

  function creditOnArrival(run, player, points) {
    if (!points) return;
    run.scorer = player;
    run.points = points;
    Table.refreshScore(player);
  }

  function pointsInFlight(player) {
    let pending = 0;
    for (const run of flights.values()) if (run.scorer === player) pending += run.points;
    return pending;
  }

  function reconcile() {
    // The incremental renderer normally retains destination nodes; also support a redraw of an entire station.
    for (const run of Array.from(flights.values())) {
      if (run.destination.isConnected) continue;
      if (run.kind === "chip") { finish(run); continue; }
      const replacement = run.find();
      if (!replacement) { finish(run); continue; }
      restore(run);
      run.destination = replacement;
      if (run.maskDestination) conceal(run, replacement);
    }
  }

  function takeSource(key, regular, releases) {
    const older = flights.get(key);
    if (!older) return regular;
    releases.add(older);
    if (older.kind === "chip" && older.travel && regular) {
      const {path, duration} = older.travel;
      const t = clamp((older.clock.currentTime || 0) / duration, 0, 1);
      const dt = .002, a = Math.max(0, t - dt), b = Math.min(1, t + dt);
      const start = chipPoint(path, a), end = chipPoint(path, b);
      const elapsed = (b - a) * duration;
      return {...regular, vx:(end.x - start.x) / elapsed, vy:(end.y - start.y) / elapsed,
        vw:(end.w - start.w) / elapsed, vh:(end.h - start.h) / elapsed};
    }
    return place(older.main) || regular;
  }

  // Only accents use independent timing. Every physical flight uses one clock and one easing over its full path.
  function reject(node) {
    if (!node?.isConnected || typeof node.animate !== "function" || document.hidden) return;
    try {
      for (const old of rejections.get(node) || []) cancelAccent(old);
      const current = [];
      rejections.set(node, current);
      const run = (part, frames, duration) => {
        const animation = track(part, frames, duration);
        current.push(animation);
        if (part.matches(".chip,.wallet-chip")) chipAccents.set(part, animation);
      };
      const stack = node.querySelectorAll("img.wallet-chip[data-layer], img.chip[data-layer]");
      const art = stack[stack.length - 1] || node.querySelector(".card-stock, .deck-top, .card-face, .wallet-stack, .chip, .deed, .action-piece");
      // Keep the control itself stationary; only the noninteractive face moves in board coordinates.
      const parts = art ? [art] : Array.from(node.children).filter(child =>
        !child.matches("button, a, input, select, textarea, [tabindex]")
      );
      if (motionPreference?.matches || !parts.length) {
        const base = getComputedStyle(node).filter;
        const pressed = (base === "none" ? "" : base + " ") + "brightness(.84)";
        run(node, [{filter: pressed}, {filter: pressed}], 135);
        return;
      }
      const distance = Math.max(1.4, Math.min(3, (node.offsetWidth || place(node)?.w || 32) * .042));
      const beats = [[0, 0, 0], [.20, -1, -.78], [.46, .77, .56], [.71, -.29, -.21], [1, 0, 0]];
      const frames = beats.map(([offset, shift, angle]) => ({
        offset, composite: "add", translate: (distance * shift) + "px 0px", rotate: angle + "deg",
        easing: "cubic-bezier(.24,.52,.32,1)"
      }));
      for (const part of parts) run(part, frames, 205);
      if (node.matches(".deck") && !node.querySelector(".deck-top")) {
        // The cover is painted on the deck button; slide its ink along with the separate gold furniture.
        run(node, beats.map(([offset, shift]) => ({
          offset, backgroundPositionX: "calc(50% + " + (distance * shift) + "px)",
          easing: "cubic-bezier(.24,.52,.32,1)"
        })), 205);
      }
    } catch { /* Feedback must never interrupt a turn. */ }
  }

  function handoff(player) {
    if (!supported()) return;
    cancelAccent(activeStamps.get(seat(1 - player)?.querySelector(".seat-seal")));
    const direction = player ? 1 : -1;
    const stamps = [seat(player)?.querySelector(".seat-seal"), select("#turn-action .action-piece")];
    stamps.forEach((stamp, index) => {
      if (!stamp) return;
      const drift = direction * (index ? 2.1 : .7);
      cancelAccent(activeStamps.get(stamp));
      const animation = track(stamp, [
        {translate: "0px 0px", scale: "1", rotate: "0deg", easing: "ease-out"},
        {offset: .28, translate: drift + "px clamp(-4.2px,-10%,-2px)", scale: "1.035",
          rotate: (direction * .9) + "deg", easing: "cubic-bezier(.47,0,.78,.62)"},
        {offset: .76, translate: "0px .35px", scale: ".993", rotate: "0deg", easing: "ease-out"},
        {translate: "0px 0px", scale: "1", rotate: "0deg"}
      ], index ? 267 : 285, index ? 26 : 0);
      activeStamps.set(stamp, animation);
    });
  }

  const bankKey = (color, level) => "bank/" + color + "/" + level;
  const walletKey = (p, color, level) => "wallet/" + p + "/" + color + "/" + level;
  const handKey = (p, id) => "hand/" + p + "/" + id;
  const cardKey = id => "market/" + id;
  const chipNode = (well, level) => well?.querySelector('img[data-layer="' + level + '"]');

  function visualAction(previous, next, action) {
    const p = previous.active, before = previous.players[p], after = next.players[p];
    const reserved = after.reserved.find(id => !before.reserved.includes(id));
    if (action.type === "reserve" && !reserved) return {type:"select"};
    if (action.type !== "effect") return action;
    const step = previous.flow?.queue[0];
    if (step?.kind === "reserve-two" && reserved) return {type:"reserve", tier:step.tier, pile:step.pile};
    if (step?.kind === "post-token") return {type:"take", tokens:after.tokens.map((n,i) => Math.max(0,n-before.tokens[i]))};
    const gained = after.cards.find(id => !before.cards.includes(id));
    if (gained) return {type:"buy",id:gained};
    return {type:"select"};
  }

  function chipWell(node) {
    const well = place(node?.parentElement);
    if (!well) return null;
    const ratio = node.naturalHeight ? node.naturalWidth / node.naturalHeight : 1;
    return {...well, inkW:Math.min(well.w, ratio * well.h), inkH:Math.min(well.h, well.w / ratio)};
  }

  function chipMeasures(nodes, well = chipWell(nodes.find(Boolean))) {
    return nodes.map(node => {
      const box = place(node);
      if (box && well) { box.w *= well.inkW / well.w; box.h *= well.inkH / well.h; }
      return box;
    });
  }

  function changes(previous, action, next) {
    const p = previous.active, before = previous.players[p].tokens;
    if (next) return next.players[p].tokens.map((n, i) => n - before[i]);
    if (action.type === "take" || action.type === "discard") {
      return before.map((_, i) => (action.tokens[i] || 0) * (action.type === "take" ? 1 : -1));
    }
    if (action.type === "reserve") return [0, 0, 0, 0, 0, Math.min(1, previous.bank[5])];
    if (action.type === "buy") {
      const pay = action.pay || (() => {
        const normal = Splendor.payment(previous, action.id, p);
        return normal.colored.concat(normal.gold);
      })();
      return pay.map(n => -n);
    }
    return [];
  }

  function captureGroups(previous, action, next, releases) {
    const p = previous.active;
    const marked = {take: "is-raised", discard: "is-returning", buy: "is-paying-chip"}[action.type];
    const groups = [];
    changes(previous, action, next).forEach((amount, color) => {
      if (!amount) return;
      const incoming = amount > 0;
      const source = incoming ? bankPile(color) : wallet(p, color);
      const all = Array.from(source?.querySelectorAll("img[data-layer]") || []).reverse();
      const preferred = marked ? all.filter(n => n.classList.contains(marked)) : [];
      const top = preferred.concat(all.filter(n => !preferred.includes(n))).slice(0, Math.abs(amount));
      // Ship the subset bottom first. The original top coin also lands on top of the new stack.
      top.sort((a, b) => Number(a.dataset.layer) - Number(b.dataset.layer));
      const measured = chipMeasures(top);
      const coins = top.map((node, i) => {
        const level = Number(node.dataset.layer);
        const key = incoming ? bankKey(color, level) : walletKey(p, color, level);
        return takeSource(key, measured[i], releases);
      });
      if (coins.length) groups.push({color, incoming, coins});
    });
    return groups;
  }

  function smooth(t) {
    const u = clamp(t, 0, 1);
    return u * u * (3 - 2 * u);
  }

  function centerAt(path, t) {
    const {from, to, arc} = path;
    const bow = 4 * t * (1 - t);
    const height = arc * bow;
    const x = mix(from.x, to.x, t);
    const y = mix(from.y, to.y, t) - height;
    return {x, y, bow};
  }

  function pose(path, t) {
    const {from, to, tilt} = path;
    const {x, y, bow} = centerAt(path, t);
    const size = 1 + bow * .012;
    const sx = mix(1, to.w / from.w, t) * size;
    const sy = mix(1, to.h / from.h, t) * size;
    const roll = mix(from.roll || 0, to.roll || 0, t);
    return "translate3d(" + x + "px," + y + "px,0) rotate(" + (roll + tilt * bow) + "deg) scale(" +
      sx + "," + sy + ") translate(-50%,-50%)";
  }

  function poses(path) {
    // Linear interpolation between samples approximates the shallow quadratic to subpixel precision.
    return Array.from({length: 13}, (_, i) => ({offset: i / 12, transform: pose(path, i / 12)}));
  }

  function geometry(from, to, sharedArc, tilt = 0) {
    const distance = Math.hypot(to.x - from.x, to.y - from.y);
    return {from, to, arc: sharedArc ?? clamp(distance * .034, 2, 15), tilt};
  }

  function paperDuration(distance, shortSide) {
    return Math.round(clamp(268 + distance / shortSide * 125, 282, 403));
  }

  function animate(run, node, frames, duration, delay) {
    const a = node.animate(frames, {duration, delay, easing: curve, fill: "both"});
    run.animations.push(a);
    // Animations assembled in this task start together on the next presentation tick.
    return a;
  }

  function sheet(node, from) {
    Object.assign(node.style, {position: "absolute", left: "0", top: "0", width: from.w + "px", height: from.h + "px",
      display: "block", boxSizing: "border-box", transformOrigin: "0 0", pointerEvents: "none", willChange: "transform"});
    return node;
  }

  function image(src) {
    const img = document.createElement("img");
    img.alt = "";
    img.draggable = false;
    img.src = src;
    img.style.objectFit = "fill";
    return img;
  }

  function send(run, node, path, duration, delay) {
    run.main = sheet(node, path.from);
    run.main.dataset.piece = run.kind;
    run.nodes.push(run.main);
    mount(run.main);
    const a = animate(run, run.main, poses(path), duration, delay);
    a.onfinish = () => finish(run, true);
  }
  function measureArrivals(snapshot, previous, next) {
    const p = previous.active;
    const groups = [];
    snapshot.groups.forEach(({color, incoming, coins}) => {
      const count = incoming ? next.players[p].tokens[color] : next.bank[color];
      const startLevel = count - coins.length;
      const findWell = () => incoming ? wallet(p, color) : bankPile(color);
      const spot = findWell();
      const nodes = coins.map((_, i) => chipNode(spot, startLevel + i));
      const well = chipWell(nodes.find(Boolean));
      if (!well) return;
      const targets = chipMeasures(nodes, well);
      const sample = coins.findIndex((c, i) => c && targets[i]);
      if (sample < 0) return;
      const distance = Math.hypot(targets[sample].x - coins[sample].x, targets[sample].y - coins[sample].y);
      const arc = clamp(distance * .054, 5, 23);
      // Distance is measured in visible coin diameters. A long trip to a small
      // purse therefore gets more frames than a short trip across the tray.
      const startWidth = coins[sample].w, endWidth = targets[sample].w;
      const ratio = endWidth / startWidth;
      const meanWidth = Math.abs(ratio - 1) < .005 ? (startWidth + endWidth) / 2 :
        (endWidth - startWidth) / Math.log(ratio);
      const diameters = distance / (.91 * meanWidth);
      groups.push({color, incoming, coins, targets, nodes, startLevel, findWell, well, arc,
        duration:Math.round(Math.max(260, diameters * 47))});
    });
    return groups;
  }

  // Ease into and out of a steady middle speed. Integrating a cosine ramp
  // gives the flat middle a smooth velocity and acceleration at either end.
  function chipProgress(t) {
    const ramp = .14, end = Math.min(t, 1 - t);
    if (end >= ramp) return (t - ramp / 2) / (1 - ramp);
    const distance = (end - ramp / Math.PI * Math.sin(Math.PI * end / ramp)) / (2 * (1 - ramp));
    return t <= .5 ? distance : 1 - distance;
  }

  function chipPoint(path, t) {
    const {from, to, arc} = path;
    const progress = chipProgress(t);
    // Keep speed consistent to the eye as the same chip changes apparent size.
    const advance = path.logRatio ? Math.expm1(path.logRatio * progress) / path.ratioChange : progress;
    // A seated chip starts and finishes level. On an immediate return, the first
    // part of the new path keeps the incoming velocity, including its change in size.
    const bow = (4 * t * (1 - t)) ** 2, lift = arc * bow;
    const ms = t * path.duration;
    const carry = from.vx === undefined ? 0 : ms * Math.max(0, 1 - ms / 110) ** 3;
    const size = 1 + .009 * bow;
    return {x:mix(from.x,to.x,advance) + (from.vx || 0) * carry,
      y:mix(from.y,to.y,advance) - lift + (from.vy || 0) * carry,
      w:mix(from.w,to.w,advance) * size + (from.vw || 0) * carry,
      h:mix(from.h,to.h,advance) * size + (from.vh || 0) * carry, bow, lift};
  }

  function chipFrames(path, well, withShadow) {
    const chip = [], shadow = [];
    const transform = (x,y,sx,sy) => "translate3d(" + x + "px," + y + "px,0) scale(" + sx + "," + sy + ")";
    const stops = Array.from({length:33}, (_, i) => i / 32);
    if (path.from.vx !== undefined) stops.splice(1, 0, 2 / path.duration, 6 / path.duration);
    for (const t of stops) {
      const point = chipPoint(path,t);
      const x = point.x - well.x, y = point.y - well.y;
      const sx = point.w / well.inkW, sy = point.h / well.inkH;
      // The ink is seated on a pivot at 76% of the image height. Keep that
      // native pivot and raster layer even at the last subpixel of travel.
      chip.push({offset:t, transform:transform(x, y - .26 * well.h * (1 - sy), sx, sy)});
      if (withShadow) {
        const size = .82 + .27 * point.bow;
        shadow.push({offset:t, opacity:point.bow * .8,
          transform:transform(x, y + .88 * point.lift, point.w * size / well.w, point.h * size / well.h)});
      }
    }
    return {chip, shadow};
  }

  function seatChip(run) {
    const coin = run.destination;
    if (coin.isConnected && !coin.matches(".is-contacted,.is-raised,.is-returning,.is-paying-chip")) {
      const arrival = track(coin, [
        {translate:"0 0", scale:"1 1", easing:"cubic-bezier(.16,.62,.42,1)"},
        {offset:.31, translate:"0 " + run.depth + "px", scale:"1.012 .975", easing:"cubic-bezier(.28,.10,.32,1)"},
        {translate:"0 0", scale:"1 1"}
      ], 82);
      chipAccents.set(coin, arrival);
    }
  }

  function showCoins(groups, p, times) {
    for (const group of groups) {
      const {color, incoming, coins, targets, nodes, startLevel, findWell, well, arc, duration} = group;
      let landed = false;
      coins.forEach((from, i) => {
        const to = targets[i];
        if (!from || !to) return;
        const level = startLevel + i;
        const key = incoming ? walletKey(p, color, level) : bankKey(color, level);
        const run = startRun(key, () => chipNode(findWell(), level), "chip", nodes[i]);
        if (!run) return;
        const ratio = to.w / from.w;
        const path = {from, to, arc, duration, ratioChange:ratio - 1,
          logRatio:Math.abs(ratio - 1) < .005 ? 0 : Math.log(ratio)};
        const frames = chipFrames(path, well, !landed);
        const move = (node, keyframes) => {
          // Let coins and shadows start on the same presentation tick, after setup finishes.
          const a = node.animate(keyframes, {duration, easing:"linear", fill:"both"});
          run.animations.push(a);
          return a;
        };
        if (!landed) {
          const shadow = document.createElement("span");
          shadow.className = "flight-shadow";
          shadow.dataset.boardShadow = "packet";
          run.destination.parentNode.appendChild(shadow);
          run.nodes.push(shadow);
          move(shadow, frames.shadow);
        }
        // Move the destination's actual bitmap, in its own well. It keeps the
        // same texture, contain-fit, and pixel grid all the way through landing.
        run.main = run.destination;
        run.main.dataset.piece = "chip";
        run.travel = {path, duration};
        run.depth = clamp(to.h * .018, .32, .85);
        run.clock = move(run.main, frames.chip);
        run.clock.onfinish = () => finish(run, true);
        landed = true;
      });
      if (landed) record(times, "chip", duration);
    }
    if (groups.length) queueChipCounts();
  }

  function fitFace(node) {
    Object.assign(node.style, {position: "absolute", inset: "0", width: "100%", height: "100%", margin: "0",
      visibility: "visible", transform: "none", translate: "none", rotate: "none", scale: "none", animation: "none",
      transition: "none", pointerEvents: "none"});
    node.removeAttribute("id");
    return node;
  }

  function copyFront(face) {
    if (!face) return null;
    const copy = fitFace(face.cloneNode(true));
    const hint = face.closest(".market-card[data-advice]")?.dataset.advice;
    if (hint || face.closest('.affordable,[data-expansion-offer="free"]')) copy.classList.add("gilded-in-flight");
    if (hint) copy.dataset.advice = hint;
    if (face.closest(".is-chosen")) copy.classList.add("is-chosen");
    return copy;
  }

  function symbolBox(node) {
    const box = place(node);
    if (!box) return null;
    const view = node.viewBox?.baseVal;
    if (view?.width && view.height) {
      const m = node.getScreenCTM?.();
      if (m) {
        const cx = view.x + view.width / 2, cy = view.y + view.height / 2;
        return {x: m.a * cx + m.c * cy + m.e, y: m.b * cx + m.d * cy + m.f,
          w: view.width * Math.hypot(m.a, m.b), h: view.height * Math.hypot(m.c, m.d),
          roll: Math.atan2(m.b, m.a) * 180 / Math.PI};
      }
      const ratio = view.width / view.height;
      box.w = Math.min(box.w, box.h * ratio);
      box.h = box.w / ratio;
    }
    return box;
  }

  // The printed gem's center is the hinge. Coordinates are in the card's own upright space, also in portrait.
  function printedAnchor(stock, gem) {
    if (!stock || !gem) return {u: .50, v: .36, w: .53, h: .37};
    const dx = gem.x - stock.x, dy = gem.y - stock.y;
    const a = (stock.roll || 0) * Math.PI / 180;
    return {u: .5 + (dx * Math.cos(a) + dy * Math.sin(a)) / stock.w,
      v: .5 + (-dx * Math.sin(a) + dy * Math.cos(a)) / stock.h, w: gem.w / stock.w, h: gem.h / stock.h,
      roll: (gem.roll || 0) - (stock.roll || 0)};
  }

  function glyphOrigin(stock, mark) {
    const dx = (mark.u - .5) * stock.w, dy = (mark.v - .5) * stock.h;
    const size = Math.min(stock.w * mark.w, stock.h * mark.h);
    const a = (stock.roll || 0) * Math.PI / 180;
    return {x: stock.x + dx * Math.cos(a) - dy * Math.sin(a), y: stock.y + dx * Math.sin(a) + dy * Math.cos(a),
      w:mark.rectangular ? stock.w * mark.w : size, h:mark.rectangular ? stock.h * mark.h : size,
      roll:(stock.roll || 0) + (mark.roll || 0)};
  }

  function visibleHand(id) {
    const button = select('.reserve-spread:not(.closing):not([hidden]) button[data-hand-card="' + id + '"]');
    const stock = button?.querySelector(".hand-leaf > .card-stock");
    if (!stock) return null;
    const style = getComputedStyle(button.closest(".reserve-spread"));
    return style.visibility !== "hidden" && style.display !== "none" && Number(style.opacity) > 0 ? stock : null;
  }

  function fanGeometry(stock, box, gem) {
    const style = getComputedStyle(stock);
    const w = parseFloat(style.width) || stock.offsetWidth, h = parseFloat(style.height) || stock.offsetHeight;
    if (!w || !h || !gem) return {source: box, layout: box};
    // getBoundingClientRect includes the fan angle's corners. Recover the real paper size and retain its angle.
    const roll = gem.roll || 0, a = roll * Math.PI / 180;
    const factor = box.w / (Math.abs(Math.cos(a)) * w + Math.abs(Math.sin(a)) * h);
    return {source: {...box, w: w * factor, h: h * factor, roll}, layout: {w, h}};
  }

  function backOf(tier, pile) {
    const top = deckTop(tier,pile);
    if (!top) return fitFace(Table.pocketPaper(tier,pile));
    const clone = fitFace(top.cloneNode(true));
    clone.querySelectorAll(".deck-count").forEach(n => n.remove());
    const material = 'url("' + Table.deckURL(tier,pile) + '")';
    clone.style.setProperty("--back", material);
    Object.assign(clone.style, {backgroundImage: material, backgroundSize: "cover", backgroundPosition: "center", backgroundRepeat: "no-repeat"});
    clone.classList.add("tier-" + tier);
    clone.style.backgroundColor = "var(--deck-low)";
    return clone;
  }

  function mountedFace(face) {
    const shell = document.createElement("span");
    shell.style.cssText = "display:block;position:absolute;inset:0;pointer-events:none;container-type:size";
    shell.appendChild(face);
    return shell;
  }

  function measureRefill(id, tier, pile, from) {
    const find = () => {
      const card = marketCard(id);
      return card?.querySelector(".card-stock,.card-face") || null;
    };
    const card = marketCard(id);
    const target = card?.querySelector(".card-stock,.card-face"), to = place(target);
    return from && to ? {id, tier, pile, from, to, target, find, face:copyFront(target)} : null;
  }

  function unveil(plan, duration, delay, times) {
    if (!plan) return;
    const {id, tier, pile, from, to, target, find, face} = plan;
    const run = startRun(cardKey(id), find, "back", target);
    if (!run) return;
    const shell = document.createElement("span");
    const rotor = document.createElement("span");
    rotor.style.cssText = "display:block;position:absolute;inset:0;transform-origin:center;transform-style:preserve-3d;will-change:transform";
    const front = mountedFace(face), back = mountedFace(backOf(tier,pile));
    for (const side of [front, back]) {
      side.style.backfaceVisibility = "hidden";
      side.style.webkitBackfaceVisibility = "hidden";
    }
    back.style.transform = "rotateY(180deg)";
    rotor.append(back, front);
    shell.appendChild(rotor);
    // One reversible physical sheet. The two prints share a center, size, perspective plane, path, and clock.
    const turn = Array.from({length: 17}, (_, i) => {
      const t = i / 16;
      return {offset: t, transform: "perspective(720px) rotateY(" + (-180 + 180 * smooth((t - .14) / .82)) + "deg)"};
    });
    animate(run, rotor, turn, duration, delay);
    send(run, shell, geometry(from, to, undefined, -1.6), duration, delay);
    if (delay) run.animations.push(shell.animate([{opacity: 0}, {opacity: 0}], {duration: delay}));
    record(times, "refill", delay + duration);
  }

  function captureCard(previous, action, releases) {
    const p = previous.active, card = action.id && Splendor.cards[action.id];
    const pile = card ? Splendor.pileOf(card.id) : action.pile || "base";
    const tier = card ? card.tier : action.tier;
    const sourceSlot = card && Splendor.location(previous,card.id);
    const publicCard = sourceSlot ? marketCard(card.id) : null;
    const deck = deckTop(tier,pile), top = place(deck);
    const spot = card && !publicCard ? heldSpot(p,card.id) : null;
    const purchase = action.type === "buy";
    const opened = purchase && card && !publicCard && previous.players[p].reserved.includes(card.id) ? visibleHand(card.id) : null;
    const face = publicCard?.querySelector(".card-stock,.card-face") || opened;
    const gem = purchase ? symbolBox(face?.querySelector(".card-bonus svg")) : null;
    const box = place(face), fan = opened && box ? fanGeometry(opened,box,gem) : null;
    const source = fan?.source || box || (publicCard ? place(publicCard) : card ? place(spot) : top);
    const key = card && (publicCard ? cardKey(card.id) : handKey(p,card.id));
    const from = key && !fan ? takeSource(key,source,releases) : source;
    if (fan && flights.has(key)) releases.add(flights.get(key));
    const mark = purchase ? printedAnchor(source,gem) : null;
    if (mark && gem) mark.rectangular = gem.w > 1.15 * gem.h;
    const layout = fan?.layout || (publicCard ? place(publicCard) : !card ? place(deck?.closest(".deck")) : from) || from;
    return {action, tier, pile, from, top, mark, layout, handSource:fan ? opened : null, sourceSlot,
      // A deck reservation never builds the new card's face, even if the player chose between two cards.
      face:copyFront(face)};
  }

  function captureRefills(previous, next) {
    const openings = [];
    for (const pile of previous.orient ? ["base","orient"] : ["base"]) {
      const old = Splendor.boardFor(previous,pile), current = next && Splendor.boardFor(next,pile);
      old.market.forEach((row, level) => {
        let origin;
        row.forEach((oldId,slot) => {
          const now = current?.market[level][slot];
          if (current && (!now || now === oldId)) return;
          if (origin === undefined) origin = place(deckTop(level + 1,pile));
          if (origin) openings.push({pile,tier:level + 1,slot,oldId,origin});
        });
      });
    }
    return openings;
  }

  function neutralMark(node) {
    const box = place(node);
    if (box) {
      box.h = Math.min(box.h,26);
      box.w = Math.min(box.w,box.h * 1.7);
    }
    return box;
  }

  function prepare(previous, action, next) {
    const releases = new Set();
    try {
      if (!supported()) return null;
      const p = previous.active;
      const shortSide = Math.max(1, Math.min(document.documentElement.clientWidth, document.documentElement.clientHeight));
      const result = {epoch, shortSide, groups:captureGroups(previous,action,next,releases), visitors:{},
        developments:[], refills:captureRefills(previous,next)};
      const arrivals = next ? next.players[p].nobles.filter(id => !previous.players[p].nobles.includes(id)) : previous.nobles;
      for (const id of arrivals) {
        const frame = select('.noble-tile[data-value="' + id + '"] .portrait-wrap');
        if (frame) result.visitors[id] = {point:place(frame), frame:frame.cloneNode(true)};
      }
      if (action.type === "reserve") result.developments.push(captureCard(previous,action,releases));
      // An automatic free Orient card can be acquired along with the purchased card in one engine action.
      const bought = next ? next.players[p].cards.filter(id => !previous.players[p].cards.includes(id))
        : action.type === "buy" ? [action.id] : [];
      for (const id of bought) result.developments.push(captureCard(previous,{type:"buy",id},releases));
      if (previous.orient && next?.orient) {
        for (const id of Object.keys(next.orient.pairs)) {
          if (previous.orient.pairs[id] || !previous.players[p].cards.includes(id)) continue;
          const ledger = neutralMark(seat(p)?.querySelector(".deed-heading > span"));
          const from = takeSource("purchase/" + p + "/" + id,ledger,releases);
          if (from) result.developments.push({action:{type:"buy",id}, pairing:true, from});
        }
      }
      return result;
    } catch { return null; } finally {
      for (const old of releases) finish(old);
    }
  }

  function measureCard(held, snapshot, previous, next) {
    const p = previous.active, {from, tier, action} = held;
    const bought = action.type === "buy";
    const owned = next.players[p];
    const id = bought ? action.id : owned.reserved.find(card => !previous.players[p].reserved.includes(card));
    if (!id) return null;
    const color = bought ? Splendor.bonusOf(next,id,p)?.color : null;
    const colored = Number.isInteger(color);
    const find = !bought ? () => heldSpot(p,id) : colored ? () => bonusPile(p,color)?.querySelector(".deed > .gicon") :
      () => seat(p)?.querySelector(Splendor.cards[id].effect === "gold" ? ".virtual-stock" : ".deed-heading > span");
    const target = find(), to = !bought ? place(target) : colored ? symbolBox(target) : neutralMark(target);
    const origin = from && bought && !held.pairing ? glyphOrigin(from, held.mark) : from;
    const path = origin && to ? geometry(origin, to, undefined, bought ? 0 : 1.1) : null;
    let duration = path ? paperDuration(Math.hypot(to.x - origin.x, to.y - origin.y), snapshot.shortSide) : 0;
    let pocket = null;
    if (!bought && path && target?.matches(".pocket-paper")) {
      pocket = {from, to, settle: Math.min(5, to.h * .16), layout: held.layout || from, face: held.face};
      duration += held.face ? 63 : 37;
    }
    const key = bought ? "purchase/" + p + "/" + id : handKey(p, id);
    let bonus = null;
    if (bought && colored && target) {
      const groupKey = p + "/" + color;
      const total = Splendor.bonuses(next,p)[color], before = Splendor.bonuses(previous,p)[color];
      const counter = bonusPile(p, color)?.querySelector(".bonus-count");
      const bounds = counter && {x: counter.offsetLeft, y: counter.offsetTop, w: counter.offsetWidth, h: counter.offsetHeight};
      const queue = bonusReceipts.get(groupKey);
      // Even unusually fast consecutive purchases credit one, then two, in purchase order.
      if (queue) duration = Math.max(duration, Math.ceil(queue.due - performance.now() + 22));
      bonus = {groupKey, total, before, counter, bounds, filter:getComputedStyle(target).filter};
    }
    return {held, bought, id, player:p, tier, find, key, target, path, duration, bonus, pocket};
  }

  function unmaskNumber(receipt) {
    receipt.copy?.remove();
    const counter = receipt.counter;
    if (counter) {
      if (receipt.visibility) counter.style.setProperty("visibility", receipt.visibility, receipt.priority);
      else counter.style.removeProperty("visibility");
    }
  }

  function bindNumber(receipt, counter, bounds) {
    if (!counter || !bounds || receipt.counter === counter) return;
    unmaskNumber(receipt);
    receipt.counter = counter;
    receipt.visibility = counter.style.getPropertyValue("visibility");
    receipt.priority = counter.style.getPropertyPriority("visibility");
    const copy = counter.cloneNode(false);
    copy.removeAttribute("id");
    copy.setAttribute("aria-hidden", "true");
    copy.dataset.bonusPrevious = "";
    copy.hidden = false;
    copy.textContent = receipt.visible ? String(receipt.visible) : "";
    Object.assign(copy.style, {position: "absolute", inset: "auto", left: bounds.x + "px", top: bounds.y + "px",
      width: bounds.w + "px", height: bounds.h + "px", margin: "0", pointerEvents: "none", visibility: "visible"});
    receipt.copy = copy;
    counter.after(copy);
    // Preserve the real DOM value while the previously credited number remains on the table.
    counter.style.setProperty("visibility", "hidden", "important");
  }

  function awaitBonus(run, bonus, duration) {
    let receipt = bonusReceipts.get(bonus.groupKey);
    if (!receipt) {
      receipt = {key: bonus.groupKey, visible:bonus.before, due:0, waiting:new Set()};
      bonusReceipts.set(receipt.key, receipt);
    }
    bindNumber(receipt, bonus.counter, bonus.bounds);
    receipt.waiting.add(run);
    receipt.due = performance.now() + duration;
    run.receipt = receipt;
    run.ordinal = bonus.total;
  }

  function finishBonus(run, landed) {
    const receipt = run.receipt;
    receipt.waiting.delete(run);
    if (landed) receipt.visible = run.ordinal;
    cancelAccent(receipt.pulse);
    let label = receipt.copy;
    if (receipt.waiting.size) {
      if (label) label.textContent = receipt.visible ? String(receipt.visible) : "";
    } else {
      unmaskNumber(receipt);
      bonusReceipts.delete(receipt.key);
      label = receipt.counter;
    }
    if (landed && label?.isConnected && supported()) {
      receipt.pulse = track(label, [{scale: "1.065", easing: "ease-out"}, {scale: "1"}], 105);
    }
  }

  function purchase(run, plan, times) {
    const {held, target, path, duration, bonus} = plan;
    const {layout, mark, from, tier} = held;
    if (held.pairing) {
      const stone = fitFace(target.cloneNode(true));
      stone.style.opacity = "1";
      if (bonus && !plan.sharedCounter) { awaitBonus(run,bonus,duration); plan.receipt = run.receipt; }
      send(run,mountedFace(stone),path,duration,0);
      record(times,"card",duration);
      return;
    }
    const paper = held.face || backOf(tier,held.pile);
    if (held.handSource?.isConnected && held.handSource.closest("button[data-hand-card]")?.dataset.handCard === plan.id) {
      conceal(run, held.handSource);
    }
    // Reuse the actual upper-right symbol, leaving only its empty paper tab to fold away.
    let glyph = paper.querySelector(".card-bonus svg");
    if (!glyph && bonus) glyph = target.cloneNode(true);
    if (!glyph) {
      const symbol = document.createElement("span");
      symbol.innerHTML = OrientUI.badge(Splendor.cards[plan.id],Table.state);
      glyph = symbol.querySelector("svg") || symbol;
    }
    fitFace(glyph);
    glyph.style.opacity = "1";
    glyph.style.filter = bonus?.filter || "none";
    const movingGem = mountedFace(glyph);
    const stock = sheet(mountedFace(paper), layout);
    stock.dataset.purchasePaper = "";
    stock.style.backfaceVisibility = "hidden";
    stock.style.webkitBackfaceVisibility = "hidden";
    run.nodes.push(stock);
    mount(stock);

    const hinge = " translate(" + (-mark.u * layout.w) + "px," + (-mark.v * layout.h) + "px)";
    const foldedScale = .15 * Math.min(path.to.w / from.w, path.to.h / from.h);
    const fold = Array.from({length: 19}, (_, i) => {
      const t = i / 18, pin = centerAt(path, t), tuck = smooth((t - .10) / .69);
      const shrink = mix(1, foldedScale, tuck);
      const w = from.w / layout.w * shrink, h = from.h / layout.h * shrink;
      // The sheet turns edge-on about the same moving gem; its final sliver fits behind that gem's solid center.
      return {offset: t, transform: "translate3d(" + pin.x + "px," + pin.y + "px,0) rotate(" + (from.roll || 0) * (1 - t) +
        "deg) perspective(720px) rotateY(" + (-96 * tuck) + "deg) scale(" + w + "," + h + ")" + hinge};
    });
    animate(run, stock, fold, duration, 0);
    if (bonus && !plan.sharedCounter) {
      awaitBonus(run,bonus,duration);
      plan.receipt = run.receipt;
    }
    send(run, movingGem, path, duration, 0);
    record(times, "card", duration);
  }

  const pocketJoin = .72;
  const pocketRest = .995;

  function pocketPose(pocket, t) {
    const {from, to, settle} = pocket;
    const entryX = to.x, entryY = to.y - settle;
    // The remaining travel is smaller than a layout subpixel. Use the native resting matrix exactly.
    if (t >= pocketRest) return {...to, roll: 0, clipped: 0};
    if (t >= pocketJoin) {
      const u = (t - pocketJoin) / (1 - pocketJoin);
      return {...to, y: entryY + settle * u * (2 - u), roll: 0, clipped: 0};
    }
    const u = t / pocketJoin, u2 = u * u, ease = u2 * (3 - 2 * u);
    const progress = ease + .24 * u * (1 - u) * (1 - u);
    const bow = 16 * u2 * (1 - u) * (1 - u);
    // Continue into the short downward stroke that seats the whole card on the ledge.
    const lead = (u2 * u - u2) * pocketJoin * 2 * settle / (1 - pocketJoin);
    const lift = bow * Math.min(18, Math.hypot(entryX - from.x, entryY - from.y) * .045);
    const scale = 1 + .012 * bow;
    return {x: mix(from.x, entryX, progress),
      y: mix(from.y, entryY, progress) + lead - lift,
      w: mix(from.w, to.w, ease) * scale, h: mix(from.h, to.h, ease) * scale,
      roll: (from.roll || 0) * (1 - ease) + (from.x < to.x ? 1.15 : -1.15) * bow, clipped: 0};
  }

  function pocketTurn(t) {
    return 180 * smooth((t - .075) / .43);
  }

  function linearPaper(run, node, frames, duration, delay = 0) {
    const a = node.animate(frames, {duration, delay, easing: "linear", fill: "both"});
    run.animations.push(a);
    return a;
  }

  function reserveFlight(run, plan, times) {
    const {pocket, target, duration} = plan, {layout, face} = pocket;
    // The compositor controls this real back's visibility during insertion, but it is
    // still owned by this flight and can be claimed by the opening hand.
    run.hidden.push({node: target, value: target.style.getPropertyValue("visibility"),
      priority: target.style.getPropertyPriority("visibility")});
    holders.set(target, run);
    const shell = sheet(document.createElement("span"), layout);
    shell.dataset.piece = "back";
    shell.dataset.reservation = face ? "market" : "deck";
    const rotor = document.createElement("span");
    rotor.style.cssText = "display:block;position:absolute;inset:0;transform-style:preserve-3d;transform-origin:center;pointer-events:none";
    const back = mountedFace(fitFace(target.cloneNode(true)));
    back.firstElementChild.classList.remove("in-hand");
    rotor.appendChild(back);
    if (face) {
      const front = mountedFace(face);
      for (const side of [back, front]) {
        side.style.backfaceVisibility = "hidden";
        side.style.webkitBackfaceVisibility = "hidden";
      }
      back.style.transform = "rotateY(180deg)";
      rotor.appendChild(front);
      const edge = document.createElement("span");
      const thickness = clamp(layout.w * .013, 1.15, 1.75);
      edge.style.cssText = "position:absolute;left:0;top:0;height:100%;pointer-events:none;transform-origin:0 50%;background:#d6c2a0";
      edge.style.width = thickness + "px";
      edge.style.transform = "translateZ(" + (-thickness / 2) + "px) rotateY(-90deg)";
      rotor.appendChild(edge);
    }
    shell.appendChild(rotor);
    run.nodes.push(shell);
    run.main = shell;
    mount(shell);
    const stops = Array.from({length: 25}, (_, i) => i / 24).concat(pocketJoin, pocketRest).sort((a, b) => a - b);
    const samples = stops.map(t => pocketPose(pocket, t));
    const frames = stops.map((offset, i) => {
      const p = samples[i];
      return {offset, transform: "translate3d(" + p.x + "px," + p.y + "px,0) rotate(" + p.roll +
        "deg) scale(" + p.w / layout.w + "," + p.h / layout.h + ") translate(-50%,-50%)"};
    });
    if (face) {
      linearPaper(run, rotor, stops.map(offset => ({offset,
        transform: "perspective(720px) rotateY(" + pocketTurn(offset) + "deg)"})), duration);
    }
    // The printed back takes over above the ledge and settles at its full proportions.
    const rest = "translate3d(0,0,0)", atMouth = "translate3d(0," + (-pocket.settle) + "px,0)";
    const insertion = [{offset: 0, transform: atMouth, visibility: "hidden"},
      {offset: pocketJoin, transform: atMouth, visibility: "hidden"},
      {offset: pocketJoin, transform: atMouth, visibility: "visible"}];
    for (let i = 0; i < stops.length; i++) if (stops[i] > pocketJoin) {
      const dy = samples[i].y - pocket.to.y;
      insertion.push({offset: stops[i], transform: stops[i] >= pocketRest ? rest : "translate3d(0," + dy + "px,0)", visibility: "visible"});
    }
    linearPaper(run, target, insertion, duration);
    linearPaper(run, shell, [{offset: 0, opacity: 1}, {offset: pocketJoin, opacity: 1},
      {offset: pocketJoin, opacity: 0}, {offset: 1, opacity: 0}], duration);
    const clock = linearPaper(run, shell, frames, duration);
    run.pocketTravel = {pocket, clock, duration};
    clock.onfinish = () => finish(run, true);
    record(times, "card", duration);
  }

  // If the pocket is opened before an incoming card arrives, unfold that actual moving piece.
  function unpackFromFlight(player, id) {
    const run = flights.get(handKey(player, id));
    if (!run?.pocketTravel) return null;
    const {pocket, clock, duration} = run.pocketTravel;
    const t = clamp((clock.currentTime || 0) / duration, 0, 1);
    const current = pocketPose(pocket, t);
    current.flip = pocket.face ? pocketTurn(t) : 180;
    finish(run);
    return current;
  }

  function reserveRefillDelay(plan) {
    const {pocket, held, duration} = plan;
    if (!pocket?.face || !held.top) return 53;
    const from = pocket.from, deck = held.top;
    const left = Math.min(from.x - from.w / 2, deck.x - deck.w / 2), right = Math.max(from.x + from.w / 2, deck.x + deck.w / 2);
    const top = Math.min(from.y - from.h / 2, deck.y - deck.h / 2), bottom = Math.max(from.y + from.h / 2, deck.y + deck.h / 2);
    // The departing card must also clear the route between the deck and the vacant slot.
    for (let i = 8; i <= 22; i++) {
      const t = i / 30, p = pocketPose(pocket, t), {x, y} = p;
      const w = Math.max(0, Math.min(x + p.w / 2, right) - Math.max(x - p.w / 2, left));
      const h = Math.max(0, Math.min(y + p.h / 2, bottom) - Math.max(y - p.h / 2, top));
      if (w * h < p.w * p.h * .10) return Math.round(t * duration + 12);
    }
    return Math.round(.74 * duration);
  }

  function showCard(plan, times) {
    if (!plan) return;
    const {bought, tier, find, key, target, path, duration, bonus} = plan;
    const hide = bought ? bonus?.before === 0 && !plan.sharedCounter : !plan.pocket;
    const run = path && startRun(key, find, bought ? "purchase" : "back", target, hide);
    if (run) {
      if (bought) {
        if (!plan.held.pairing) creditOnArrival(run,plan.player,Splendor.cards[plan.id].points);
        purchase(run, plan, times);
      } else if (plan.pocket) reserveFlight(run, plan, times);
      else {
        send(run, mountedFace(backOf(tier,plan.held.pile)), path, duration, 0);
        record(times, "card", duration);
      }
      if (plan.held.sourceSlot) {
        const {pile, tier, slot} = plan.held.sourceSlot;
        run.vacancy = pile + "/" + tier + "/" + slot;
        run.slotClearAt = performance.now() + reserveRefillDelay(plan);
      }
    }
  }

  function measureVisitor(snapshot, previous, next) {
    const p = previous.active;
    const id = next.players[p].nobles.find(n => !previous.players[p].nobles.includes(n));
    const visitor = snapshot.visitors[id];
    if (!visitor?.point) return null;
    const find = () => seat(p)?.querySelector('.guest-portrait[data-value="' + id + '"]') || seat(p)?.querySelector(".seat-points");
    const target = find(), to = place(target);
    if (!to) return null;
    const seal = target.classList.contains("guest-portrait");
    if (!seal) { to.w = to.h * .72; to.h *= .9; }
    const board = document.getElementById("surface").getBoundingClientRect();
    const extent = Math.min(380, Math.min(board.width,board.height) * .52);
    const zoom = extent / Math.max(visitor.point.w,visitor.point.h);
    const center = {x:board.left + board.width / 2, y:board.top + board.height / 2, scale:zoom};
    return {p, id, visitor, target, find, to, center, seal,
      rayDiameter:Math.ceil(Math.hypot(board.width,board.height)) + 4,
      delay:snapshot.developments.length ? 72 : 22};
  }

  function showVisitor(plan, times) {
    if (!plan) return;
    const {p, id, visitor, target, find, to, center, seal, rayDiameter, delay} = plan;
    const run = startRun("guest/" + p + "/" + id, find, "noble", target);
    if (!run) return;
    creditOnArrival(run,p,Splendor.nobles[id].points);
    if (!seal) restore(run);
    const duration = 2180;
    const stage = document.createElement("div");
    stage.className = "noble-arrival-stage";
    warmVisitorLight();
    const light = visitorLight.cloneNode();
    light.style.width = rayDiameter + "px";
    const name = document.createElement("span");
    name.className = "noble-arrival-name";
    name.textContent = Splendor.nobles[id].name;
    name.style.marginTop = visitor.point.h * center.scale / 2 + 10 + "px";
    stage.append(light,name);
    run.nodes.push(stage);
    mount(stage);
    stage.addEventListener("click", event => {
      event.stopPropagation();
      finish(run,true);
    });

    const frame = sheet(document.createElement("span"),visitor.point);
    frame.dataset.piece = "noble";
    frame.appendChild(visitor.frame);
    run.main = frame;
    run.nodes.push(frame);
    mount(frame);

    const play = (node,frames) => linearPaper(run,node,frames,duration,delay);
    play(stage,[{opacity:0},{offset:.23,opacity:1},{offset:.74,opacity:1},{offset:.98,opacity:0},{opacity:0}]);
    play(light,[{transform:"rotate(-8deg)"},{transform:"rotate(17deg)"}]);
    play(name,[{opacity:0},{offset:.21,opacity:0},{offset:.33,opacity:1},{offset:.73,opacity:1},{offset:.85,opacity:0},{opacity:0}]);
    const reward = frame.querySelector(".noble-reward");
    if (reward) play(reward,[{opacity:1},{offset:.80,opacity:1},{offset:.98,opacity:0},{opacity:0}]);
    const poseAt = (box,scale) => {
      const x = box.x - visitor.point.w * scale / 2;
      const y = box.y - visitor.point.h * scale / 2;
      return `translate3d(${x}px,${y}px,0) scale(${scale})`;
    };
    const landingScale = Math.min(to.w/visitor.point.w,to.h/visitor.point.h);
    if (seal) {
      // The last frame uses the ledger's own bezel, image crop and pixel size.
      const seated = document.createElement("span");
      seated.className = "guest-portrait";
      seated.appendChild(target.querySelector(".guest-seal").cloneNode(false));
      Object.assign(seated.style,{position:"absolute",top:"50%",left:"50%",width:to.w+"px",height:to.h+"px",
        transform:"translate(-50%,-50%) scale(" + 1/landingScale + ")"});
      frame.appendChild(seated);
      play(visitor.frame,[{opacity:1},{offset:.89,opacity:1},{offset:.99,opacity:0},{opacity:0}]);
      play(seated,[{opacity:0},{offset:.89,opacity:0},{offset:.99,opacity:1},{opacity:1}]);
    }
    const journey = play(frame,[
      {transform:poseAt(visitor.point,1),easing:"cubic-bezier(.28,.09,.24,1)"},
      {offset:.31,transform:poseAt(center,center.scale*1.025),easing:"ease-in-out"},
      {offset:.73,transform:poseAt(center,center.scale),easing:"cubic-bezier(.46,.02,.28,1)"},
      {transform:poseAt(to,landingScale)}
    ]);
    journey.onfinish = () => finish(run,true);
    record(times, "noble", delay + duration);
  }

  function timing() {
    return {startedAt: performance.now(), firstLandMs: 0, lastLandMs: 0, tokenLandMs: [], cardLandMs: null, nobleLandMs: null};
  }

  function record(times, kind, ms) {
    times.firstLandMs = times.firstLandMs ? Math.min(times.firstLandMs, ms) : ms;
    times.lastLandMs = Math.max(times.lastLandMs, ms);
    if (kind === "chip" && !times.tokenLandMs.includes(ms)) times.tokenLandMs.push(ms);
    if (kind === "card") times.cardLandMs = ms;
    if (kind === "noble") times.nobleLandMs = ms;
  }

  function play(snapshot, previous, next, action, onSettled) {
    const times = timing();
    try {
      if (!snapshot || snapshot.epoch !== epoch || !supported()) {
        onSettled?.();
        return times;
      }
      // Read every moving endpoint before changing any real tile or inserting anything into the effect layer.
      const groups = measureArrivals(snapshot, previous, next);
      if (action.type === "take" && groups.length > 1) {
        // A handful leaves together. Keep the last coin within one soft settling beat of the first.
        const longest = Math.max(...groups.map(group => group.duration));
        for (const group of groups) group.duration = Math.max(group.duration,longest - 55);
      }
      const cards = snapshot.developments.map(held => measureCard(held,snapshot,previous,next)).filter(Boolean);
      // A free card may arrive in the same color as the paid one. The last arrival owns the one printed counter.
      const byCounter = new Map();
      for (const card of cards) if (card.bonus) {
        const group = card.bonus.groupKey, old = byCounter.get(group);
        if (old && old.duration > card.duration) card.sharedCounter = true;
        else { if (old) old.sharedCounter = true; byCounter.set(group,card); }
      }
      const refills = [];
      for (const opening of snapshot.refills) {
        const {pile,tier,slot,oldId,origin} = opening;
        const id = Splendor.boardFor(next,pile).market[tier-1][slot];
        if (!id || id === oldId) continue;
        const refill = measureRefill(id,tier,pile,origin);
        if (refill) refills.push({refill, vacancy:pile + "/" + tier + "/" + slot});
      }
      const visitor = measureVisitor(snapshot, previous, next);
      const earlier = onSettled ? new Set(flights.values()) : null;
      times.startedAt = performance.now();
      writeBatch(() => {
        reconcile();
        showCoins(groups, previous.active, times);
        for (const card of cards) showCard(card,times);
        for (const {refill,vacancy} of refills) {
          let delay = 0;
          for (const run of flights.values()) if (run.vacancy === vacancy) {
            delay = Math.max(delay,Math.ceil(run.slotClearAt - performance.now()));
          }
          unveil(refill,325,delay,times);
        }
        showVisitor(visitor, times);
      });
      for (const card of cards) if (card.receipt) card.receipt.due = Math.max(card.receipt.due,times.startedAt + card.duration);
      times.tokenLandMs.sort((a, b) => a - b);
      if (onSettled) {
        const moving = Array.from(flights.values()).filter(run => !earlier.has(run));
        let remaining = moving.length;
        if (!remaining) onSettled();
        else {
          const landed = () => { if (--remaining === 0) onSettled(); };
          moving.forEach(run => { run.onSettled = landed; });
        }
      }
    } catch { clear(); onSettled?.(); return timing(); }
    return times;
  }

  function deal() {
    clear();
    try {
      if (!supported()) return;
      const times = timing();
      const plans = [];
      for (const pile of Table.state.orient ? ["base","orient"] : ["base"]) {
        for (let tier = 1; tier <= 3; tier++) {
          const from = place(deckTop(tier,pile));
          Splendor.boardFor(Table.state,pile).market[tier - 1].forEach((id,slot) => {
            if (id) plans.push({plan:measureRefill(id,tier,pile,from), delay:(3 - tier)*43 + slot*22 + (pile === "orient" ? 22 : 0)});
          });
        }
      }
      writeBatch(() => {
        for (const {plan, delay} of plans) unveil(plan, 310, delay, times);
      });
    } catch { clear(); }
  }

  function uncoverCard(event) {
    const card = event.target.closest?.("#development-market .market-card[data-value]");
    if (card) finish(flights.get(cardKey(card.dataset.value)));
  }

  if (typeof document !== "undefined") {
    document.addEventListener("keydown", event => {
      const stage = layer?.querySelector(".noble-arrival-stage");
      if (!stage || !["Enter"," ","Escape"].includes(event.key)) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      if (!event.repeat) stage.click();
    }, true);
    document.addEventListener("pointerdown", uncoverCard, {capture: true, passive: true});
    document.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") uncoverCard(e); }, true);
    document.addEventListener("visibilitychange", () => { if (document.hidden) clear(); });
    globalThis.addEventListener("resize", clear);
    globalThis.addEventListener("pagehide", clear);
    globalThis.screen?.orientation?.addEventListener?.("change", clear);
    motionPreference?.addEventListener?.("change", clear);
  }
  globalThis.BoardMotion = Object.freeze({visualAction, prepare, play, deal, handoff, reject, clear, warmVisitorLight, releaseChip, unpackFromFlight, pointsInFlight, queueChipCounts, isInFlight: node => holders.has(node)});
})();

/* Only the actual cards and the usual purchase piece are in front of the table. */
(() => {
  "use strict";
