  function visibleTable(surface) {
    const view = window.visualViewport;
    const full = {x:0, y:0, w:surface.clientWidth, h:surface.clientHeight};
    if (!view || view.scale === 1) return full;
    const board = surface.getBoundingClientRect();
    const left = Math.max(board.left, view.offsetLeft), top = Math.max(board.top, view.offsetTop);
    const right = Math.min(board.right, view.offsetLeft + view.width);
    const bottom = Math.min(board.bottom, view.offsetTop + view.height);
    if (right <= left || bottom <= top) return full;
    return {x:left - board.left, y:top - board.top, w:right - left, h:bottom - top};
