    const padding = getComputedStyle(surface);
    const left = Math.max(frame.x,parseFloat(padding.paddingLeft) || 0);
    const top = Math.max(frame.y,parseFloat(padding.paddingTop) || 0);
    const right = Math.min(frame.x + w,surface.clientWidth - (parseFloat(padding.paddingRight) || 0));
    const bottom = Math.min(frame.y + h,surface.clientHeight - (parseFloat(padding.paddingBottom) || 0));
    const gap = Math.max(7, Math.min(24, w * .019));
    const maxWidth = Math.min(255,h * .54 * ratio);
