    const edge = Math.ceil(maxWidth * .05 + 1);
    const span = Math.min(w * .86,right - left - 2 * edge);
    const width = Math.max(1,Math.min(maxWidth,(bottom - top - 2 * edge) * ratio,(span - (n - 1) * gap) / n));
    const height = width / ratio;
    const startX = (left + right - n * width - (n - 1) * gap) / 2;
    const y = (top + bottom - height) / 2;
    // When the players pinch in, keep the original purchase piece within reach.
    const anchor = rect(document.getElementById("action-anchor"));
    const actionX = anchor.x + anchor.w / 2, actionY = anchor.y + anchor.h / 2;
    const scaleX = w / surface.clientWidth, scaleY = h / surface.clientHeight;
    const action = document.getElementById("turn-action");
    action.style.setProperty("--hand-action-x", frame.x + actionX * scaleX - actionX + "px");
    action.style.setProperty("--hand-action-y", frame.y + actionY * scaleY - actionY + "px");
    action.style.setProperty("--hand-action-scale", Math.min(scaleX, scaleY));
    hand.cards.forEach((card, i) => {
      const wing = i - (n - 1) / 2;
      const x = startX + i * (width + gap);
      const slot = rect(hand.slots[i]), paper = card.paper ? rect(card.paper) : slot;
      card.buried = Math.max(0, Math.min(.80, (paper.y + paper.h - slot.y - slot.h) / paper.h));
      card.origin = "translate3d(" + (paper.x + paper.w / 2 - x - width / 2) + "px," +
        (paper.y + paper.h / 2 - y - height / 2) + "px,0) scale(" + (paper.w / width) + "," + (paper.h / height) + ")";
      if (card.departure) {
        const f = surface.getBoundingClientRect(), point = card.departure;
        const px = point.x - f.left, py = point.y - f.top;
        card.launch = "translate3d(" + (px - x - width / 2) + "px," + (py - y - height / 2) +
          "px,0) rotate(" + (point.roll || 0) + "deg) scale(" + point.w / width + "," + point.h / height + ")";
      }
      card.rest = "rotate(" + wing * 1.35 + "deg)";
      Object.assign(card.button.style, {left:x + "px", top:y + "px", width:width + "px"});
      card.leaf.style.transform = card.rest;
    });
  }

  function animate(hand, opening) {
    const animations = [];
    for (const [i, card] of hand.cards.entries()) {
      const current = getComputedStyle(card.leaf).transform;
      const face = card.leaf.querySelector(".card-stock");
      const faceAngle = face ? parseFloat(getComputedStyle(face).rotate.split(" ").pop()) || 0 : 0;
      stopLeaf(card);
      if (reduced.matches || !card.leaf.animate) continue;
      const frames = opening ? [{transform:card.launch || card.origin}, {transform:card.rest}]
        : [{transform:current}, {transform:card.origin}];
      const timing = {
        duration: opening ? 275 : 170, delay: (opening ? i : hand.cards.length - 1 - i) * 20,
        easing: opening ? "cubic-bezier(.19,.66,.26,1)" : "cubic-bezier(.38,.02,.61,1)", fill: "both"
      };
      card.animation = card.leaf.animate(frames, timing);
      animations.push(card.animation);
      if (card.back && face) {
        const start = opening ? card.departure?.flip ?? 180 : faceAngle, end = opening ? 0 : 180;
        const crop = opening ? card.departure?.clipped ?? card.buried : card.buried;
        const uncut = "inset(-20%)", inPocket = "inset(0% 0% " + (100 * crop) + "% 0%)";
        const turning = opening
          ? [{rotate:"y " + start + "deg", clipPath:inPocket}, {offset:.22, rotate:"y " + (.88 * start) + "deg", clipPath:uncut}, {rotate:"y 0deg", clipPath:uncut}]
          : [{rotate:"y " + start + "deg", clipPath:uncut}, {offset:.72, rotate:"y " + end + "deg", clipPath:uncut}, {rotate:"y " + end + "deg", clipPath:inPocket}];
        const turnTiming = opening ? {...timing, fill:"backwards"} : timing;
