        if (!opening) card.animation.finished.then(() => returnPaper(card), () => {});
      }
    }
    return animations;
  }

  function close({animated = true, restoreFocus = false, purchased = null} = {}) {
    if (!openHand) return;
    const hand = openHand;
    const focusWasInside = hand.host.contains(document.activeElement);
    openHand = null;
    observer?.disconnect();
    const surface = document.getElementById("surface");
    surface.classList.remove("hand-inspection","hand-observing");
    for (const attr of ["role", "aria-modal", "aria-label"]) surface.removeAttribute(attr);
    for (const child of hand.frozen) child.inert = false;
    if (purchased) {
      const leaving = hand.cards.find(card => card.button.dataset.handCard === purchased);
      stopLeaf(leaving);
      returnPaper(leaving);
      leaving?.button.remove();
      hand.cards = hand.cards.filter(card => card !== leaving);
      const surface = document.getElementById("surface");
      hand.cards.forEach((card, i) => {
        const box = localBox(card.button, surface), to = localBox(card.paper || hand.slots[i], surface);
        card.origin = "translate3d(" + (to.x + to.w / 2 - box.x - box.w / 2) + "px," +
          (to.y + to.h / 2 - box.y - box.h / 2) + "px,0) scale(" + to.w / box.w + "," + to.h / box.h + ")";
      });
    }
    if (Table.viewer !== hand.owner) {
      for (const card of hand.cards) {
        const id = card.button.dataset.handCard;
        if (!Table.state.players[hand.owner].privateReserved?.includes(id)) continue;
        const pose = getComputedStyle(card.leaf).transform;
        stopLeaf(card);
        card.leaf.style.transform = pose;
