    hand.host.inert = true;
    closing?.remove();
    let removed = false;
    const remove = () => {
      if (removed) return;
      removed = true;
      hand.cards.forEach(card => { stopLeaf(card); returnPaper(card); });
      hand.host.remove();
      if (closing?.host === hand.host) closing = null;
    };
    closing = {host: hand.host, remove};
    const jobs = animated ? animate(hand, false) : [];
    if (jobs.length) Promise.allSettled(jobs.map(a => a.finished)).then(remove);
    else remove();
  }

  function isFaceDown(owner, id) {
    const state = Table.state;
    const viewer = Table.viewer;
    return owner !== viewer && state.players[owner].privateReserved?.includes(id);
  }

  function open(owner) {
    close({animated:false});
    closing?.remove();
    closing = null;
    const s = Table.state, handIds = s.players[owner].reserved;
    if (!handIds.length) return;
    const host = document.createElement("div");
    host.id = "open-reserve-hand";
    host.className = "reserve-spread";
    host.dataset.owner = owner;
    host.setAttribute("role", "group");
    host.setAttribute("aria-label", Table.playerName(owner) + "的预留牌");
    const buyTurn = owner === s.active && s.phase === "action" && !Table.computerTurn && !Table.friendWaiting;
    const bag = document.querySelector("#seat-" + owner + " .holdings-button");
    const slots = bag.querySelectorAll(".reserve-fan > i");
    const cards = handIds.map((id, index) => {
      const meta = Lan.back(id), c = Splendor.cards[id];
      const privateBack = isFaceDown(owner, id);
      const btn = document.createElement("button");
      const canBuy = !privateBack && buyTurn && Splendor.payment(s,id,owner).canBuy;
      btn.type = "button";
      btn.className = "market-card held-card" + (!privateBack && c.bonus !== null ? " dye-" + c.bonus : "") + (canBuy ? " affordable" : "");
      btn.setAttribute("aria-pressed", "false");
      const leaf = document.createElement("span");
      leaf.className = "hand-leaf";
