        btn.setAttribute("aria-label",Table.cardDescription(id) + "，" + (canBuy ? "可购买" : buyTurn ? "暂时买不起" : "查看预留牌"));
        leaf.innerHTML = Table.cardStock(id);
        back.style.removeProperty("visibility");
        back.classList.remove("in-hand");
        back.classList.add("hand-reverse");
        leaf.appendChild(back);
      }
      btn.appendChild(leaf);
      host.appendChild(btn);
      const card = {button:btn, leaf, paper, back, departure};
      if (paper) { borrowed.set(paper, card); paper.classList.add("in-hand"); }
      return card;
    });
    const surface = document.getElementById("surface"), controls = document.getElementById("turn-controls");
    const frozen = Array.from(document.getElementById("playfield").children).filter(child => child !== controls && !child.inert);
    bag.setAttribute("aria-expanded", "true");
    bag.setAttribute("aria-controls", host.id);
    bag.closest(".seat").classList.add("hand-open");
    surface.appendChild(host);
    surface.classList.add("hand-inspection");
    surface.classList.toggle("hand-observing", !buyTurn);
    surface.setAttribute("role", "dialog");
    surface.setAttribute("aria-modal", "true");
    surface.setAttribute("aria-label", Table.playerName(owner) + "的预留牌");
    for (const child of frozen) child.inert = true;
