    host.addEventListener("click", event => {
      if (event.target.closest("[data-hand-card], [data-hand-back], #turn-action")) return;
      event.stopPropagation();
      Controls.close();
    });
    host.addEventListener("keydown", event => {
      const current = cards.findIndex(card => card.button === document.activeElement);
      if (current < 0 || !["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(event.key)) return;
      event.preventDefault();
      const step = event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 1;
      cards[(current + step + cards.length) % cards.length].button.focus({preventScroll:true});
    });
    cards[0].button.focus({preventScroll:true});
  }

  function mark(id, swaps = []) {
    if (!openHand) return;
    for (const {button} of openHand.cards) {
      const selected = !!id && button.dataset.handCard === id;
      button.classList.toggle("is-chosen", selected);
      if (button.getAttribute("aria-pressed") !== String(selected)) button.setAttribute("aria-pressed", String(selected));
      for (const cost of button.querySelectorAll("[data-cost-color]")) {
