  reduced.addEventListener?.("change", () => {
    if (!reduced.matches) return;
    closing?.remove();
    if (openHand) for (const card of openHand.cards) stopLeaf(card);
  });
  window.visualViewport?.addEventListener("resize", queueLayout);
  window.visualViewport?.addEventListener("scroll", queueLayout);
  document.addEventListener("keydown", event => {
    if (!openHand || event.key !== "Tab") return;
    const items = openHand.cards.map(card => card.button);
    const payment = document.querySelector("#expansion-choice .ex-payment:not([hidden])");
    if (payment) items.push(...payment.querySelectorAll("button:not(:disabled)"));
    const action = document.getElementById("turn-action");
    if (!action.disabled) items.push(action);
    const i = items.indexOf(document.activeElement);
    event.preventDefault();
    const next = items[(i + (event.shiftKey ? -1 : 1) + items.length) % items.length];
    next.focus({preventScroll:true});
    const strip = next.closest(".ex-row");
    if (strip && strip.scrollWidth > strip.clientWidth) {
      const surface = document.getElementById("surface");
      const local = localBox(next,surface).x - localBox(strip,surface).x;
      if (local < strip.scrollLeft) strip.scrollLeft = local;
      else if (local + next.offsetWidth > strip.scrollLeft + strip.clientWidth) strip.scrollLeft = local + next.offsetWidth - strip.clientWidth;
    }
  });
  globalThis.ReserveHand = Object.freeze({open, close, mark, isFaceDown, get owner(){return openHand?.owner ?? null;},
    get state(){return openHand?.state ?? null;}, get readOnly(){return openHand?.readOnly === true;}});
})();

/* Online rendezvous for this shared game edition. The relays never carry game state. */
(() => {
  "use strict";
  const edition = "d8b5372d2c2772124e4741182a867a1dc1d7fafe2dc0f80b2adfe2eeb6beab9b";
  const brokers = ["wss://broker.emqx.io:8084/mqtt","wss://broker.hivemq.com:8884/mqtt"];
  const encode = new TextEncoder(), decode = new TextDecoder();
  const b64 = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes)));
  const un64 = text => Uint8Array.from(atob(text),c=>c.charCodeAt(0));
  const random = size => crypto.getRandomValues(new Uint8Array(size));
  const validPeer = text => typeof text === "string" && /^[A-Za-z0-9+/]{87}=$/.test(text);
  async function networkTag(salt) {
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),4000);
    try {
      const response=await fetch("https://api.ipify.org?format=json",{
        signal:controller.signal,credentials:"omit",referrerPolicy:"no-referrer",cache:"no-store"
      });
      if(!response.ok)return "";
      const {ip}=await response.json();
      if(typeof ip!=="string" || !/^(\d{1,3}\.){3}\d{1,3}$/.test(ip))return "";
      const digest=await crypto.subtle.digest("SHA-256",encode.encode(salt+"|"+ip));
      return b64(digest);
    } catch { return ""; } finally { clearTimeout(timer); }
  }

  class RoomDirectory {
    constructor(onMessage,onStatus) {
      this.onMessage=onMessage;
      this.onStatus=onStatus;
      this.clients=new Set();
      this.online=new Set();
      this.seen=new Set();
      this.closed=false;
    }
    async start() {
      if (!globalThis.crypto?.subtle) throw new Error("当前打开方式不支持加密找房，请用系统浏览器打开游戏。");
      const raw=Uint8Array.from(edition.match(/../g),byte=>parseInt(byte,16));
      const digest=await crypto.subtle.digest("SHA-256",raw);
      this.topic="splendor-table/v2/"+Array.from(new Uint8Array(digest).slice(0,16),v=>v.toString(16).padStart(2,"0")).join("");
      this.circle=await crypto.subtle.importKey("raw",raw,"AES-GCM",false,["encrypt","decrypt"]);
      this.keys=await crypto.subtle.generateKey({name:"ECDH",namedCurve:"P-256"},false,["deriveKey"]);
      this.id=b64(await crypto.subtle.exportKey("raw",this.keys.publicKey));
      if (this.closed) return;
      const [,network]=await Promise.all([Promise.any(brokers.map(url=>this.dial(url))),networkTag(edition)]);
      this.network=network;
    }
    async dial(url) {
      const id="sp"+Array.from(random(10),v=>v.toString(16).padStart(2,"0")).join("");
      const client=new Paho.Client(url,id);
      this.clients.add(client);
      await new Promise((resolve,reject)=>{
        const fail=()=>reject(new Error("找房服务暂时连不上，请检查互联网连接后重试。"));
        client.onConnectionLost=()=>{
          const wasOnline=this.online.delete(client);
          if (!this.closed && wasOnline && this.online.size===0) this.onStatus(false);
          fail();
        };
        client.onMessageArrived=packet=>{
          if(this.closed || packet.retained || packet.destinationName!==this.topic || packet.payloadBytes.length>64000) return;
          this.receive(packet.payloadString).catch(()=>{ /* Ignore unrelated or unreadable room advertisements. */ });
        };
        client.connect({useSSL:true,mqttVersion:4,cleanSession:true,timeout:8,keepAliveInterval:30,
          onFailure:fail,onSuccess:()=>{
            if(this.closed){client.disconnect();fail();return;}
            client.subscribe(this.topic,{qos:0,timeout:5,onFailure:fail,onSuccess:()=>{
              if(this.closed){fail();return;}
              this.online.add(client);resolve();this.onStatus(true);
            }});
          }
        });
      });
    }
    async pairKey(other) {
      const pub=await crypto.subtle.importKey("raw",un64(other),{name:"ECDH",namedCurve:"P-256"},false,[]);
      return crypto.subtle.deriveKey({name:"ECDH",public:pub},this.keys.privateKey,{name:"AES-GCM",length:256},false,["encrypt","decrypt"]);
    }
    async pack(message,to="") {
      const from=this.id, iv=random(12);
      const key=to ? await this.pairKey(to) : this.circle;
      const cipher=await crypto.subtle.encrypt({name:"AES-GCM",iv,additionalData:encode.encode(from+"|"+to)},key,encode.encode(JSON.stringify(message)));
      return JSON.stringify({from,to,iv:b64(iv),body:b64(cipher)});
    }
    publish(payload) {
      if(this.closed)return;
      let delivered=false;
      for(const client of this.online){
        if(!client.isConnected())continue;
        try {client.send(this.topic,payload,0,false);delivered=true;} catch { /* The other relay can still deliver. */ }
      }
      if(!delivered) throw new Error("找房服务已断开，请重新搜索。");
    }
    async send(message,to="") {
      const payload=await this.pack(message,to);
      if(!this.closed)this.publish(payload);
    }
    async receive(payload) {
      const {from,to,iv,body}=JSON.parse(payload);
      if(!validPeer(from) || from===this.id || (to!=="" && to!==this.id) || typeof iv!=="string" ||
          iv.length!==16 || typeof body!=="string" || body.length>61000)return;
      const stamp=from+iv;
      if(this.seen.has(stamp))return;
      this.seen.add(stamp); // Both relays may deliver before the first decryption resolves.
      if(this.seen.size>256)this.seen.delete(this.seen.values().next().value);
      const key=to ? await this.pairKey(from) : this.circle;
      const plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:un64(iv),additionalData:encode.encode(from+"|"+to)},key,un64(body));
      if(!this.closed)await this.onMessage(JSON.parse(decode.decode(plain)),from,!!to);
    }
    close() {
      this.closed=true;
      for(const client of this.clients){try{client.disconnect();}catch{/* Already disconnected. */}}
      this.clients.clear();this.online.clear();this.seen.clear();
    }
  }
  globalThis.RoomDirectory=RoomDirectory;
})();

/* Find a table online. Gameplay stays on a reliable WebRTC data channel. */
(() => {
  "use strict";
  const hostSave = "splendor.lan.host.v1", guestSave = "splendor.lan.guest.v1";
  const dialog = document.getElementById("lan-dialog");
  const randomId = () => Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,"0")).join("");
  const isId = value => typeof value === "string" && /^[0-9a-f]{32}$/.test(value);
  const copy = value => JSON.parse(JSON.stringify(value));
  function read(key) { try { return JSON.parse(localStorage.getItem(key)); } catch { return null; } }
  function write(key,value) { try { localStorage.setItem(key,JSON.stringify(value)); return true; } catch { return false; } }
  let guestKey = read(guestSave);
  let room = null, role = null, peer = null, channel = null;
  let ready = false, pending = false, watchdog = 0, disconnectTimer = 0;
  let stored = true, screen = "";
  let directory = null, contact = null, listingTimer = 0, relayTimer = 0, gonePacket = "";
  const rooms = new Map();
  const listingVersions = new Map(), withdrawn = new Set();
  let serial = 0, searchEdition = false;
  const cleanName = value => typeof value === "string" ? [...value.trim()].slice(0,18).join("") : "";
  const choose = list => list[crypto.getRandomValues(new Uint8Array(1))[0]%list.length];
  const gemName = () => choose(["琥珀","翡翠","蓝晶","红玉","珍珠","金砂"]);
  let guestName = cleanName(read("splendor.lan.name")) || "";
  let version = -1;
  const aliases = new Map();
  const hiddenBack = /^back:(base|orient):([123]):([0-9a-f]{32})$/;

  function back(id) {
    const card = Splendor.cards[id];
    if (card) return {tier:card.tier,pile:Splendor.pileOf(id)};
    const match = hiddenBack.exec(id);
    if (!match) throw new Error("无法读取这张牌背。");
    return {tier:Number(match[2]),pile:match[1]};
  }

  // Never transmit a shuffle seed, deck order or the host's privately drawn face.
  function guestView(state) {
    const view = copy(state), host = view.players[0];
    view.log = [];
    for (const board of [view,view.orient].filter(Boolean)) for (const deck of board.decks) deck.fill(null);
    const step = view.flow?.queue[0];
    if (view.active === 1 && view.phase === "effect" && step?.kind === "reserve-two") {
      const deck = Splendor.boardFor(state,step.pile).decks[step.tier-1];
      const exposed = Splendor.boardFor(view,step.pile).decks[step.tier-1];
      exposed.splice(-2,2,...deck.slice(-2));
    }
    if (host.privateReserved) {
      for (const id of host.privateReserved) {
        if (!aliases.has(id)) {
          const card = back(id);
          aliases.set(id,`back:${card.pile}:${card.tier}:${randomId()}`);
        }
      }
      host.reserved = host.reserved.map(id=>host.privateReserved.includes(id) ? aliases.get(id) : id);
      host.privateReserved = host.privateReserved.map(id=>aliases.get(id));
    }
    return view;
  }

  function validView(view) {
    // Validate the same conservation and phase rules as a save, using any compatible
    // unseen faces for the masked cards. The renderer keeps the original masked view.
    try {
      const s = copy(view), known = new Set(s.orient?.discarded || []);
      const boards = [s,s.orient].filter(Boolean);
      for (const b of boards) for (const row of [...b.decks,...b.market]) for (const id of row) if (id) known.add(id);
      for (const p of s.players) for (const id of [...p.cards,...p.reserved]) if (!hiddenBack.test(id)) known.add(id);
      const remaining = new Map();
      for (const card of Object.values(Splendor.cards)) {
        if (known.has(card.id)) continue;
        const key = Splendor.pileOf(card.id)+card.tier;
        if (!remaining.has(key)) remaining.set(key,[]);
        remaining.get(key).push(card.id);
      }
      const host = s.players[0], replacements = new Map();
      for (const id of host.privateReserved || []) {
        if (!hiddenBack.test(id)) return false;
        const meta = back(id);
        replacements.set(id,remaining.get(meta.pile+meta.tier).pop());
      }
      host.reserved = host.reserved.map(id=>replacements.get(id) || id);
      if (host.privateReserved) host.privateReserved = host.privateReserved.map(id=>replacements.get(id));
      for (const b of boards) b.decks.forEach((deck,i)=>{
        const key = (b === s ? "base" : "orient") + (i+1);
        for (let j=0;j<deck.length;j++) if (deck[j] === null) deck[j] = remaining.get(key).pop();
      });
      return Splendor.validState(s);
    } catch { return false; }
  }

  function persist() { stored = write(hostSave,room); }
  function send(data) {
    if (channel?.readyState !== "open") throw new Error("好友已断开，请重新连接。");
    channel.send(JSON.stringify(data));
  }
  function snapshot(visual = null, fresh = false) {
    send({t:"board",room:room.id,rev:room.rev,mat:room.mat,state:guestView(room.state),visual,fresh});
  }
  function drop() {
    clearTimeout(watchdog);
    clearTimeout(disconnectTimer);
    const pc = peer;
    peer = channel = null;
    ready = pending = false;
    if (pc) pc.close();
  }
  function lost(message) {
    stopDirectory();
    drop();
    if (Table.mode === "lan") Table.render();
    show("lost",message);
  }
  function timeout(pc,message) {
    clearTimeout(watchdog);
    watchdog = setTimeout(()=>{if (peer === pc) lost(message);},15000);
  }
  function beginMatch() {
    room.state = GamePacks.create(room.first,room.packs,{balancedOpening:room.balanced});
    room.rev++;
    aliases.clear();
    persist();
  }
  function connected() {
    ready = true; pending = false;
    clearTimeout(watchdog);
    stopDirectory();
    if (dialog.open) dialog.close();
  }
  function message(event) {
    if (typeof event.data !== "string" || event.data.length > 64000) throw new Error("联机数据无效。");
    const m = JSON.parse(event.data);
    if (!m || m.room !== room.id) throw new Error("房间不一致。");
    if (m.t === "bye") { lost("好友已离开，牌局已暂停。"); return; }
    if (role === 0 && m.t === "join" && !ready) {
      if (!isId(m.key) || (room.friend && room.friend !== m.key)) {
        send({t:"denied",room:room.id}); lost("此牌局已绑定原来的好友。"); return;
      }
      room.friend = m.key;
      if (!room.state) beginMatch();
      connected();
      Table.enterLan(room.state,room.mat);
      snapshot(null,true);
    } else if (role === 1 && m.t === "denied") {
      lost("这局属于另一台设备。请房主另开一桌。");
    } else if (role === 0 && ready && m.t === "move") {
      if (m.rev !== room.rev || room.state.active !== 1 || room.state.phase === "over") { snapshot(); return; }
      try { Table.acceptFriendMove(m.action); }
      catch { snapshot(); }
    } else if (role === 1 && m.t === "board") {
      if (!Number.isSafeInteger(m.rev) || m.rev < 0 || (ready && m.rev < version)) return;
      if (!validView(m.state)) throw new Error("收到的牌局未通过校验，请双方使用同一版本。");
      const continuous = ready && !m.fresh && m.rev === version+1 && m.visual;
      const same = ready && version === m.rev;
      version = m.rev;
      if (!ready) connected();
      else { pending=false; clearTimeout(watchdog); }
      if (continuous) Table.applyFriendView(m.state,m.visual);
      else if (!same || m.fresh) Table.enterLan(m.state,m.mat);
      else Table.render();
    }
  }

  function bindChannel(ch,pc) {
    channel = ch;
    ch.onopen = () => {
      if (pc !== peer) return;
      timeout(pc,"未收到好友的牌局确认，请重新找房。");
      if (role === 1) send({t:"join",room:room.id,key:guestKey});
    };
    ch.onmessage = event => {
      if (pc !== peer) return;
      try { message(event); } catch (error) { lost(error.message || "牌局同步中断。"); }
    };
    ch.onclose = ch.onerror = () => { if (pc === peer) lost("连接已断开。房主重新开放原桌后，好友可搜索续局。"); };
  }
  function startPeer(seat) {
    drop();
    role = seat; version = -1;
    const pc = new RTCPeerConnection({iceServers:[]});
    peer = pc;
    const connectionChanged = () => {
      if (pc !== peer) return;
      clearTimeout(disconnectTimer);
      const status = pc.connectionState || pc.iceConnectionState;
      if (status === "failed") lost("连接失败。请确认两台设备在同一个可互访的 Wi-Fi 下。");
      else if (status === "disconnected") {
        disconnectTimer = setTimeout(()=>{if(pc===peer && (pc.connectionState||pc.iceConnectionState)==="disconnected") lost("连接已中断，请重新开放或搜索棋桌。");},5000);
      }
    };
    pc.onconnectionstatechange = pc.oniceconnectionstatechange = connectionChanged;
    if (seat === 0) bindChannel(pc.createDataChannel("splendor-1",{ordered:true}),pc);
    else pc.ondatachannel = e=>{if(pc===peer && !channel && e.channel.label==="splendor-1") bindChannel(e.channel,pc);};
    return pc;
  }
  async function localDescription(pc,kind) {
    await pc.setLocalDescription(kind === "offer" ? await pc.createOffer() : await pc.createAnswer());
    if (pc.iceGatheringState !== "complete") await new Promise(resolve=>{
      const done = () => { clearTimeout(timer); pc.removeEventListener("icegatheringstatechange",changed); resolve(); };
      const changed = () => { if (pc.iceGatheringState === "complete") done(); };
      const timer = setTimeout(done,5000);
      pc.addEventListener("icegatheringstatechange",changed);
      changed();
    });
    if (pc !== peer) return "";
    const sdp = pc.localDescription.sdp;
    if (!/^a=candidate:/m.test(sdp)) throw new Error("浏览器未提供局域网地址。请用系统浏览器打开，并允许本地网络访问。");
    return sdp;
  }

  const button = (key,label,primary=false) => `<button type="button" data-lan="${key}" class="${primary ? "lan-primary" : ""}">${label}</button>`;
  const nameField = (key,label) => `<label class="lan-field">${label}<input id="${key}" maxlength="18" autocomplete="off"></label>`;
  function savedRoom() {
    const value=read(hostSave);
    return value && isId(value.id) && isId(value.friend) && Number.isSafeInteger(value.rev) && Splendor.validState(value.state) ? value : null;
  }
  function show(page,notice="") {
    screen=page;
    let body="", actions="";
    const inGame=Table.mode === "lan";
    if (page==="menu") {
      body="<p>两部手机打开同一份好友版，连同一个 Wi-Fi。找房时需要联网。</p>";
      if (savedRoom()) actions+=button("resume","继续上次的房间",true);
      actions+=button("setup","我来建房")+button("search","搜索棋桌",true);
    } else if(page==="setup") {
      body=nameField("lan-table-name","棋桌名")+GamePacks.choices(["base"])+GamePacks.openingChoice(false);
      if(savedRoom()) body+='<p>新桌开局后会替换上次的联机存档。</p>';
      actions=button("host","开放棋桌",true);
    } else if(page==="advertising") {
      body='<p class="lan-room-title" id="lan-table-title"></p><p>等待好友在另一部手机上点「搜索棋桌」。</p>';
    } else if(page==="search") {
      body=nameField("lan-guest-name","我的称呼")+'<div id="lan-rooms" aria-label="可加入的棋桌"></div>';
      actions=button("refresh","重新搜索");
    } else if(page==="approval") {
      body='<p id="lan-applicant"></p>';
      actions=button("approve","同意入桌",true)+button("decline","暂不接受");
    } else if(page==="requesting") {
      body='<p id="lan-request-title"></p>';
      actions=button("withdraw","取消申请");
    } else if(page==="room") {
      body='<p>好友已连接 · '+(role===0?"你是房主":"好友是房主")+'</p>';
      actions=button("table","回到棋桌",true)+button("leave","离开牌桌");
    } else if(page==="lost") {
      if (role===0 && room?.state) actions=button("resume","重新开放棋桌",true);
      else if(role===1) actions=button("search","重新搜索棋桌",true);
      else actions=button("menu","重新配对",true);
      if(inGame) actions+=button("leave","返回封面");
    } else if(page==="online") body="<p>正在连接找房服务…</p>";
    else if(page==="working") body="<p>正在建立两部手机之间的连接…</p>";
    if(!inGame && !["menu","lost","requesting","approval"].includes(page)) actions+=button("back","返回");
    if(page==="menu" || (!inGame && page==="lost")) actions+=button("close","关闭");
    if(inGame && ["online","working","advertising","search","requesting","approval"].includes(page)) actions+=button("leave","离开牌桌");
    dialog.innerHTML='<section class="lan-folio"><h2 id="lan-title">局域网好友对战</h2><div class="lan-body">'+body+
      '<p id="lan-note" role="status"></p></div><footer>'+actions+'</footer></section>';
    const note=dialog.querySelector("#lan-note");
    note.textContent=notice || (!stored ? "此浏览器只能在本次打开期间保留联机进度。" : "");
    if(page==="setup") dialog.querySelector("#lan-table-name").value=gemName()+choose(["港","商馆","庭院","驿站"]);
    if(page==="search") {dialog.querySelector("#lan-guest-name").value=guestName;renderRooms();}
    if(page==="advertising") dialog.querySelector("#lan-table-title").textContent=room.label;
    if(page==="approval") dialog.querySelector("#lan-applicant").textContent=`「${contact.name}」想加入「${room.label}」。`;
    if(page==="requesting") dialog.querySelector("#lan-request-title").textContent=`正在申请加入「${contact.name}」，等待房主同意。`;
    if(!dialog.open) dialog.showModal();
  }
  function renderRooms() {
    const list=dialog.querySelector("#lan-rooms");
    if(!list)return;
    const now=Date.now();
    for(const [id,item] of rooms) if(now-item.seen>25000) rooms.delete(id);
    list.replaceChildren();
    let visible=0;
    for(const [id,item] of rooms){
      if(!searchEdition && directory?.network && item.network && item.network!==directory.network)continue;
      visible++;
      const row=document.createElement("button");
      row.type="button"; row.className="lan-listing"; row.dataset.lan="request"; row.dataset.peer=id;
      const label=document.createElement("b"),join=document.createElement("span");
      label.textContent=item.name; join.textContent=item.resume ? "续局 ›" : "加入 ›";
      const mark=document.createElement("span");
      mark.className="lan-mark";mark.innerHTML=Table.gem(parseInt(item.room.slice(-2),16)%5);
      row.append(mark,label,join);list.appendChild(row);
    }
    if(!visible) list.textContent="暂无开放的棋桌。房主开放后会自动显示。";
    if(!searchEdition && rooms.size>visible) {
      const more=document.createElement("button");
      more.type="button";more.dataset.lan="widen";more.textContent="网络出口不同？查看同版棋桌";
      list.appendChild(more);
    }
  }
  function stopDirectory(notifyPeer=false) {
    clearInterval(listingTimer);
    clearTimeout(relayTimer);
    clearTimeout(watchdog);
    const other=contact;
    rooms.clear();listingVersions.clear();withdrawn.clear();contact=null;
    const old=directory;
    directory=null;
    if(old){
      if(role===0 && gonePacket){try{old.publish(gonePacket);}catch{/* Listing also expires. */}}
      if(notifyPeer && other && room)
        old.send({t:role===1 ? "cancel" : "decline",ticket:other.ticket,room:room.id},other.target)
          .catch(()=>{}).finally(()=>old.close());
      else old.close();
    }
    gonePacket="";
  }
  function advertise() {
    return directory.send({t:"table",serial:++serial,room:room.id,name:room.label,resume:!!room.state,network:directory.network||""});
  }
  async function announce() {
    if(screen==="advertising") await advertise();
    if(screen==="search") {renderRooms();await directory.send({t:"find"});}
  }
  async function startDirectory(seat) {
    stopDirectory();drop();role=seat;version=-1;serial=0;searchEdition=false;
    show("online");
    const d=new RoomDirectory(async (m,from,direct)=>{
      if(directory!==d)return;
      try {await handleSignal(d,m,from,direct);}
      catch(error){if(directory===d)lost(error.message || "联机协商中断，请重新搜索。");}
    },online=>{
      if(directory!==d)return;
      clearTimeout(relayTimer);
      if(online) announce().catch(()=>{});
      else relayTimer=setTimeout(()=>{
        if(directory===d && !d.online.size && !peer?.remoteDescription) lost("找房服务已断开。请检查互联网连接后重试。");
      },5000);
    });
    directory=d;
    try {
      await d.start();
      if(directory!==d)return;
      const gone=await d.pack({t:"gone",serial:Number.MAX_SAFE_INTEGER});
      if(directory!==d)return;
      gonePacket=gone;
      show(seat===0 ? "advertising" : "search");
      await announce();
      if(directory!==d)return;
      listingTimer=setInterval(()=>{
        if(directory===d && screen==="search" && !document.hidden) announce().catch(()=>{});
      },8000);
    } catch(error){
      if(directory===d) lost(error instanceof AggregateError ? "找房服务暂时不可达，请检查两部手机的互联网连接后重试。" : error.message);
    }
  }
  async function host(resume) {
    const previous=resume ? (role===0 && room?.state ? room : savedRoom()) : null;
    if(resume && !previous) throw new Error("找不到可恢复的房间。");
    room=previous || {id:randomId(),rev:0,first:0,friend:null,state:null,
      label:cleanName(dialog.querySelector("#lan-table-name").value),
      packs:GamePacks.readChoices(dialog),balanced:dialog.querySelector("[data-balanced-opening]").checked,mat:Table.mat};
    room.label=cleanName(room.label) || gemName()+"棋桌";
    await startDirectory(0);
  }
  async function search() {
    if(!isId(guestKey)) {guestKey=randomId();stored=write(guestSave,guestKey);}
    if(!guestName) guestName=gemName()+"访客";
    if(Table.mode!=="lan") room=null;
    await startDirectory(1);
  }
  async function requestSeat(target) {
    const listing=rooms.get(target);
    if(screen!=="search" || !listing || Date.now()-listing.seen>25000) {renderRooms();return;}
    guestName=cleanName(dialog.querySelector("#lan-guest-name").value) || guestName;
    write("splendor.lan.name",guestName);
    room={id:listing.room};
    const ticket=randomId();
    const d=directory, id=room.id;
    contact={target,ticket,name:listing.name};
    show("requesting");
    watchdog=setTimeout(()=>cancelRequest("房主暂未回应，可重新申请。"),45000);
    const proof=listing.resume ? await seatProof(guestKey,id,ticket) : "";
    if(directory===d && contact?.ticket===ticket) await d.send({t:"knock",ticket,room:id,name:guestName,proof},target);
  }
  async function seatProof(key,id,ticket) {
    const bytes=new TextEncoder().encode([key,id,ticket].join(":"));
    const digest=await crypto.subtle.digest("SHA-256",bytes);
    return Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,"0")).join("");
  }
  function matching(m,from) {
    return contact && from===contact.target && m.ticket===contact.ticket && m.room===room?.id;
  }
  function resetLobby(notice) {
    drop();contact=null;
    show(role===0 ? "advertising" : "search",notice);
    announce().catch(()=>{});
  }
  function cancelRequest(notice) {
    if(!contact || !directory)return;
    directory.send({t:"cancel",room:room.id,ticket:contact.ticket},contact.target).catch(()=>{});
    resetLobby(notice);
  }
  async function decline() {
    if(screen!=="approval" || !contact)return;
    const {target,ticket}=contact;
    const notify=directory.send({t:"decline",room:room.id,ticket},target);
    resetLobby("棋桌继续等待好友。");
    await notify;
  }
  async function approve() {
    if(screen!=="approval" || !contact)return;
    const accepted=contact, d=directory;
    const pc=startPeer(0);
    show("working");
    timeout(pc,"好友未能连接。请确认同一 Wi-Fi 允许设备互访，再重新开放棋桌。");
    try {
      const sdp=await localDescription(pc,"offer");
      if(peer===pc && contact===accepted && directory===d)
        await d.send({t:"offer",room:room.id,ticket:accepted.ticket,sdp},accepted.target);
    } catch(error){if(peer===pc)throw error;}
  }
  async function handleSignal(d,m,from,direct) {
    if(!m || typeof m.t!=="string")return;
    if(!direct){
      if(m.t==="find" && role===0 && screen==="advertising") await advertise();
      if(role===1 && screen==="search"){
        if(!["table","gone"].includes(m.t) || !Number.isSafeInteger(m.serial) || m.serial<1 ||
           m.serial<=(listingVersions.get(from)||0)) return;
        listingVersions.set(from,m.serial);
        if(listingVersions.size>128)listingVersions.delete(listingVersions.keys().next().value);
        if(m.t==="table" && isId(m.room) && cleanName(m.name) &&
           (Table.mode!=="lan" || m.room===room?.id) && (rooms.has(from) || rooms.size<48)){
          rooms.set(from,{room:m.room,name:cleanName(m.name),resume:m.resume===true,
            network:typeof m.network==="string" ? m.network.slice(0,44) : "",seen:Date.now()});
          renderRooms();
        } else if(m.t==="gone"){rooms.delete(from);renderRooms();}
      }
      return;
    }
    if(!isId(m.ticket) || m.room!==room?.id)return;
    const requestId=from+"|"+m.ticket;
    if(m.t==="cancel" && role===0){
      withdrawn.add(requestId);
      if(withdrawn.size>64)withdrawn.delete(withdrawn.values().next().value);
      if(matching(m,from))resetLobby("好友已取消申请。");
      return;
    }
    if(m.t==="knock" && role===0) {
      if(room.friend && m.proof!==await seatProof(room.friend,m.room,m.ticket)) {
        if(directory===d) await d.send({t:"bound",ticket:m.ticket,room:m.room},from);
        return;
      }
      if(directory!==d || withdrawn.has(requestId))return;
      if(screen!=="advertising"){
        if(!matching(m,from)) await d.send({t:"busy",ticket:m.ticket,room:m.room},from);
        return;
      }
      contact={target:from,ticket:m.ticket,name:cleanName(m.name)||"好友"};
      show("approval");
      watchdog=setTimeout(()=>decline().catch(()=>{}),40000);
      await d.send({t:"gone",serial:++serial});
      return;
    }
    if(!matching(m,from))return;
    if(["busy","decline","bound"].includes(m.t) && role===1 && ["requesting","working"].includes(screen)){
      rooms.delete(from);
      resetLobby(m.t==="bound" ? "请用原来加入这局的设备和浏览器续局。" :
        m.t==="busy" ? "这张桌正在接待另一位好友。" : "房主暂未接受申请。");
      return;
    }
    if(typeof m.sdp!=="string" || m.sdp.length>40000 || !m.sdp.startsWith("v=0"))return;
    if(role===1 && screen==="requesting" && m.t==="offer"){
      const pc=startPeer(1);
      show("working");
      timeout(pc,"未能直连。请检查本地网络权限，并避开隔离设备的访客 Wi-Fi。");
      try {
        await pc.setRemoteDescription({type:"offer",sdp:m.sdp});
        const sdp=await localDescription(pc,"answer");
        if(pc===peer && directory===d) await d.send({t:"answer",room:m.room,ticket:m.ticket,sdp},from);
      } catch(error){if(pc===peer)throw error;}
    } else if(role===0 && screen==="working" && m.t==="answer" && peer?.signalingState==="have-local-offer"){
      const pc=peer;
      try {await pc.setRemoteDescription({type:"answer",sdp:m.sdp});}
      catch(error){if(pc===peer)throw error;}
    }
  }
  function cancel() {
    if(Table.mode==="lan"){if(ready)dialog.close();return;}
    stopDirectory(true);drop();role=null;room=null;dialog.close();
  }
  function open() {
    if(typeof RTCPeerConnection!=="function" || !globalThis.crypto?.subtle) {
      show("menu","此打开方式不支持加密直连，请用系统浏览器打开游戏。");
      for(const el of dialog.querySelectorAll("[data-lan]:not([data-lan=close])")) el.disabled=true;
    } else show(Table.mode==="lan" ? (ready ? "room" : "lost") : "menu");
  }
  dialog.addEventListener("cancel",event=>{event.preventDefault();cancel();});
  document.addEventListener("visibilitychange",()=>{
    if(!document.hidden && directory)announce().catch(()=>{});
  });
  window.addEventListener("pagehide",()=>{if(directory)stopDirectory();});
  window.addEventListener("pageshow",event=>{
    if(event.persisted && !directory && dialog.open && !ready && !["menu","setup","lost"].includes(screen))
      lost("页面已恢复，请重新开放或搜索棋桌。");
  });
  dialog.addEventListener("click",async event=>{
    const el=event.target.closest("[data-lan]");
    if(!el)return;
    try {
      switch(el.dataset.lan){
        case "close": case "table": cancel();break;
        case "leave":
          if(channel?.readyState==="open")send({t:"bye",room:room.id});
          stopDirectory(true);drop();location.reload();break;
        case "back": case "menu": stopDirectory(true);drop();role=null;room=null;show("menu");break;
        case "setup": show("setup");break;
        case "search": await search();break;
        case "host": case "resume": await host(el.dataset.lan==="resume");break;
        case "refresh": rooms.clear();await announce();break;
        case "widen": searchEdition=true;renderRooms();break;
        case "request": await requestSeat(el.dataset.peer);break;
        case "approve": await approve();break;
        case "decline": await decline();break;
        case "withdraw": cancelRequest("已取消申请。");break;
      }
    } catch(error) {
      if(!dialog.open)return;
      if(["working","online","requesting"].includes(screen)) lost(error.message || "连接失败，请重试。");
      else dialog.querySelector("#lan-note").textContent=error.message || "请重试。";
    }
  });
  globalThis.Lan=Object.freeze({open,back,get seat(){return role;},get waiting(){return !ready || pending;},
    propose(action) {
      if(role!==1 || !ready || pending)return;
      try {
        send({t:"move",room:room.id,rev:version,action});
        pending=true;
        // Leave selected pieces lifted until the authoritative move starts their flight.
        document.getElementById("turn-action").disabled=true;
        timeout(peer,"同步中断，请重新连接并核对最后一步。");
      }
      catch { lost("未能发送这一步，请重新连接。"); }
    },
    commit(next,visual) {
      const previous=room.state;
      room.state=next;room.rev++;persist();
      const move={type:visual.type};
      if(visual.id && Splendor.cards[visual.id]) move.id=visual.id;
      if(visual.type==="buy" && previous.active===0 && previous.players[0].privateReserved?.includes(visual.id))
        move.fromBack=aliases.get(visual.id);
      if(visual.tier){move.tier=visual.tier;move.pile=visual.pile || "base";}
      try {snapshot(move);} catch {lost("连接已断开，房主保留了最后一步。");}
    },
    rematch() {
      if(role!==0 || !ready || room.state.phase!=="over")return;
      room.first=1-room.state.first;
      beginMatch();Table.enterLan(room.state,room.mat);snapshot(null,true);
    }
  });
})();

(() => {
  "use strict";

  const registry = new Map();
  const identifier = id => typeof id === "string" && /^[a-z][a-z0-9-]{0,63}$/.test(id);

  function register({id, name, detail = "", required = false, setup}) {
    if (!identifier(id) || registry.has(id) || typeof name !== "string" || !name.trim() ||
        (setup !== undefined && typeof setup !== "function")) throw new Error("扩展包信息无效。");
    registry.set(id, Object.freeze({id, name, detail, required, setup}));
  }
  register({id:"base", name:"基础版", required:true});
  const boxes = [
    {id:"silk-road", name:"丝绸之路", en:"The Silk Road", modules:[["cities","繁华之城","城市目标"],["trading-posts","贸易之路","贸易站能力"]]},
    {id:"sun-never-sets", name:"永昼之地", en:"The Sun Never Sets", modules:[["orient","东方之门","东方发展牌"],["strongholds","荣誉之战","要塞与征服"]]}
  ];
  for (const box of boxes) for (const [id,name,detail] of box.modules) register({id,name,detail});

  function selection(ids) {
    const picked = new Set(Array.isArray(ids) ? ids : []);
    return Array.from(registry.values()).filter(pack => pack.required || picked.has(pack.id)).map(pack => pack.id);
  }

  function savedSelection(ids) {
    return Array.from(new Set(["base", ...(Array.isArray(ids) ? ids.filter(identifier) : [])]));
  }

  function create(first, ids, {balancedOpening = false} = {}) {
    const state = Splendor.newGame(first,Math.random,ids,{balancedOpening});
    for (const id of ids) registry.get(id)?.setup?.(state);
    if (!Splendor.validState(state)) throw new Error("所选游戏内容无法建立对局。");
    return state;
  }

  function choices(ids) {
    const current = selection(ids);
    function option(pack) {
      const required = pack.required ? ' disabled' : '';
      return '<label class="pack-choice"><input type="checkbox" data-pack="' + pack.id + '"' +
        (current.includes(pack.id) ? ' checked' : '') + required + '><span>' + Table.escape(pack.name) +
        (pack.detail ? '<i class="pack-purpose">'+Table.escape(pack.detail)+'</i>' : '') +
        '</span>' + (pack.required ? '<small>必选</small>' : '') + '</label>';
    }
    const contents = boxes.map(box => {
      const all = box.modules.every(([id])=>current.includes(id));
      return '<section class="exp-box" data-box="' + box.id + '"><label class="box-title"><input type="checkbox" data-box-check="' +
        box.id + '"' + (all ? ' checked' : '') + '><span><b>' + box.name + '</b><i lang="en">' + box.en +
        '</i></span></label><div class="box-modules">' + box.modules.map(([id])=>option(registry.get(id))).join("") + '</div></section>';
    }).join("");
    const official = new Set(boxes.flatMap(box=>box.modules.map(([id])=>id)));
    const other = Array.from(registry.values()).filter(pack=>!official.has(pack.id) && pack.id!=="base");
    return '<fieldset class="pack-list"><legend>游戏内容<small class="base-included">基础版已含</small></legend>' +
      '<div class="exp-boxes">' + contents + '</div>' + other.map(option).join("") + '</fieldset>';
  }

  function syncChoices(parent) {
    for (const box of parent.querySelectorAll(".exp-box")) {
      const fields = Array.from(box.querySelectorAll("input[data-pack]"));
      const selected = fields.filter(f=>f.checked).length;
      const master = box.querySelector("input[data-box-check]");
      master.checked = selected === fields.length;
      master.indeterminate = selected > 0 && selected < fields.length;
    }
  }
  document.addEventListener("change",event=>{
    const box = event.target.closest?.(".exp-box");
    if (!box) return;
    if (event.target.matches("input[data-box-check]")) {
      for (const field of box.querySelectorAll("input[data-pack]")) field.checked=event.target.checked;
    }
    syncChoices(box.parentElement);
  });

  function readChoices(parent) {
    return selection(Array.from(parent.querySelectorAll("input[data-pack]:checked"), input => input.dataset.pack));
  }

  function openingChoice(enabled, nextOnly = false) {
    return '<label class="opening-choice"><input type="checkbox" data-balanced-opening aria-description="异色有两种就拿满两枚。同色拿两枚仍须该堆有四枚。"'+ (enabled ? " checked" : "") +
      '><span>' + (nextOnly ? '<small>下局</small>' : '') + '先手首回合拿两枚筹码</span></label>';
  }

  function modeChoice(mode, group) {
    return '<fieldset class="match-choice"><legend>对局模式</legend><div>' +
      [["local","双人同桌"],["solo","人机对局"]].map(([value,label]) =>
        '<label><input type="radio" name="' + group + '" data-match-mode value="' + value + '"' +
        (mode === value ? ' checked' : '') + '><span>' + label + '</span></label>').join("") + '</div></fieldset>';
  }
  function readMode(parent) { return parent.querySelector("[data-match-mode]:checked")?.value === "solo" ? "solo" : "local"; }

  function difficultyChoice(level, group, mode) {
    if (!RivalTurn.supportsHard) return "";
    return '<fieldset class="rival-choice"' + (mode === "solo" ? '' : ' hidden disabled') + '><legend>电脑难度</legend><div>' +
      [["easy","简单"],["hard","困难"]].map(([value,word]) =>
        '<label><input type="radio" data-rival-difficulty name="' + group + '" value="' + value + '"' +
        (value === level ? ' checked' : '') + '><span>' + word + '</span></label>').join("") + '</div></fieldset>';
  }
  function readDifficulty(parent) {
    return parent.querySelector("[data-rival-difficulty]:checked")?.value || Table.difficulty;
  }
  function showDifficulty(parent, mode) {
    const choice = parent.querySelector(".rival-choice");
    if (choice) choice.hidden = choice.disabled = mode !== "solo";
  }

  // Keep both drafts while comparing modes within a new-game folio.
  function bindMatchForm(parent, initialMode) {
    const opening = parent.querySelector("[data-balanced-opening]");
    const picker = parent.querySelector(".pack-list");
    const variants = {local:Table.nextOpening("local"), solo:Table.nextOpening("solo")};
    variants[initialMode] = opening.checked;
    let previous = initialMode;
    const update = () => {
      variants[previous] = opening.checked;
      const next = readMode(parent);
      opening.checked = variants[next];
      showDifficulty(parent,next);
      picker.classList.toggle("base-only", next === "solo");
      picker.querySelector(".exp-boxes").hidden = next === "solo";
      for (const child of picker.children) if (child.matches(".pack-choice") && !child.querySelector("[data-pack=base]")) child.hidden = next === "solo";
      const label = parent.querySelector("[data-second-name]");
      if (label) label.textContent = next === "solo" ? Table.playerName(1,"solo") : label.dataset.secondName;
      previous = next;
    };
    for (const field of parent.querySelectorAll("[data-match-mode]")) field.addEventListener("change",update);
    update();
  }
  globalThis.GamePacks = Object.freeze({register, selection, savedSelection, create, choices, openingChoice, modeChoice, readMode, difficultyChoice, readDifficulty, bindMatchForm, readChoices, syncChoices, boxes});

  const cover = document.getElementById("game-cover");
  const dialog = document.getElementById("cover-dialog");
  const primary = document.getElementById("cover-primary");
  const surface = document.getElementById("surface");
  let proposed = ["base"];
  let proposedMode = "local";
  let proposedDifficulty = "easy";
  let proposedFirst = null;
  let curtain = null;

  function show(focus = true) {
    const state = Table.state;
    proposed = selection(Table.packs);
    proposedMode = Table.mode;
    proposedDifficulty = Table.difficulty;
    proposedFirst = null;
    curtain?.cancel();
    curtain = null;
    if (!surface.hidden) BoardMotion.clear();
    surface.inert = true;
    surface.hidden = true;
    cover.hidden = false;
    cover.inert = false;
    cover.removeAttribute("aria-hidden");
    const progress = document.getElementById("cover-progress");
    progress.replaceChildren();
    document.getElementById("cover-start-error").hidden = true;
    cover.querySelector("[data-screen-note]").textContent = "";
    if (state) {
      const labels = [Table.playerName(0), Table.playerName(1)];
      const names = labels.map(value => {
        const name = document.createElement("span");
        name.textContent = name.title = value;
        return name;
      });
      const score = document.createElement("b");
      const scores = [Splendor.score(state, 0), Splendor.score(state, 1)];
      score.textContent = scores.join(" – ");
      progress.setAttribute("aria-label", labels.map((value, i) => value + "，" + scores[i] + " 声望").join("。"));
      progress.append(names[0], score, names[1]);
    }
    progress.hidden = !state;
    const selector = document.getElementById("cover-mode");
    selector.hidden = !!state;
    if (!state) {
      selector.innerHTML = modeChoice(proposedMode, "cover-mode") + difficultyChoice(proposedDifficulty,"cover-difficulty",proposedMode);
      selector.onchange = () => {
        proposedMode = readMode(selector);
        proposedDifficulty = readDifficulty(selector);
        showDifficulty(selector,proposedMode);
      };
    }
    primary.textContent = state?.phase === "over" ? "查看上局" : state ? "继续对局" : "开始对局";
    primary.dataset.lobby = state ? "continue" : "start";
    cover.querySelector('[data-lobby="new"]').hidden = !state;
    if (focus) primary.focus({preventScroll:true});
    RivalTurn.sync();
  }

  function enter() {
    if (cover.hidden || cover.inert) return;
    if (dialog.open) dialog.close();
    BoardFullscreen.onEntry();
    surface.hidden = false;
    surface.inert = false;
    document.getElementById("playfield").focus({preventScroll:true});
    cover.inert = true;
    cover.setAttribute("aria-hidden", "true");
    if (matchMedia("(prefers-reduced-motion: reduce)").matches || !cover.animate) {
      cover.hidden = true;
      return;
    }
    BoardMotion.warmVisitorLight();
    const fade = cover.animate([{opacity:1}, {opacity:0}], {duration:165, easing:"ease-out", fill:"both"});
    curtain = fade;
    fade.onfinish = () => {
      if (curtain !== fade) return;
      cover.hidden = true;
      curtain = null;
      fade.cancel();
    };
  }

  function resume() {
    if (!Table.hasGame) return;
    enter();
    Table.render();
    if (Table.state.phase === "over" && !Controls.modalOpen) Controls.open("result");
  }

  function openDialog(mode) {
    if (dialog.open) return;
    const fresh = mode === "new";
    const title = fresh ? "新开一局？" : "新局设置";
    const first = proposedFirst ?? Table.options.nextFirst ?? (Table.state ? 1 - Table.state.first : 0);
    const seats = Table.options.names.map((name, i) => '<label><input type="radio" name="cover-first" value="' + i + '"' +
      (i === first ? ' checked' : '') + '><span' + (i ? ' data-second-name="'+Table.escape(name)+'"' : '') + '>' + Table.escape(name) + '</span></label>');
    const content = (fresh ? '<p class="cover-dialog-note">确认后将替换当前对局，重新洗牌开局。</p>' : '') +
      modeChoice(proposedMode, "cover-dialog-mode") + difficultyChoice(proposedDifficulty,"cover-dialog-difficulty",proposedMode) +
      '<fieldset class="lobby-first"><legend>先手玩家</legend><div>' +
      seats.join("") + '</div></fieldset>';
    dialog.innerHTML = '<div class="cover-dialog-body"><h2 id="cover-dialog-title">' + title + '</h2><div class="cover-dialog-fields">' + content +
      openingChoice(Table.nextOpening(proposedMode),!fresh && Table.hasGame) + choices(proposed) +
      '</div><p class="cover-error" role="alert" hidden></p><div class="cover-dialog-actions"><button type="button" data-lobby="cancel">取消</button>' +
      '<button type="button" class="cover-dialog-primary" data-lobby="' + (fresh ? 'confirm-new' : 'apply-packs') + '">' +
      (fresh ? '确认开局' : '完成') + '</button></div></div>';
    syncChoices(dialog);
    bindMatchForm(dialog,proposedMode);
    dialog.showModal();
    dialog.querySelector('[data-lobby="cancel"]').focus({preventScroll:true});
  }

  cover.addEventListener("click", event => {
    const button = event.target.closest("button[data-lobby]");
    if (!button || cover.hidden || cover.inert || button.disabled) return;
    if (dialog.open && !dialog.contains(button)) return;
    switch (button.dataset.lobby) {
      case "start":
        if (Table.hasGame) openDialog("new");
        else try {
          Table.newGame(proposedFirst ?? Table.options.nextFirst ?? 0,proposed,{mode:proposedMode,difficulty:proposedDifficulty});
        } catch (problem) {
          const error = document.getElementById("cover-start-error");
          error.textContent = problem.message;
          error.hidden = false;
        }
        break;
      case "continue": resume(); break;
      case "lan": Lan.open(); break;
      case "new": case "packs": openDialog(button.dataset.lobby); break;
      case "cancel": dialog.close(); break;
      case "apply-packs":
        proposed = readChoices(dialog);
        proposedMode = readMode(dialog);
        proposedDifficulty = readDifficulty(dialog);
        proposedFirst = Number(dialog.querySelector("input[name=cover-first]:checked").value);
        Table.setNextOpening(dialog.querySelector("[data-balanced-opening]").checked,proposedMode);
        const coverMode = document.querySelector('#cover-mode input[value="' + proposedMode + '"]');
        if (coverMode) coverMode.checked = true;
        const coverDifficulty = document.querySelector('#cover-mode [data-rival-difficulty][value="' + proposedDifficulty + '"]');
        if (coverDifficulty) coverDifficulty.checked = true;
        showDifficulty(document.getElementById("cover-mode"),proposedMode);
        dialog.close();
        break;
      case "confirm-new": {
        const first = Number(dialog.querySelector("input[name=cover-first]:checked").value);
        try {
          Table.newGame(first,readChoices(dialog),{mode:readMode(dialog),difficulty:readDifficulty(dialog),nextFirst:first,balancedOpening:dialog.querySelector("[data-balanced-opening]").checked});
        } catch (problem) {
          const error = dialog.querySelector(".cover-error");
          error.textContent = problem.message;
          error.hidden = false;
        }
        break;
      }
    }
  });
  cover.addEventListener("keydown", event => {
    if (event.repeat && (event.key === "Enter" || event.key === " ")) event.preventDefault();
  });
  globalThis.GameLobby = Object.freeze({show, enter, resume});
})();

(() => {
  "use strict";

  const gemNames = ["钻石", "蓝宝石", "祖母绿", "红宝石", "缟玛瑙", "黄金"];
  const tierNames = ["", "Ⅰ", "Ⅱ", "Ⅲ"];
  const emptyCounts = Object.freeze([0, 0, 0, 0, 0, 0]);
  const phaseButton = {over: "result", discard: "discard", noble: "noble"};
  const buttonCaption = {take: "拿取", buy: "购买", reserve: "预留", discard: "归还", noble: "迎接", pass: "跳过", result: "结算"};
  const validKinds = new Set(["player", "noble", "rules", "settings", "result", "resetConfirm"]);
  let view = null;
  let bankDraft = null;
  let cardDraft = null;
  let returnDraft = null;
  let visitorDraft = null;
  let computerDraft = null;
  let opener = null;
  let resultShown = false;
  let waitingForResult = null;
  let changingState = false;
  let closeWatcher = null;
  let buttonPress = null;
  let suppressClickUntil = 0;
  const inertElements = new Set();

  const table = () => globalThis.Table;
  const engine = () => globalThis.Splendor;
  const sum = values => values.reduce((total, n) => total + n, 0);
  const emptyTokens = () => emptyCounts.slice();
  const hasSelection = () => !computerDraft && !!(bankDraft || cardDraft || returnDraft || visitorDraft);
  const icon = name => table().icon(name);
  const gem = color => table().gem(color);
  const escape = value => String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  const playerName = id => table().playerName(id);
  const getLayer = () => document.getElementById("dialog-layer");
  const button = (action, label, options = {}) => {
    const { value, variant = "secondary", disabled = false, symbol, attrs = "" } = options;
    return `<button type="button" class="dlg-button dlg-${variant}" data-dlg="${action}" ${value === undefined ? "" : `data-value="${escape(value)}"`} ${disabled ? "disabled" : ""} ${attrs}>${symbol ? icon(symbol) : ""}<span>${escape(label)}</span></button>`;
  };

  function costs(values, zeroLabel = "免费") {
    const html = values.map((n, i) => n > 0
      ? `<span class="dlg-price" aria-label="${gemNames[i]}${n}枚" title="${gemNames[i]} × ${n}">${gem(i)}<b>${n}</b></span>` : "").join("");
    return html || `<span class="dlg-free">${escape(zeroLabel)}</span>`;
  }

  function labeledRow(label, html) {
    return `<div class="dlg-row"><span class="dlg-row-label">${escape(label)}</span><div class="dlg-row-content">${html}</div></div>`;
  }

  function note(text, type = "") {
    return text ? `<p class="dlg-note ${type}">${escape(text)}</p>` : "";
  }

  function rememberOpener() {
    const element = document.activeElement;
    if (!element || element === document.body || getLayer()?.contains(element)) return;
    const attributes = Array.from(element.attributes).filter(a => a.name.startsWith("data-") || a.name === "aria-label" || a.name === "id");
    opener = { element, attributes: attributes.map(a => [a.name, a.value]) };
  }

  function restoreFocus() {
    if (!opener) return;
    let element = opener.element.isConnected ? opener.element : null;
    if (!element && opener.attributes.length) {
      const candidates = Array.from(document.querySelectorAll("button, [role=button], [tabindex]"));
      element = candidates.find(candidate => opener.attributes.every(([name, value]) => candidate.getAttribute(name) === value));
      if (!element) {
        const stable = opener.attributes.filter(([name]) => name === "id" || name.startsWith("data-"));
        if (stable.length) element = candidates.find(candidate => stable.every(([name, value]) => candidate.getAttribute(name) === value));
      }
    }
    element?.focus({ preventScroll: true });
    opener = null;
  }

  function setBoardInert(inert) {
    if (!inert) {
      inertElements.forEach(el => { el.inert = false; });
      inertElements.clear();
      return;
    }
    const layer = getLayer();
    if (!layer?.parentElement) return;
    for (const sibling of layer.parentElement.children) {
      if (sibling === layer || sibling.inert || ["SCRIPT", "STYLE", "LINK"].includes(sibling.tagName)) continue;
      sibling.inert = true;
