    view = null;
    const layer = getLayer();
    if (layer) {
      layer.replaceChildren();
      layer.classList.remove("dlg-open");
    }
    setBoardInert(false);
    watchTransient();
    if (previewing && !keepAudioPreview) BoardMusic.configure(table().options.music,table().options.musicVolume);
