  }

  function makeView(kind, arg, previous = null, overrides = {}) {
    const state = table().state;
    if (!validKinds.has(kind)) return null;
    if (kind === "noble") arg = engine().nobles[arg]?.id ?? arg;
    if (kind === "noble" && (!engine().nobles[arg] || !(state.nobles.includes(arg) || state.players.some(p => p.nobles.includes(arg))))) return null;
    if (kind === "player" && ![0, 1].includes(Number(arg))) return null;
    const draft = {};
    if (kind === "player") {
      draft.tab = "assets";
    }
    if (kind === "settings" || kind === "resetConfirm") {
      draft.mode = table().mode;
      draft.difficulty = table().difficulty;
      draft.assist = table().options.assist;
      draft.names = table().options.names.slice();
      draft.sound = table().options.sound === true;
      draft.haptics = table().options.haptics;
      draft.music = table().options.music !== false;
      draft.musicVolume = table().options.musicVolume;
      draft.packs = table().packs;
      draft.balancedOpening = kind === "settings" && table().openingEditable ? state.balancedOpening === true : table().nextOpening();
      draft.nextFirst = table().options.nextFirst ?? (kind === "resetConfirm" ? 1 - state.first : state.first);
    }
    return { kind, arg, state, previous, draft: Object.assign(draft, overrides), error: "" };
  }

  function open(kind, arg, tab, pile = "base") {
    const state = table()?.state;
    if (table()?.computerTurn && !["settings","rules"].includes(kind)) return;
    if (!state || !getLayer()) return;
    const reading = ["rules", "noble", "player"].includes(kind);
    if (table().friendWaiting && !reading && !["settings","result"].includes(kind)) return;
    if (state.phase === "discard" && !reading && kind !== "settings") return;
    if (state.phase === "effect" && kind === "card" && ExUI.onCard(arg)) return;
    if (state.phase === "effect" && kind === "bank") { ExUI.onToken(Number(arg)); return; }
    if (kind === "player" && (tab === "reserved" || tab === "reserve-slot")) {
      const owner = Number(arg);
      if (![0, 1].includes(owner) || ["discard","noble"].includes(state.phase)) return;
      if (view) clearView(false);
      if (tab === "reserve-slot" && owner === state.active && state.phase === "action" && !table().friendWaiting) {
        beginReservation();
        return;
      }
      if (ReserveHand.owner === owner) {
        ReserveHand.close({restoreFocus:true});
        drawSelection();
        return;
      }
      if (state.players[owner].reserved.length) {
        if (owner === state.active && state.phase === "action") clearSelection();
        ReserveHand.open(owner);
        table().feel?.("fan");
        drawSelection();
      } else if (owner === state.active && state.phase === "action" && !table().friendWaiting) beginReservation();
      return;
    }
    if (ReserveHand.owner !== null) {
      ReserveHand.close();
      watchTransient();
    }
    if (kind === "noble" && !table().friendWaiting && state.phase === "noble" && state.nobles.includes(arg)) {
      selectVisitor(arg);
      return;
    }
    if (kind === "card") { selectMarketCard(arg); return; }
    if (kind === "deck") { selectDeck(Number(arg),pile); return; }
    if (kind === "bank") {
      const color = arg === undefined || arg === null ? null : Number(arg);
      if (color !== null && (!Number.isInteger(color) || color < 0 || color > 5)) return;
      if (state.phase !== "action") return;
      if (view) clearView(false);
      if (color === 5) { reject(document.querySelector("#bank .pile-5")); return; }
      selectFromBank(state, color);
      return;
    }
    if (!reading) clearSelection();
    if (kind === "result" && state.phase !== "over") return;
    const next = makeView(kind, arg);
    if (!next) return;
    if (kind === "player" && ["assets", "nobles"].includes(tab)) next.draft.tab = tab;
    if (!view) rememberOpener();
    if (kind === "result") resultShown = true;
    view = next;
    draw();
  }

  function navigate(kind, arg, overrides) {
    const next = makeView(kind, arg, view, overrides);
    if (!next) return;
    view = next;
    draw();
  }

  function close() {
    if (view) { clearView(); return; }
    if (ReserveHand.readOnly) {
      ReserveHand.close({restoreFocus:true});
      drawSelection();
    } else clearSelection(true);
  }

  function back() {
    if (!view?.previous) { close(); return; }
    view = view.previous;
    view.error = "";
    draw();
  }

  function transientOpen() {
    return hasSelection() || ReserveHand.owner !== null || !!view;
  }

  function backOneLayer() {
    if (!transientOpen()) return false;
    if (view?.previous) back();
    else close();
    return true;
  }

  // A native close request handles Android Back without adding synthetic history entries.
  function watchTransient() {
    RivalTurn.sync();
    if (!transientOpen()) {
      closeWatcher?.destroy();
      closeWatcher = null;
      return;
    }
    if (closeWatcher || typeof window.CloseWatcher !== "function") return;
    try {
      const watcher = new window.CloseWatcher();
      closeWatcher = watcher;
      watcher.addEventListener("close", () => {
        if (closeWatcher !== watcher) return;
        closeWatcher = null;
        backOneLayer();
        watchTransient();
      }, { once: true });
