      // Embedded browsers can expose the constructor outside an active document.
    }
  }

  function sync() {
    const board = table();
    if (changingState || !board?.state || !getLayer()) return;
    const state = board.state;
    if (computerDraft && computerDraft.state !== state) computerDraft = null;
    if (ReserveHand.owner !== null && ReserveHand.state !== state) {
      const owner = ReserveHand.owner;
      const purchased = ReserveHand.state.players[owner].reserved.find(id => state.players[owner].cards.includes(id));
      ReserveHand.close({animated:!!purchased, purchased});
    }
    if (state.phase !== "action" || (bankDraft && bankDraft.state !== state)) bankDraft = null;
    if (cardDraft && (cardDraft.state !== state || !engine().canSelectBuy(state,cardDraft.id))) cardDraft = null;
    if (state.phase !== "discard" || (returnDraft && returnDraft.state !== state)) returnDraft = null;
    if (state.phase !== "noble" || (visitorDraft && visitorDraft.state !== state)) visitorDraft = null;
    drawSelection();
    if (state.phase !== "over") resultShown = false;
    if (state.phase === "over" && !board.passingTurn && !resultShown) {
      if (!ExUI.pieces?.busy) { open("result"); return; }
      if (waitingForResult !== state) {
        waitingForResult = state;
        ExUI.pieces.settled().then(() => {
          if (waitingForResult === state) waitingForResult = null;
          if (board.state === state && !resultShown) sync();
        });
      }
    }
    if (view && view.state !== state) { clearView(); return; }
    if (view && !getLayer().querySelector(".dlg-panel")) draw();
