    if (state.balancedOpening && table().openingEditable && sum(picked) >= 2) return false;
    if (picked[color]) return picked[color] === 1 && sum(picked) === 1 && state.bank[color] >= 4;
    return picked.filter(Boolean).length < engine().takeLimit(state);
  }

  function walletCanReturn(hand, color, picked) {
    return Number.isInteger(color) && color >= 0 && color < 6 && picked[color] < hand[color] && sum(picked) < sum(hand) - 10;
  }

  // The provisional contact is the same physical layer a completed tap would select.
  function contactCoin(piece) {
