    }
    return null;
  }

  function selectFromBank(state, color) {
    if (color === null) { drawSelection(); return; }
    if (!state.bank[color]) {
      if (bankDraft) bankDraft.message = "这堆已取空";
      reject(document.querySelector("#bank .pile-" + color));
      drawSelection();
      return;
    }
    if (!bankDraft || bankDraft.state !== state) {
