    }
    table().feel?.("select");
    drawSelection();
  }

  function releasePile(color) {
    color = Number(color);
    if (!bankDraft || view || bankDraft.state !== table().state || !Number.isInteger(color) ||
        color < 0 || color >= 5 || !bankDraft.tokens[color]) return false;
    bankDraft.tokens[color] = 0;
    bankDraft.message = "";
    bankDraft.lastColor = bankDraft.tokens.findIndex(Boolean);
    if (bankDraft.lastColor < 0) bankDraft = null;
    table().feel?.("cancel");
    drawSelection();
    return true;
  }

  function marketHas(state, id) {
    return !!engine().location(state,id);
  }

  function reject(node) {
    if (node) globalThis.BoardMotion?.reject?.(node);
  }

  function handButton(player) {
    return document.querySelector(`#seat-${player} .holdings-button`);
  }

  function chooseCard(draft) {
    bankDraft = null;
    cardDraft = draft;
    table().feel?.("paper");
    drawSelection();
  }

  function purchaseDraft(state, id, payment, held = false) {
    const cost = payment.sacrifice;
    const sacrifice = cost ? (cost.options.length === 2 ? cost.options.slice() : cost.required.slice()) : [];
    return {state, type:"buy", id, held, due:payment, pay:[...payment.colored,payment.gold],
      virtual:payment.virtual.slice(), sacrifice, swaps:[]};
  }

  function selectMarketCard(id) {
    const state = table().state;
    if (view || !engine().canSelectBuy(state,id) || !marketHas(state,id)) return;
    if (!engine().canAccess(state,id)) { reject(document.querySelector(`.market-card[data-value="${id}"]`)); return; }
    if (cardDraft?.id === id) { clearSelection(true); return; }
    const payment = engine().payment(state, id);
    const fromSlot = !!cardDraft?.fromSlot;
    if (payment.canBuy && !fromSlot) chooseCard(purchaseDraft(state, id, payment));
    else reserveCard(id);
  }

  function reserveCard(id) {
    if (table().friendWaiting) return;
    const state = table().state;
    if (table().computerTurn || view || state.phase !== "action" || !marketHas(state,id) || !engine().canAccess(state,id)) return;
    if (ReserveHand.owner !== null) ReserveHand.close();
    if (cardDraft?.type === "reserve" && cardDraft.id === id) { clearSelection(true); return; }
    if (state.players[state.active].reserved.length >= 3) {
      reject(document.querySelector(`.market-card[data-value="${id}"]`));
      return;
    }
    chooseCard({ state, type: "reserve", id, fromSlot: !!cardDraft?.fromSlot });
  }

  function selectDeck(tier,pile = "base") {
    const state = table().state;
    if (view || state.phase !== "action" || ![1, 2, 3].includes(tier)) return;
    if (cardDraft?.tier === tier && cardDraft.pile === pile) { clearSelection(true); return; }
    if (state.players[state.active].reserved.length >= 3 || !engine().boardFor(state,pile)?.decks[tier-1].length) {
      reject(document.querySelector(`#surface .deck[data-pile="${pile}"][data-value="${tier}"]`));
      return;
    }
    chooseCard({state,type:"reserve",tier,pile,fromSlot:!!cardDraft?.fromSlot});
  }

  function beginReservation() {
    const state = table().state;
    if (state.phase !== "action" || state.players[state.active].reserved.length >= 3) return;
    if (cardDraft?.fromSlot && !cardDraft.id && !cardDraft.tier) { clearSelection(true); return; }
    if (view) clearView();
    chooseCard({ state, type: "reserve", fromSlot: true });
  }

  function selectHeldCard(id, node) {
    const state = table().state;
    if (ReserveHand.owner !== state.active || view ||
        state.phase !== "action" || !state.players[state.active].reserved.includes(id)) return;
    if (cardDraft?.held && cardDraft.id === id) { cardDraft = null; drawSelection(); return; }
    const payment = engine().payment(state, id);
    if (!payment.canBuy) { reject(node); return; }
    chooseCard(purchaseDraft(state, id, payment, true));
  }

  function setExpansionTender(gold, virtual) {
    const d=cardDraft, s=table().state;
    if (d?.type!=="buy" || d.state!==s || !Array.isArray(virtual)) return false;
    const choices=engine().tender(s,d.id,d.pay.slice(0,5));
    if (!choices.some(m=>m.gold===gold && m.virtual.length===virtual.length)) return false;
    const owned=Orient.goldCards(s);
    if (new Set(virtual).size!==virtual.length || !virtual.every(id=>owned.includes(id))) return false;
    d.pay[5]=gold; d.virtual=virtual.slice();
    drawSelection();
    return true;
  }

  function setSacrifice(ids) {
    const d=cardDraft;
    if (!d?.due?.sacrifice || d.state!==table().state || !Array.isArray(ids) || ids.length>2 ||
        new Set(ids).size!==ids.length || !ids.every(id=>d.due.sacrifice.options.includes(id)) ||
        !d.due.sacrifice.required.every(id=>ids.includes(id))) return false;
    d.sacrifice=ids.slice();
    drawSelection();
    return true;
  }

  function changeSwaps(d, swaps) {
    const colored=d.due.colored.slice();
    for (const c of swaps) colored[c]--;
    const modes=engine().tender(d.state,d.id,colored);
    if (!modes.length) return false;
    const preferred=modes.find(m=>m.virtual.length===d.virtual.length) || modes[0];
    d.swaps=swaps; d.pay=colored.concat(preferred.gold); d.virtual=preferred.virtual.slice();
    table().feel("select"); drawSelection();
    return true;
  }

  function changeHeldPayment(color) {
    if (!cardDraft?.held || ReserveHand.owner!==table().state.active) return false;
    if (cardDraft.pay[color]>0 && changeSwaps(cardDraft,cardDraft.swaps.concat(color))) return true;
    if (cardDraft.swaps.includes(color)) return changeSwaps(cardDraft,cardDraft.swaps.filter(i=>i!==color));
    return false;
  }

  function payWithWallet(color) {
    if (table().friendWaiting) return false;
    const state=table().state;
    if (table().computerTurn) return false;
    color=Number(color);
    if (!view && state.phase === "discard") {
      const hand = state.players[state.active].tokens;
      const picked = returnDraft?.tokens || emptyTokens();
      if (walletCanReturn(hand, color, picked)) {
        picked[color]++;
        returnDraft = { state, tokens: picked, lastColor: color };
        table().feel?.("select");
        drawSelection();
      } else reject(document.querySelector('#seat-'+state.active+' .wallet-well[data-token-color="'+color+'"]'));
      return true;
    }
    if (view || cardDraft?.type!=="buy" || cardDraft.state!==state || !engine().canSelectBuy(state,cardDraft.id)) return false;
    if (color===5 && cardDraft.swaps.length && changeSwaps(cardDraft,cardDraft.swaps.slice(0,-1))) return true;
    if (color>=0 && color<5 && cardDraft.pay[color]>0 && changeSwaps(cardDraft,cardDraft.swaps.concat(color))) return true;
    reject(document.querySelector('#seat-'+state.active+' .wallet-well[data-token-color="'+color+'"]'));
    return true;
  }

  function releaseWallet(color) {
    color = Number(color);
    if (!returnDraft || view || returnDraft.state !== table().state || table().state.phase !== "discard" ||
        !Number.isInteger(color) || color < 0 || color >= 6 || !returnDraft.tokens[color]) return false;
    returnDraft.tokens[color] = 0;
    returnDraft.lastColor = returnDraft.tokens.findIndex(Boolean);
    if (returnDraft.lastColor < 0) returnDraft = null;
    table().feel?.("cancel");
    drawSelection();
    return true;
  }

  function canReturn(state, draft) {
    if (state.phase !== "discard" || draft?.state !== state) return false;
    const hand = state.players[state.active].tokens;
    const excess = sum(hand) - 10;
    return excess > 0 && sum(draft.tokens) === excess && draft.tokens.every((count, color) => count <= hand[color]);
  }

  function visitorTile(id) {
    return document.querySelector(`#surface .noble-tile[data-value="${id}"]`);
  }

  function selectVisitor(id) {
    const state = table().state;
    if (view || state.phase !== "noble") return;
    if (!engine().eligible(state).includes(id)) { reject(visitorTile(id)); return; }
    if (visitorDraft?.id === id) { clearSelection(true); return; }
    visitorDraft = { state, id };
    drawSelection();
  }

  function reservable(draft) {
    if (!draft || draft.type !== "reserve" || draft.state.players[draft.state.active].reserved.length >= 3) return false;
    return draft.id ? marketHas(draft.state,draft.id) && engine().canAccess(draft.state,draft.id) :
      !!(draft.tier && engine().boardFor(draft.state,draft.pile)?.decks[draft.tier-1].length);
  }

  function selectionOrigin() {
    if (visitorDraft) return visitorTile(visitorDraft.id);
    if (returnDraft) return document.querySelector(`#seat-${returnDraft.state.active} .wallet-well[data-token-color="${returnDraft.lastColor}"]`);
    if (bankDraft) return document.querySelector(`#bank .bank-pile[data-value="${bankDraft.lastColor ?? 0}"]`);
    if (!cardDraft) return null;
    if (cardDraft.held || (!cardDraft.id && !cardDraft.tier)) return handButton(cardDraft.state.active);
    if (cardDraft.tier) return document.querySelector(`#surface .deck[data-pile="${cardDraft.pile}"][data-value="${cardDraft.tier}"]`);
    return document.querySelector(`#surface .market-card[data-value="${cardDraft.id}"]`);
  }

  function clearSelection(restore = false) {
    if (!hasSelection() && ReserveHand.owner === null) return;
    const origin = restore ? selectionOrigin() || (ReserveHand.owner !== null ? handButton(ReserveHand.owner) : null) : null;
    if (ReserveHand.owner !== null) ReserveHand.close();
    const handlingCoins = !!(bankDraft || returnDraft);
    bankDraft = null;
    cardDraft = null;
    returnDraft = null;
    visitorDraft = null;
    drawSelection();
    if (restore) {
      if (handlingCoins) table().feel?.("cancel");
      origin?.focus({ preventScroll: true });
    }
  }

  let markedCardPiece = null;
  let markedKind = "";
  let markedVisitors = [];
  let walletProjection = "take";

  function aria(node, name, value) {
    if (value === null) {
      if (node.hasAttribute(name)) node.removeAttribute(name);
    } else if (node.getAttribute(name) !== String(value)) node.setAttribute(name, String(value));
  }

  function markCardPiece(node, kind) {
    node.classList.toggle("is-choosing-reserve", kind === "slot");
    node.classList.toggle("is-chosen", !!kind && kind !== "slot");
    node.classList.toggle("for-reserve", kind === "reserve");
    if (node.matches(".market-card, .deck")) aria(node, "aria-pressed", !!kind);
  }

  function drawCardSelection(state) {
    let piece = null;
    let kind = "";
    if (cardDraft) {
      if (cardDraft.held) {
        const slot = state.players[state.active].reserved.indexOf(cardDraft.id);
        piece = handButton(state.active)?.querySelectorAll(".reserve-fan i.held")[slot] || null;
        kind = "held";
      } else {
        piece = selectionOrigin();
        kind = cardDraft.fromSlot && !cardDraft.id && !cardDraft.tier ? "slot" : cardDraft.type;
      }
    }
    if (piece === markedCardPiece && kind === markedKind) return;
    if (markedCardPiece?.isConnected && markedCardPiece !== piece) markCardPiece(markedCardPiece, "");
    if (piece) markCardPiece(piece, kind);
    markedCardPiece = piece;
    markedKind = kind;
  }

  function drawVisitorSelection(state) {
    if (state.phase !== "noble") {
      for (const tile of markedVisitors) {
        if (!tile.isConnected) continue;
        tile.classList.toggle("eligible-visitor", false);
        tile.classList.toggle("is-invited", false);
        aria(tile, "aria-pressed", null);
      }
      if (markedVisitors.length) markedVisitors = [];
      return [];
    }
    const visitors = engine().eligible(state);
    markedVisitors = Array.from(document.querySelectorAll("#patrons .noble-tile"));
    for (const tile of markedVisitors) {
      const eligible = visitors.includes(tile.dataset.value);
      const invited = eligible && visitorDraft?.id === tile.dataset.value;
      tile.classList.toggle("eligible-visitor", eligible);
      tile.classList.toggle("is-invited", invited);
      aria(tile, "aria-pressed", invited);
    }
    return visitors;
  }

  function drawSelection() {
    const state = table().state;
    const picked = bankDraft?.tokens || emptyCounts;
    const board = table();
    board.previewBank(bankDraft ? picked : null);
    const projection = state.phase === "discard" ? "return" : cardDraft?.type === "buy" ? "pay" : "take";
    if (projection === "return") board.previewReturn(returnDraft?.tokens || null);
    else if (projection === "pay") board.previewPay(cardDraft.pay, cardDraft.id);
    else if (!bankDraft && walletProjection === "pay") board.previewPay(null);
    else if (!bankDraft && walletProjection === "return") board.previewReturn(null);
    else board.previewTake(bankDraft?.tokens || null);
    walletProjection = projection;
    ExUI.render(state);
    ExUI.payment(cardDraft?.type === "buy" ? cardDraft : null,state);
    watchTransient();
    drawCardSelection(state);
    ReserveHand.mark(cardDraft?.held ? cardDraft.id : null, cardDraft?.swaps);
    const visitors = drawVisitorSelection(state);
    TableAdvice.draw(bankDraft,cardDraft,returnDraft,visitorDraft,!!view);

    const confirm = document.getElementById("turn-action");
    if (!confirm) return;
    if (board.passingTurn) {
      confirm.disabled = true;
      return;
    }
    const mode = (ReserveHand.owner !== null ? "buy" : null) || phaseButton[state.phase] || cardDraft?.type || (state.phase === "effect" ? "effect" : null) ||
      (!bankDraft && !board.friendWaiting && engine().canPass(state) ? "pass" : "take");
    const caption = confirm.querySelector(".action-caption");
    const thinking = board.computerTurn && !computerDraft;
    const excess = Math.max(0, sum(state.players[state.active].tokens) + sum(picked) - 10);
    const word = board.friendWaiting ? (Lan.waiting ? "同步" : "等候") : thinking ? "思考" : mode === "effect" ? "选择" : mode === "discard" ? `归还\n${excess} 枚` : buttonCaption[mode];
    if (caption && caption.textContent !== word) caption.textContent = word;
    if (confirm.dataset.bankAction !== mode) confirm.dataset.bankAction = mode;
    const disabled = board.computerTurn || board.friendWaiting || mode === "effect" || (mode === "buy" && (cardDraft?.type !== "buy" || (cardDraft.due.sacrifice &&
      !Orient.validateSacrifice(state,cardDraft.id,cardDraft.sacrifice,state.active,engine())))) || (mode === "take" && !engine().canTake(state, picked)) ||
      (mode === "reserve" && !reservable(cardDraft)) || (mode === "discard" && !canReturn(state, returnDraft)) ||
      (mode === "noble" && !visitors.includes(visitorDraft?.id));
    if (confirm.disabled !== disabled) confirm.disabled = disabled;
    const chosen = picked.map((n, i) => n ? `${gemNames[i]}${n}枚` : "").filter(Boolean).join("、");
    const actionLabels = {
      take: `确认拿取${chosen || "宝石"}`, buy: cardDraft?.held ? "购买选中的预留卡" : "购买选中的发展卡",
      reserve: cardDraft?.tier ? `盲抽预留${tierNames[cardDraft.tier]}级卡` : "预留选中的发展卡",
      discard: `需归还${excess}枚筹码，已选${sum(returnDraft?.tokens || [])}枚`,
      noble: visitorDraft ? `迎接${engine().nobles[visitorDraft.id].name}` : "迎接贵族",
      pass: "无可用行动，跳过回合", result: "查看对局结果"
    };
    aria(confirm, "aria-label", board.friendWaiting ? (Lan.waiting ? "等待牌局同步" : "等待好友行动") :
      thinking ? "电脑正在思考" : actionLabels[mode] || "请在桌面完成扩展选择");
    let message = bankDraft?.message || (chosen ? `已选${chosen}${excess ? `，需归还${excess}枚` : ""}` : "");
    if (cardDraft) {
      if (cardDraft.fromSlot && !cardDraft.id && !cardDraft.tier) message = "请选择要预留的市场卡或牌堆。";
      else if (cardDraft.type === "reserve" && confirm.disabled) message = "预留区已满。";
      else message = actionLabels[mode];
    }
    if (mode === "discard") message = `需归还${excess}枚，已选${sum(returnDraft?.tokens || [])}枚。`;
    if (mode === "noble" && visitorDraft) message = actionLabels.noble;
    const status = document.getElementById("selection-status");
    if (status && status.textContent !== message) status.textContent = message;
  }

  function confirmSelection() {
    const state = table().state;
    if (view || table().computerTurn || table().friendWaiting || state.phase === "over" || changingState) return;
    const bank = bankDraft;
    const choice = cardDraft;
    const giving = returnDraft;
    const visitor = visitorDraft;
    let action;
    if (state.phase === "noble" && visitor?.state === state && engine().eligible(state).includes(visitor.id)) {
      action = { type: "noble", id: visitor.id };
    } else if (canReturn(state, giving)) action = { type: "discard", tokens: giving.tokens.slice() };
    else if (state.phase !== "action" && !(choice?.type === "buy" && engine().canSelectBuy(state,choice.id))) return;
    else if (bank?.state === state && engine().canTake(state, bank.tokens)) action = { type: "take", tokens: bank.tokens.slice() };
    else if (choice?.state === state) {
      if (choice.type === "buy") action = {type:"buy",id:choice.id,pay:choice.pay.slice(),virtual:choice.virtual.slice(),sacrifice:choice.sacrifice.slice()};
      else if (reservable(choice)) action = choice.id ? {type:"reserve",id:choice.id} : {type:"reserve",tier:choice.tier,pile:choice.pile};
    }
    if (!action) return;
    const source = selectionOrigin();
    // The motion snapshot measures the lifted physical pieces before the board redraws.
    bankDraft = null;
    cardDraft = null;
    returnDraft = null;
    visitorDraft = null;
    try {
      table().dispatch(action);
    } catch {
      if (table().state === state) { bankDraft = bank; cardDraft = choice; returnDraft = giving; visitorDraft = visitor; }
      drawSelection();
      reject(source);
    }
  }

  // Lift the same physical pieces that a human would select. Dispatch captures
  // these poses before the next draw, so the flight continues from the lift.
  function previewComputer(action) {
    const state = table().state;
    if (!action && !computerDraft) return;
    bankDraft = cardDraft = returnDraft = visitorDraft = null;
    computerDraft = action ? {state} : null;
    if (action?.type === "take") bankDraft = {state, tokens:action.tokens};
    if (action?.type === "discard") returnDraft = {state, tokens:action.tokens};
    if (action?.type === "noble") visitorDraft = {state, id:action.id};
    if (action?.type === "reserve") cardDraft = {state, ...action, pile:"base"};
    if (action?.type === "buy") {
      cardDraft = purchaseDraft(state, action.id, engine().payment(state,action.id), state.players[state.active].reserved.includes(action.id));
      if (action.pay) cardDraft.pay = action.pay;
    }
    drawSelection();
  }

  function showAdvice(state,action) {
    TableAdvice.set(state,action);
    TableAdvice.draw(bankDraft,cardDraft,returnDraft,visitorDraft,!!view);
  }

  function playerCards(ids, owner) {
    const board = table();
    const cards = ids.map(id => {
      if (ReserveHand.isFaceDown(owner, id)) {
        const {tier,pile} = Lan.back(id);
        const label = (pile === "orient" ? "东方" : "基础") + tierNames[tier] + "级盲预留牌，牌背";
        return `<div class="dlg-owned-card" role="img" aria-label="${label}">${board.pocketPaper(tier, pile).outerHTML}</div>`;
      }
      return `<div class="dlg-owned-card" role="img" aria-label="${escape(board.cardDescription(id))}">${board.cardStock(id)}</div>`;
    });
    return `<div class="dlg-owned-grid${board.state.orient ? " with-orient" : ""}">${cards.join("")}</div>`;
  }

  function noblesList(ids) {
    return `<div class="dlg-noble-list">${ids.map(id => {
      const noble = engine().nobles[id];
      return `<button type="button" class="dlg-noble-choice" data-dlg="inspect-noble" data-value="${escape(id)}">
        <img src="${escape(table().portraitURL(id))}" alt=""><span class="dlg-noble-choice-info"><strong>${escape(noble.name)}</strong><span class="dlg-mini-prices">${costs(noble.need)}</span></span>
        <span class="dlg-choice-icon">${icon("arrow")}</span></button>`;
    }).join("")}</div>`;
  }

  function playerContent() {
    const { state, draft } = view;
    const player = Number(view.arg);
    const hand = state.players[player];
    const score = engine().score(state, player);
    const bonuses = engine().bonuses(state, player);
    const tabs = [["assets", "资产", hand.cards.length], ["reserved", "预留", hand.reserved.length]];
    if (!state.cities) tabs.push(["nobles", "贵族", hand.nobles.length]);
    let body = `<div class="dlg-account-head"><img class="dlg-account-seal" alt="" src="${escape(table().sealURL(player))}"><div class="dlg-player-totals"><div><span>${icon("crown")}声望</span><b>${score}${state.cities ? "" : "<small> / 15</small>"}</b></div><div><span>${icon("token")}筹码</span><b>${sum(hand.tokens)}<small> / 10</small></b></div><div><span>${icon("cards")}发展卡</span><b>${hand.cards.length}<small> 张</small></b></div></div></div>
      <div class="dlg-tabs" aria-label="资产类别">${tabs.map(([value, label, n]) => `<button type="button" data-dlg="player-tab" data-value="${value}" aria-pressed="${draft.tab === value}" class="${draft.tab === value ? "is-picked" : ""}">${label}<small>${n}</small></button>`).join("")}</div>`;
    if (draft.tab === "reserved") {
      body += hand.reserved.length ? playerCards(hand.reserved, player) : note("尚无预留牌。");
    } else if (draft.tab === "assets" || state.cities) {
      body += labeledRow("手中筹码", costs(hand.tokens, "尚无筹码")) + labeledRow("永久折扣", costs(bonuses, "尚无折扣"));
      if (state.orient) {
        const counts = engine().cardCounts(state, player);
        const colors = counts.map((n, i) => n ? `<span class="dlg-price" title="${gemNames[i]}发展卡 ${n} 张" aria-label="${gemNames[i]}发展卡${n}张">${gem(i)}<b>${n}</b></span>` : "").join("");
        body += labeledRow("各色实体牌数", colors || '<span class="dlg-free">尚无有色牌</span>');
        body += labeledRow("东方金券", Orient.goldCards(state, player).length + " 张");
      }
      if (state.posts) {
        const stations = state.posts[player].map(id => `<span class="dlg-asset-station" title="${escape(SilkRoad.posts[id].power)}">${escape(SilkRoad.posts[id].name)}</span>`).join("");
        body += labeledRow("已设贸易站", stations || "尚未设站");
      }
      if (state.cities) {
        const reached = SilkRoad.eligibleCities(state, player, engine()).map(id => escape(SilkRoad.cities[id].name));
        body += labeledRow("达成城市", reached.length ? reached.join("、") : "尚未达成");
      }
      if (state.strongholds) {
        const stock = state.strongholds[player].filter(id => id === null).length;
        body += labeledRow("要塞", `库存 ${stock} 枚 · 牌上 ${3 - stock} 枚`);
      }
      if (hand.cards.length) body += `<h3 class="dlg-subtitle">${state.orient ? "持有的发展卡" : "已购发展卡"}</h3>${playerCards(hand.cards, player)}`;
    } else {
      body += hand.nobles.length ? noblesList(hand.nobles) : note("尚无贵族来访。");
    }
    return { title: playerName(player), symbol: "cards", body, foot: button("close", "返回棋盘") };
  }

  function nobleContent() {
    const { state, arg: id } = view;
    const noble = engine().nobles[id];
    const owner = state.players.findIndex(p => p.nobles.includes(id));
    const player = owner >= 0 ? owner : state.active;
    const counts = engine().cardCounts(state, player);
    const req = noble.need.map((n, i) => {
      if (!n) return "";
      const marks = Array.from({length:n}, (_, step) => `<i${step < counts[i] ? ' class="filled"' : ""}></i>`).join("");
      return `<div class="dlg-need ${counts[i] >= n ? "met" : ""}"><span>${gem(i)}${gemNames[i]}发展卡</span><span class="dlg-need-marks" aria-hidden="true">${marks}</span><strong>${counts[i]} / ${n} ${counts[i] >= n ? icon("check") : ""}</strong></div>`;
    }).join("");
    const body = `<div class="dlg-noble-intro"><span class="dlg-portrait"><img alt="" src="${escape(table().portraitURL(id))}"></span><div><span class="dlg-reward">${icon("crown")}+${noble.points} 声望</span><h3>${escape(noble.name)}</h3><p>${owner >= 0 ? `已拜访${escape(playerName(owner))}` : "凑齐所需颜色的发展卡，回合结束时即可迎接来访。"}</p></div></div>
      <h3 class="dlg-subtitle">${escape(playerName(player))}持有的发展卡</h3><div class="dlg-need-list">${req}</div>`;
    return { title: "贵族", symbol: "crown", body, foot: button(view.previous ? "back" : "close", view.previous ? "返回" : "返回棋盘") };
  }

  function rulesContent() {
    const state = view.state;
    const goal = state.cities ? "满足一座城市的声望和发展卡要求，进入最后一轮。" : "购买发展卡、吸引贵族来访，争取最高声望。";
    const detail = (title, text) => `<details class="dlg-rule"><summary>${title}</summary>${text}</details>`;
    const end = state.cities
      ? "回合结束时，只要有人满足任一城市的全部条件，就完成当轮。仅一人达城时，该玩家获胜。双方都达城时比较声望，同分时场上发展卡较少者胜，再同则并列。"
      : "每轮双方各行动一次。先手率先达到 15 点声望，后手还有最后一手。后手率先达到 15 点，结算完这个回合就结束。声望高者获胜。同分时场上发展卡较少者胜，仍相同则并列。";
    const objectives = [state.cities ? "城市" : "贵族", ...(state.posts ? ["贸易站"] : [])].join("和");
    const modules = [];
    if (state.cities) {
      modules.push(detail("城市", "<p>开局从七块双面城市牌中抽三块，各自随机翻出一面。城市要求的数字是最低声望和各色发展卡张数。</p><p>无色的牌数图标要求凑齐同一种颜色，这个颜色须与该城市已列的颜色不同。双方都可以达成同一座城市。点桌上的城市牌可查看自己的进度。</p>"));
    }
    if (state.posts) {
      const powers = Object.values(SilkRoad.posts).map(post => {
        const need = post.need.map((n, i) => n ? gemNames[i] + "牌" + n + "张" : "").filter(Boolean).join("、");
        return `<li><b>${escape(post.name)}</b>（${need}）　${escape(post.power)}</li>`;
      }).join("");
      modules.push(detail("贸易站", `<p>每种贸易站各有两块。回合结束时，有符合条件的新站就领取一块，同时符合多种可自选一种。每人每种限一块，能力持续到终局。${state.cities ? "先领取贸易站，再检查城市目标。" : "先结算贵族来访，再领取贸易站。"}</p><ul>${powers}</ul>`));
    }
    if (state.orient) {
      modules.push(detail("东方", `<p>每级另开两张东方牌。基础牌和东方牌各用自己的牌堆补位，也都可以预留。</p>
        <ul><li><b>金券</b>　购牌时可弃置，每张抵两枚万能黄金。两枚可以用于相同或不同颜色，剩余价值在本次购买后失效。</li>
        <li><b>配对锦囊</b>　须先有一张提供加成的牌。取得锦囊时选定一张已有牌，永久复制它的颜色及折扣份数。</li>
        <li><b>双折扣</b>　购牌时抵两枚同色筹码。计算${objectives}的要求时，每张有色发展卡只计一张，已配对的锦囊按选定颜色计数。</li>
        <li><b>免费取牌</b>　二级锦囊配对后免费取得一张一级明牌。带取牌图标的三级牌可免费取得一张二级明牌。先处理所得牌的效果，再从原牌堆补牌。</li>
        <li><b>交牌购买</b>　带交牌图标的三级牌需交出两张指定颜色的发展卡，已配为该色的锦囊优先。交出的牌移出游戏。</li></ul>`));
    }
    if (state.strongholds) {
      const timing = "征服结算完毕，再检查十枚筹码上限和" + (state.cities ? "城市目标。" : "贵族来访。");
      modules.push(detail("要塞", StrongholdsUI.rules.map((text, i, rows) =>
        `<p>${text}${i === rows.length - 1 ? timing : ""}</p>`).join("")));
    }
    const combined = [];
    if (state.posts && state.orient) combined.push("贸易站的择牌预留也适用于东方牌堆。黄金倍值同样适用于金券产生的每枚虚拟黄金。东方效果免费取得的牌不会再次触发购牌取宝，交出发展卡后也保留已领取的贸易站。");
    if (state.strongholds && state.orient) combined.push("要塞可占领东方牌。免费取牌时也须避开对方占领的牌，取走己方占领的牌就收回要塞。一次东方购牌只触发一次要塞行动。");
    if (state.posts && state.strongholds) combined.push("征服购买也会触发购牌取宝。常规购买后从贸易站拿到的筹码可以支付同回合的征服。");
    if (combined.length) modules.push(detail("扩展联动", combined.map(text => `<p>${text}</p>`).join("")));
    const body = `<div class="dlg-rules-intro"><span class="dlg-goal-mark">${icon("crown")}<b>${state.cities ? "城" : "15"}</b></span><div><strong>${state.cities ? "城市目标" : "声望目标"}</strong><p>${goal}</p></div></div>
      <details class="dlg-rule" open><summary>每回合选择一个行动</summary><ul>
        <li><b>拿取宝石</b>　拿三种不同颜色各一枚。如果剩余颜色不足三种，每种各拿一枚。也可以从至少有四枚的一色中拿两枚。${state.balancedOpening ? "本局启用了先手平衡，先手首回合拿异色时，有两种就拿满两枚，只剩一种才拿一枚。" : ""}</li>
        <li><b>购买发展卡</b>　从市场或自己的预留区购牌。先减去已有永久折扣，再支付筹码。黄金可以代替任意颜色。</li>
        <li><b>预留一张牌</b>　选择一张市场明牌，或盲抽任一牌堆的顶牌。盲抽牌只有自己可查看。同时领取一枚黄金。黄金用尽时仍可预留。每人最多预留三张。</li>
      </ul></details>
      <details class="dlg-rule"><summary>${state.cities ? "筹码与永久折扣" : "筹码、折扣与贵族"}</summary><p>双人局每色有四枚筹码，另有五枚黄金。回合结束时手里最多留十枚筹码，黄金也计入上限。用过的筹码放回银行。</p>
      <p>每张基础发展卡提供一份对应颜色的永久折扣。${state.cities ? "购买其他牌时可继续使用折扣。" : "回合结束时，若各色发展卡张数满足贵族要求，该贵族会来访并带来三点声望。每回合最多接待一位，发展卡可继续使用。"}</p></details>
      <details class="dlg-rule"><summary>准备与胜负</summary><p>基础牌三个等级各翻开四张，另摆出${state.cities ? "三座城市" : "三位随机贵族"}。移走市场明牌后，完成相关即时效果，从原牌堆补位。牌堆见底时留空。</p>
      <p>${end}</p></details>
      ${modules.join("")}
      <details class="dlg-rule"><summary>同屏操作</summary>
      <p>点宝石堆预备一枚。该堆至少有四枚且只选了这一色时，再点可取两枚。长按一堆只撤回该色，点桌面空白处取消整笔选择。选好按手边的「拿取」。</p>
      <p>选择市场卡后，买得起会显示「购买」，暂买不起会显示「预留」。再点同一张牌可取消。</p>
      <p>想预留买得起的卡，可以长按它（键盘可按 R），或先点自己的空预留槽再选卡。点牌堆可以盲抽预留。每次都按手边按钮确认。</p>
      <p>选购时，点自己钱包里要支付的彩色筹码，可用一枚黄金代替。点钱包中的黄金可撤回最近一次替换。</p>
      <p>点预留牌袋，最多三张牌会在桌面中央展开。自己的回合可点金边牌，再按「购买」。需调整黄金时，点已选牌上的费用标记。点其他地方可收起并取消选择。</p><p>超过十枚时，点自己钱包里的筹码逐枚选还，长按可撤回该色，选足后按「归还」。</p></details>
      <p class="dlg-credits">原作 Splendor · 设计 Marc André · 出版 SPACE Cowboys。本地版插画重新绘制。原创配乐《晚潮归港》使用 S. Christian Collins 的 GeneralUser GS 音色录制。</p>`;
    return { title: "游戏规则", symbol: "book", body, foot: button("close", "返回棋盘") };
  }

  function firstSelector(draft, label) {
    return `<fieldset class="dlg-fieldset"><legend>${label}</legend><div class="dlg-first-options">${[0, 1].map(i =>
      `<label><input type="radio" name="dlg-first" value="${i}" ${draft.nextFirst === i ? "checked" : ""}><span ${i ? 'data-second-name="' + escape(draft.names[i]) + '"' : ''}>${escape(draft.names[i])}</span></label>`).join("")}</div></fieldset>`;
  }

  function settingsContent() {
    const { draft } = view;
    const seats = [0, 1].map(i => {
      const seat = i ? "二号席" : "一号席";
      const computer = table().mode === "solo" && i === 1;
      const name = computer ? playerName(1) : draft.names[i];
      const level = computer && GamePacks.difficultyChoice(draft.difficulty,"table-difficulty","solo");
      return `<div class="dlg-seat-sign" data-seat="${i}"><label class="dlg-seat-order"><input type="radio" name="dlg-first" value="${i}" ${draft.nextFirst === i ? "checked" : ""} aria-label="新局由${escape(name)}先手">
        <span class="dlg-order-seal"><img alt="" src="${escape(table().sealURL(i))}"><i class="on">先手</i><i class="off">后手</i></span></label>
        ${level || `<label class="dlg-name-field"><span>${seat}</span><input type="text" data-player-name="${i}" maxlength="12" autocomplete="off" value="${escape(name)}" aria-label="${seat}玩家名字" ${computer ? "readonly" : ""}></label>`}</div>`;
    }).join("");
    const lan = table().mode === "lan";
    const assist = table().mode === "solo" && RivalTurn.supportsHard ?
      `<label class="opening-choice assist-choice" title="由困难棋手推荐下一步"><input type="checkbox" aria-label="棋步辅助，由困难棋手推荐" data-solo-assist ${draft.assist ? "checked" : ""}><span>${icon("compass")}棋步辅助</span></label>` : "";
    const actions = lan ? button("lan-room","联机房间",{variant:"primary"}) :
      button("new-prompt","新开一局",{variant:"primary",symbol:"turn"}) + button("cover","返回封面");
    const body = `<div class="dlg-settings"><div class="dlg-settings-start">${actions}</div>
      ${lan ? "" : '<fieldset class="dlg-fieldset dlg-seats-page"><legend>新局先手 <small>本局先手 · '+escape(playerName(view.state.first))+'</small></legend>'+seats+assist+'</fieldset>'}
      <fieldset class="dlg-fieldset dlg-sound-page"><legend>声音与触感</legend><div class="dlg-sound-keys">
        <label class="dlg-instrument" title="《晚潮归港》"><b>背景音乐</b><input type="checkbox" data-table-music ${draft.music ? "checked" : ""}><i class="dlg-dial" aria-hidden="true"></i><span class="dlg-dial-state" aria-hidden="true"><i class="on">开</i><i class="off">关</i></span></label>
        <label class="dlg-instrument" title="筹码、翻牌与贵族来访"><b>桌面音效</b><input type="checkbox" data-table-sound ${draft.sound ? "checked" : ""}><i class="dlg-dial" aria-hidden="true"></i><span class="dlg-dial-state" aria-hidden="true"><i class="on">开</i><i class="off">关</i></span></label></div>
        <label class="dlg-music-level"><span>音乐音量</span><input type="range" min="0" max="100" step="1" value="${Math.round(draft.musicVolume * 100)}" data-music-level aria-label="背景音乐音量"><output>${Math.round(draft.musicVolume * 100)}%</output></label>
        <label class="opening-choice dlg-haptics"><input type="checkbox" data-table-haptics ${draft.haptics ? "checked" : ""}><span>操作振动</span></label>
      </fieldset>${lan ? "" : GamePacks.openingChoice(draft.balancedOpening,!table().openingEditable)}</div>`;
    const storage = lan || table().saved ? "" : note("当前浏览器只能在本次打开时保留进度。");
    return { title: "棋桌设置", symbol: "gear", body: body + storage, foot: button("close", "取消") + button("save-settings", "保存设置", { variant: "primary", symbol: "check" }) };
  }

  function readSettings() {
    const layer = getLayer();
    const balancedOpening = layer.querySelector("[data-balanced-opening]")?.checked;
    view.draft.balancedOpening = balancedOpening;
    const savedOpening = table().openingEditable ? table().state.balancedOpening === true : table().nextOpening();
    const names = [0, 1].map(i => {
      const input = layer.querySelector(`[data-player-name="${i}"]`);
      if (!input || input.readOnly) return table().options.names[i];
      return Array.from(input?.value.trim() || (i ? "玩家二" : "玩家一")).slice(0, 12).join("");
    });
    return {
      names,
      difficulty:GamePacks.readDifficulty(layer),
      assist:layer.querySelector("[data-solo-assist]")?.checked ?? view.draft.assist,
      ...(balancedOpening !== savedOpening ? {balancedOpening} : {}),
      sound: !!layer.querySelector("[data-table-sound]")?.checked,
      haptics: layer.querySelector("[data-table-haptics]").checked,
      music: !!layer.querySelector("[data-table-music]")?.checked,
      musicVolume: Number(layer.querySelector("[data-music-level]").value) / 100,
      nextFirst: Number(layer.querySelector("input[name=dlg-first]:checked")?.value ?? view.draft.nextFirst)
    };
  }

  function resetContent() {
    const { draft, state } = view;
    const message = state.phase === "over" ? "双方将从零声望重新开始。" : "新局会替换当前进度，双方将从零声望重新开始。";
    return { title: "新开一局？", symbol: "turn", body: note(message, "dlg-highlight") + GamePacks.modeChoice(draft.mode,"reset-mode") +
      GamePacks.difficultyChoice(draft.difficulty,"reset-difficulty",draft.mode) + firstSelector(draft, "先手玩家") +
      GamePacks.openingChoice(draft.balancedOpening) + GamePacks.choices(draft.packs),
      foot: button("back", "返回") + button("reset", "确认开局", { variant: "primary", symbol: "check" }) };
  }

  function resultContent() {
    const state = view.state;
    const tied = state.winner === "tie";
    const scores = [0, 1].map(i => engine().score(state, i));
    const gap = Math.abs(scores[0] - scores[1]);
    const cardGap = Math.abs(state.players[0].cards.length - state.players[1].cards.length);
    const reached = state.cities ? state.players.map((_, i) =>
      SilkRoad.eligibleCities(state, i, engine()).map(id => SilkRoad.cities[id].name)) : null;
    let verdict;
    if (reached && reached.filter(names => names.length).length === 1) {
      verdict = "仅" + playerName(state.winner) + "达成城市目标，赢得本局。";
    } else {
      const qualified = reached ? "双方均已达城。" : "";
      if (tied) verdict = qualified + "双方声望相同，场上的发展卡数量也相同。";
      else if (gap) verdict = qualified + "以 " + gap + " 点声望的优势胜出。";
      else verdict = qualified + "双方声望相同，胜方场上少 " + cardGap + " 张发展卡。";
    }
    const level = table().resultDifficulty;
    const mark = level ? `<small class="dlg-result-level" data-level="${level}"><span aria-hidden="true">·</span>${level === "hard" ? "困难" : "简单"}</small>` : "";
    const sides = state.players.map((p, i) => `<section class="dlg-result-side${state.winner === i ? " is-victor" : ""}" data-seat="${i}">
      <img class="dlg-wax" alt="" draggable="false" src="${escape(table().sealURL(i))}">
      <h4>${escape(playerName(i))}${i === 1 ? mark : ""}</h4><p class="dlg-result-score"><b>${scores[i]}</b><span>声望</span></p>
      <p class="dlg-result-assets">${p.cards.length} 张发展卡 <i>·</i> ${reached ? (reached[i].length ? "达成" + escape(reached[i].join("、")) : "尚未达城") : p.nobles.length + " 位贵族"}${state.posts ? " <i>·</i> " + state.posts[i].length + " 座贸易站" : ""}</p></section>`).join("");
    const body = `<div class="dlg-victory">${icon("laurel")}<div><h3>${tied ? "双方并列获胜" : `${escape(playerName(state.winner))}获胜`}</h3><p>${escape(verdict)}</p></div></div>
      <div class="dlg-result-pair">${sides}</div>`;
    const lan = table().mode === "lan";
    const replay = lan && Lan.seat === 1 ? button("lan-room","联机房间") : button("rematch","再来一局",{variant:"primary",symbol:"turn"});
    return { title: "终局结算", symbol: "crown", body, layout: "dlg-result-panel", foot: button("close", "查看棋盘") + (lan ? "" : button("new-prompt","调整设置")) + replay };
  }

  const contentFor = {
    player: playerContent, noble: nobleContent,
    rules: rulesContent, settings: settingsContent,
    resetConfirm: resetContent, result: resultContent
  };

  function draw(retain = false, focus = true) {
    if (!view) return;
    const layer = getLayer();
    if (!layer) return;
    const scroll = retain ? layer.querySelector(".dlg-body")?.scrollTop || 0 : 0;
    const focused = retain && layer.contains(document.activeElement) ? document.activeElement?.closest("[data-dlg]") : null;
    const keepAction = focused?.dataset.dlg;
    const keepValue = focused?.dataset.value;
    const data = contentFor[view.kind]();
    layer.classList.add("dlg-open");
    watchTransient();
    setBoardInert(true);
    const player = view.kind === "player" ? Number(view.arg) : view.kind === "result" ? view.state.winner : view.state.active;
    layer.innerHTML = `<div class="dlg-shade" data-dlg="close"></div><div class="dlg-frame">
      <section class="dlg-panel ${data.layout || ""}" data-folio="${view.kind}" data-player="${player}" role="dialog" aria-modal="true" aria-labelledby="dlg-heading" tabindex="-1">
        ${view.kind === "settings" ? '<span class="dlg-center-fold" aria-hidden="true"></span>' : ""}<span class="dlg-title-symbol" aria-hidden="true">${icon(data.symbol)}</span>
        <header class="dlg-header">${view.previous ? `<button type="button" class="dlg-icon-button dlg-back" data-dlg="back" aria-label="返回上一页">${icon("arrow")}</button>` : ""}
          <h2 id="dlg-heading">${escape(data.title)}</h2>${view.kind === "settings" ? '<button type="button" class="screen-toggle" data-fullscreen>进入全屏</button>' : ""}<button type="button" class="dlg-icon-button" data-dlg="close" aria-label="关闭">${icon("close")}</button></header>
        <div class="dlg-body">${view.kind === "settings" ? '<p class="screen-note" data-screen-note role="status"></p>' : ""}${data.body}</div>
        ${view.error ? `<div class="dlg-error" role="alert">${escape(view.error)}</div>` : ""}
        <footer class="dlg-foot">${data.foot || ""}</footer>
      </section></div>`;
    GamePacks.syncChoices(layer);
    if (view.kind === "resetConfirm") GamePacks.bindMatchForm(layer,view.draft.mode);
    const scroller = layer.querySelector(".dlg-body");
    if (scroller) scroller.scrollTop = scroll;
    if (view.kind === "settings") {
      BoardFullscreen.sync();
    }
    const matching = keepAction && Array.from(layer.querySelectorAll("[data-dlg]:not(:disabled)")).find(el => el.dataset.dlg === keepAction && el.dataset.value === keepValue);
    if (focus) (matching || layer.querySelector(".dlg-panel"))?.focus({ preventScroll: true });
  }

  function onPointerDown(event) {
    if (!event.isPrimary) {
      suppressClickUntil = performance.now() + 500;
      if (buttonPress) buttonPress.moved = true;
      return;
    }
    if (event.button !== 0) return;
    suppressClickUntil = 0;
    buttonPress = event.target.closest?.("#surface button") ?
      { id: event.pointerId, x: event.clientX, y: event.clientY, moved: false } : null;
  }

  function onPointerMove(event) {
    if (buttonPress?.id === event.pointerId && Math.hypot(event.clientX - buttonPress.x, event.clientY - buttonPress.y) > 10) {
      buttonPress.moved = true;
    }
  }

  function onPointerEnd(event) {
    if (buttonPress?.id !== event.pointerId) return;
    if (buttonPress.moved || Math.hypot(event.clientX - buttonPress.x, event.clientY - buttonPress.y) > 10) {
      suppressClickUntil = performance.now() + 500;
    }
    buttonPress = null;
  }

  function guardDraggedClick(event) {
    if (event.detail > 0 && performance.now() < suppressClickUntil) {
      event.preventDefault();
      event.stopImmediatePropagation();
      suppressClickUntil = 0;
    }
  }

  function onClick(event) {
    const bankButton = event.target.closest?.("#turn-action");
    if (bankButton && !bankButton.disabled) {
      if (bankButton.dataset.bankAction === "result") open("result");
      else if (bankButton.dataset.bankAction === "pass" && engine().canPass(table().state)) table().dispatch({type: "pass"});
      else confirmSelection();
      return;
    }
    const held = event.target.closest?.(".reserve-spread:not(.closing) [data-hand-card]");
    if (held) {
      const cost = event.target.closest("[data-cost-color]");
      if (cost && cardDraft?.id === held.dataset.handCard && changeHeldPayment(Number(cost.dataset.costColor))) return;
      selectHeldCard(held.dataset.handCard, held);
      return;
    }
    if (!view && (hasSelection() || ReserveHand.owner !== null) && event.target.closest?.("#surface") && !event.target.closest?.("button, #dialog-layer")) {
      clearSelection(true);
      return;
    }
    const target = event.target.closest?.("#dialog-layer [data-dlg]");
    if (!target || target.disabled || !view) return;
    event.stopPropagation();
    const action = target.dataset.dlg;
    const value = target.dataset.value;
    const n = Number(value);
    const { kind, state, arg, draft } = view;
    view.error = "";
    switch (action) {
      case "close": close(); break;
      case "back": back(); break;
      case "lan-room": clearView(false); Lan.open(); break;
      case "player-tab":
        draft.tab = value;
        draw(true);
        break;
      case "inspect-noble": navigate("noble", value); break;
      case "new-prompt": {
        const options = kind === "settings" ? readSettings() : undefined;
        if (options) Object.assign(draft, options);
        navigate("resetConfirm", null, options); break;
      }
      case "save-settings": {
        const options = readSettings();
        transact(() => table().configure(options)); break;
      }
      case "cover":
        clearView(false);
        opener = null;
        GameLobby.show();
        break;
      case "reset": {
        const first = Number(getLayer().querySelector("input[name=dlg-first]:checked")?.value ?? draft.nextFirst);
        const packs = GamePacks.readChoices(getLayer());
        const balancedOpening = getLayer().querySelector("[data-balanced-opening]").checked;
        const mode = GamePacks.readMode(getLayer());
        const difficulty = GamePacks.readDifficulty(getLayer());
        transact(() => table().newGame(first, packs, {mode, difficulty, assist:draft.assist, names:draft.names, sound:draft.sound, haptics:draft.haptics, music:draft.music, musicVolume:draft.musicVolume, nextFirst:first, balancedOpening}));
        break;
      }
      case "rematch":
        if (table().mode === "lan") {
          if (kind === "result" && state.phase === "over" && Lan.seat === 0) transact(()=>Lan.rematch());
          break;
        }
        if (kind === "result" && state.phase === "over")
          transact(() => table().newGame(1 - state.first, table().packs, {mode:table().mode, balancedOpening:table().nextOpening()}));
        break;
    }
  }

  function onKey(event) {
    if (event.isComposing) return;
    if (/^[1-5]$/.test(event.key) && ReserveHand.owner !== null && !event.repeat && changeHeldPayment(Number(event.key) - 1)) {
      event.preventDefault();
      return;
    }
    if (["Escape", "BrowserBack", "GoBack"].includes(event.key)) {
      if (!transientOpen()) return;
      // Under CloseWatcher the trusted Escape is already a platform close request.
      if (event.key === "Escape" && event.isTrusted && closeWatcher) return;
      if (!event.repeat && backOneLayer()) event.preventDefault();
      return;
    }
    if (!view) return;
    if (event.key !== "Tab") return;
    const layer = getLayer();
    const items = [...layer.querySelectorAll("button:not(:disabled), input:not(:disabled), summary, a[href]")].filter(el => el.getClientRects().length);
    if (!items.length) { event.preventDefault(); return; }
    const focus = document.activeElement;
    if (event.shiftKey && (focus === items[0] || !items.includes(focus))) { event.preventDefault(); items[items.length - 1].focus(); }
    if (!event.shiftKey && (focus === items[items.length - 1] || !items.includes(focus))) { event.preventDefault(); items[0].focus(); }
  }

  document.addEventListener("pointerdown", onPointerDown, true);
  document.addEventListener("pointermove", onPointerMove, { capture: true, passive: true });
  document.addEventListener("pointerup", onPointerEnd, true);
  document.addEventListener("pointercancel", onPointerEnd, true);
  document.addEventListener("click", guardDraggedClick, true);
  document.addEventListener("click", onClick);
  document.addEventListener("keydown", onKey);
  document.addEventListener("input", event => {
    const field = event.target;
    if (view?.kind === "settings" && field.matches("[data-table-haptics]")) {
      view.draft.haptics = field.checked;
      if (field.checked) BoardFeedback.play("select", false, null, true);
      return;
    }
    if (view?.kind === "settings" && field.matches?.("[data-table-music], [data-music-level], [data-table-sound]")) {
      const layer = getLayer();
      view.draft.music = layer.querySelector("[data-table-music]").checked;
      view.draft.musicVolume = Number(layer.querySelector("[data-music-level]").value) / 100;
      view.draft.sound = layer.querySelector("[data-table-sound]").checked;
      layer.querySelector(".dlg-music-level output").textContent = Math.round(view.draft.musicVolume * 100) + "%";
      BoardMusic.configure(view.draft.music, view.draft.musicVolume);
      if (field.matches("[data-table-sound]") && field.checked) BoardFeedback.play("select", true, null, false);
      return;
    }
    if (view?.kind !== "settings" || !field.matches?.("#dialog-layer [data-player-name]")) return;
    const idx = Number(field.dataset.playerName);
    const order = getLayer().querySelector(`input[name=dlg-first][value="${idx}"]`);
    if (order) order.setAttribute("aria-label", (field.value.trim() || (idx ? "玩家二" : "玩家一")) + "先手");
  });
  function showRivalError(message) {
    if (!table().computerTurn) return;
    open("settings");
    if (view?.kind === "settings") {
      view.error = message;
      draw(true);
    }
  }
  globalThis.Controls = Object.freeze({ open, sync, close, reserveCard, payWithWallet, releasePile, releaseWallet, contactCoin, setExpansionTender, setSacrifice, previewComputer, showRivalError, showAdvice, clearAdvice:TableAdvice.clear, get folioOpen(){return !!view;}, get modalOpen() {return !!view || ReserveHand.owner !== null;} });
})();

/* Offline card markings and choice labels for the 2025 Orient deck. */
(function (root) {
  "use strict";

  const names = ["钻石", "蓝宝石", "祖母绿", "红宝石", "缟玛瑙"];
  const colors = ["#f1e8d0", "#68aaca", "#73a58b", "#d98268", "#453d3a"];
  const labels = {gold: "双金", pair: "配对袋", double: "双加成", "pair-free": "配对并取一级牌",
    free: "取二级牌", sacrifice: "交出两牌"};

  function pairingText(paired) {
