    const rank = level === 1 ? "M10 7v8" : "M8 7v8m4-8v8";
    return '<g transform="translate(' + x + ',2)"><rect x="2" y="2" width="15" height="18" rx="2" fill="#827061" stroke="#dbc49a"/>' +
      '<rect x="5" y="1" width="15" height="18" rx="2" fill="#ded0af" stroke="#f9e6b9"/>' +
      '<path d="' + rank + '" transform="translate(2)" fill="none" stroke="#433b3b" stroke-width="1.5"/>' +
