    switch (card.effect) {
      case "gold":
        body = '<g stroke="#f1ce71" stroke-width="1.3"><circle cx="15" cy="12" r="8" fill="#a66d2e"/>' +
          '<circle cx="28" cy="14" r="8" fill="#c68e40"/><circle cx="28" cy="14" r="5.6" fill="none"/>' +
          '<path d="m28 10 3 4-3 4-3-4Z" fill="#f4d583" stroke="none"/></g>';
