    rack = make("button", "keep-stock keep-seat-" + player);
    rack.type = "button";
    rack.disabled = true;
    for (let i = 0; i < 3; i++) rack.append(make("span", "keep-socket"));
    rack.addEventListener("click", () => {
      if (currentStep(table().state) === "stronghold" && table().state.active === player) setMode("place");
