      slot.node = empty;
      slot.id = null;
      if (focused) deck.focus({preventScroll: true});
      return;
    }
    const c = engine.cards[id];
    if (!slot.id) {
      const card = makeNode("button", "market-card");
      card.type = "button";
      card.dataset.open = "card";
      card.setAttribute("aria-keyshortcuts", "R");
      card.setAttribute("aria-pressed", "false");
      slot.node.replaceWith(card);
      slot.node = card;
    } else if (engine.cards[slot.id].bonus !== c.bonus) {
      slot.node.classList.remove("dye-" + engine.cards[slot.id].bonus);
    }
    slot.node.classList.toggle("dye-" + c.bonus, true);
    slot.node.dataset.value = id;
    slot.node.dataset.pile = engine.pileOf(id);
    slot.node.innerHTML = cardStock(id);
    slot.id = id;
    slot.label = cardDescription(id);
  }

  function drawMarket() {
    const host = byId("development-market");
    if (!rows.length || rows[0].group.parentNode !== host || host.dataset.orient !== String(!!state.orient)) mountMarket(host);
    if (!turnHandoff && state === pricedState) return;
    const hand = state.players[state.active];
    const full = hand.reserved.length >= 3;
    const classicPricing = !state.orient && !state.posts && !state.strongholds;
    const power = !turnHandoff && classicPricing ? [state.phase, full, ...hand.tokens, ...engine.bonuses(state)].join(",") : "";
    for (const row of rows) {
      const board = engine.boardFor(state,row.pile), remaining = board.decks[row.tier - 1].length;
      if (row.remaining !== remaining) {
        row.remaining = remaining;
        setText(row.count, remaining);
        row.deck.classList.toggle("deck-depleted", !remaining);
        setAttr(row.deck, "aria-label", `${row.pile==='orient'?'东方':'基础'}${row.tier}级牌堆，余${remaining}张，盲抽预留`);
      }
      row.slots.forEach((slot, index) => {
        const id = board.market[row.tier - 1][index];
        const changed = slot.id !== id;
        if (changed) changeMarketSlot(slot, id, row.deck);
        if (turnHandoff) {
          if (changed && id) {
            slot.node.classList.remove("affordable");
            setAttr(slot.node, "aria-label", slot.label);
          }
          return;
        }
        if (!id || (!changed && classicPricing && power === buyingPower)) return;
        const canBuy = engine.canSelectBuy(state,id) && engine.payment(state,id).canBuy;
        const action = !engine.canAccess(state,id) ? "，对方要塞占领" : canBuy ? "，点选购买" : state.phase!=="action" ? "" : full ? "，预留区已满" : "，点选预留";
        setAttr(slot.node, "aria-label", slot.label + action);
        slot.node.classList.toggle("affordable", canBuy);
      });
    }
    buyingPower = power;
    pricedState = turnHandoff ? null : state;
  }

  function patronTile(id) {
    const n = engine.nobles[id];
    const tile = makeNode("button", "noble-tile");
    tile.type = "button";
    tile.dataset.open = "noble";
    tile.dataset.value = id;
    tile.setAttribute("aria-label", `${n.name}，3声望，要求永久加成${tokenText(n.need)}`);
    tile.innerHTML = `<span class="noble-face"><span class="portrait-wrap"><img src="${portraitURL(id)}" alt="" draggable="false"><span class="noble-reward">${icon("crown")}<b>3</b></span></span>
      <span class="noble-paper"><span class="noble-name">${escape(patronLabels[n.art])}</span><span class="noble-needs">${prices(n.need)}</span></span></span>`;
    return tile;
  }

  function guestSeal(id) {
    const noble = engine.nobles[id];
    const button = makeNode("button", "guest-portrait");
    button.type = "button";
    button.dataset.open = "noble";
    button.dataset.value = id;
    button.setAttribute("aria-label", `查看已来访的${noble.name}，${noble.points}点声望`);
    button.title = noble.name;
    const stamp = picture(portraitURL(id), "guest-seal");
    button.appendChild(stamp);
    return button;
  }

  function pocketPaper(tier,pile="base") {
    const paper = makeNode("span", "pocket-paper tier-" + tier);
    paper.dataset.tier = String(tier);
    paper.dataset.pile = pile;
    paper.style.setProperty("--back", 'url("' + deckURL(tier,pile) + '")');
    paper.innerHTML = `<span class="pocket-art"></span><span class="pocket-rank">${roman[tier - 1]}</span><span class="pocket-lettering" lang="en">Splendor</span><span class="pocket-pips">${"<span></span>".repeat(tier)}</span>`;
    return paper;
  }

  // The public portraits and the small seals in each ledger follow the same ordered list of real nobles.
  function syncNobles(container, ids, create) {
    const focused = document.activeElement;
    const hadFocus = container.contains(focused);
    for (const node of Array.from(container.children)) {
      if (!ids.includes(node.dataset.nobleId)) node.remove();
    }
    ids.forEach((id, index) => {
      const current = container.children[index];
      if (current?.dataset.nobleId === id) return;
      const found = Array.from(container.children).find(node => node.dataset.nobleId === id);
      const item = found || create(id);
      if (!found) item.dataset.nobleId = id;
      container.insertBefore(item, current || null);
    });
    if (hadFocus && document.activeElement !== focused) {
      const target = focused.isConnected ? focused : container.querySelector("button") || byId("seat-" + state.active)?.querySelector(".name-button");
      target?.focus({preventScroll: true});
    }
  }

  function drawPatrons() {
    const host = byId("patrons");
    if (state.cities) {
      if (nobleTray?.parentNode === host) nobleTray.remove();
      nobleTray = null;
      publicNobles = null;
      return;
    }
    if (nobleTray?.parentNode !== host) {
      nobleTray = makeNode("div", "noble-tray");
      host.replaceChildren(nobleTray);
      publicNobles = null;
    }
    const key = state.nobles.join(",");
    if (key !== publicNobles) {
      const settle = nobleTray.childElementCount > state.nobles.length &&
        !matchMedia("(prefers-reduced-motion: reduce)").matches;
      const oldOrder = settle ? Array.from(nobleTray.children, tile => tile.dataset.nobleId) : null;
      syncNobles(nobleTray, state.nobles, patronTile);
      if (oldOrder) Array.from(nobleTray.children).forEach((tile, index) => {
        const oldIndex = oldOrder.indexOf(tile.dataset.nobleId);
        if (oldIndex === -1) return;
        // Centered, equal-width slots: one step is a tile plus its gap.
        // Keeping this in CSS units avoids forcing layout twice during the purchase.
        const steps = oldIndex - index + (state.nobles.length - oldOrder.length) / 2;
        if (steps) tile.animate?.([{transform:`translateX(calc(${steps * 100}% + ${steps} * var(--noble-gap)))`},
          {transform:"none"}], {duration:210, easing:"cubic-bezier(.22,.65,.32,1)"});
      });
      publicNobles = key;
    }
  }

  function setCoinLayers(ref, color, count, className, before = null) {
    while (ref.layers.length > count) ref.layers.pop().remove();
    if (ref.layers.length === count) return;
    const additions = [];
    while (ref.layers.length < count) {
      const level = ref.layers.length;
      const coin = picture(chipURL(color), className);
      coin.dataset.layer = String(level);
      coin.style.setProperty("--layer", String(level));
      additions.push(coin);
      ref.layers.push(coin);
    }
    if (before) before.before(...additions);
    else ref.stack.append(...additions);
  }

  // A chip has one bitmap and one DOM identity throughout the game. Reparent
  // the moving layers after measuring their launch and before measuring the landing.
  function transferChips(previous, next, player) {
    const moved = [];
    const before = previous.players[player].tokens;
    next.players[player].tokens.forEach((count, color) => {
      const delta = count - before[color];
      if (!delta) return;
      const bank = bankPiles[color], purse = ledgers[player]?.wells[color];
      if (!bank || !purse) return;
      const incoming = delta > 0;
      const source = incoming ? bank : purse, target = incoming ? purse : bank;
      const pieces = source.layers.splice(-Math.abs(delta));
      for (const coin of pieces) {
        BoardMotion.releaseChip(coin);
        coin.className = (incoming ? "wallet-chip" : "chip") + " changing-well";
        coin.dataset.layer = String(target.layers.length);
        coin.style.setProperty("--layer", coin.dataset.layer);
        target.layers.push(coin);
      }
      if (incoming) target.stack.append(...pieces);
      else target.counter.before(...pieces);
      moved.push(...pieces);
    });
    return moved;
  }

  function seatedChips(layers, reserved = 0) {
    const end = Math.max(0, layers.length - reserved);
    let count = end;
    for (let i = 0; i < end; i++) if (BoardMotion.isInFlight(layers[i])) count--;
    return count;
  }

  // The rules can accept the next move while the counters follow material touching the table.
  function refreshChipCounts() {
    for (const pile of bankPiles) setText(pile.counter, seatedChips(pile.layers, Math.max(0, pile.lifted)));
    for (const seat of ledgers) {
      let received = 0;
      for (const well of seat.wells) {
        const amount = Math.max(0, well.drawnAmount);
        const here = seatedChips(well.layers);
        const resting = amount ? seatedChips(well.layers, amount) : here;
        received += here;
        setText(well.counter, resting);
        const hide = !amount && resting < 2;
        if (well.counter.hidden !== hide) well.counter.hidden = hide;
      }
      setText(seat.held, received);
    }
  }

  function drawBank() {
    const host = byId("bank");
    if (bankTray?.parentNode !== host) {
      host.innerHTML = `<div class="bank-tray">${gemNames.map((name, i) => `<button type="button" class="bank-pile pile-${i}" data-open="bank" data-value="${i}">
        <span class="pile-face"><span class="chip-stack"><span class="bank-quantity" aria-hidden="true"></span></span><span class="bank-name">${name}</span></span></button>`).join("")}</div>`;
      bankTray = host.firstElementChild;
      bankPiles = Array.from(bankTray.children, node => ({node, stack: node.querySelector(".chip-stack"),
        counter: node.querySelector(".bank-quantity"), layers: [], count: -1, lifted: -1}));
    }
    bankPiles.forEach((pile, color) => {
      const count = state.bank[color];
      if (pile.layers.length === count && pile.count === count) return;
      setCoinLayers(pile, color, count, "chip", pile.counter);
      pile.node.classList.toggle("spent", !count);
    });
  }

  function previewBank(picked) {
    bankPiles.forEach((pile, color) => {
      const count = pile.layers.length;
      const lifted = picked?.[color] || 0;
      if (pile.count === count && pile.lifted === lifted) return;
      pile.count = count;
      pile.lifted = lifted;
      const resting = count - lifted;
      pile.layers.forEach((coin, level) => coin.classList.toggle("is-raised", level >= resting));
      supportAt(pile.node, lifted, resting);
      if (color < 5) {
        pile.node.classList.toggle("is-picked", !!lifted);
        setAttr(pile.node, "data-picked", lifted || null);
        setAttr(pile.node, "aria-pressed", !!lifted);
      }
      setAttr(pile.node, "aria-label", `${gemNames[color]}，槽内${resting}枚${lifted ? "，已选" + lifted + "枚" : ""}`);
    });
  }

  function mountSeat(index, host) {
    const pockets = gemNames.map((_, color) => `<button type="button" class="wallet-well empty" data-token-color="${color}" data-open="player" data-value="${index}">
      <span class="wallet-cavity"></span>${gem(color)}<span class="wallet-stack"></span><b class="stack-qty" aria-hidden="true" hidden>0</b></button>`).join("");
    const discounts = gemNames.slice(0, 5).map((_, color) => `<span class="deed-pile dye-${color} empty" data-bonus-color="${color}">
      <span class="deed">${gem(color)}</span><b class="bonus-count" aria-hidden="true"></b></span>`).join("");
    host.innerHTML = `<div class="ledger">
      <span class="leather-corner top-left" aria-hidden="true"></span><span class="leather-corner top-right" aria-hidden="true"></span>
      <div class="ledger-leaf"><div class="seat-identity"><div class="seat-profile"><img class="seat-seal" draggable="false" src="${sealURL(index)}" alt="">
      <h2><button type="button" class="name-button" data-open="player" data-value="${index}"></button></h2></div>
      <div class="seat-prestige"><span class="score-label">${icon("laurel")}声望</span><span class="seat-points"><span>0</span><small> / 15</small></span></div>
      <div class="guest-seals" role="group" aria-label="已来访的贵族" aria-hidden="true"></div></div>
      <div class="asset-heading"><span>筹码</span><span class="purse-total"><b>0</b><i></i><small> / 10</small></span></div>
      <div class="wallet-grid" role="group">${pockets}</div>
      <div class="asset-heading deed-heading"><span>永久加成</span><span class="virtual-stock" hidden></span></div><button type="button" class="deed-grid" data-open="player" data-value="${index}">${discounts}</button><div class="exp-player"></div></div>
      <button type="button" class="holdings-button" data-open="player" data-value="${index}" data-tab="reserved"><span class="reserve-fan" aria-hidden="true"><i class="vacant"></i><i class="vacant"></i><i class="vacant"></i><span class="pocket-lip"></span></span><span class="pocket-label">预留牌</span>${icon("arrow")}</button></div>`;
    const ledger = host.firstElementChild;
    const purse = ledger.querySelector(".purse-total");
    const bookmark = makeNode("span", "ledger-bookmark");
    bookmark.setAttribute("aria-hidden", "true");
    return {ledger, name: ledger.querySelector(".name-button"), points: ledger.querySelector(".seat-points > span"), purse,
      held: purse.querySelector("b"), projected: purse.querySelector("i"), wallet: ledger.querySelector(".wallet-grid"),
      deedGrid: ledger.querySelector(".deed-grid"), bag: ledger.querySelector(".holdings-button"), reserve: Array.from(ledger.querySelectorAll(".reserve-fan i")),
      wells: Array.from(ledger.querySelectorAll(".wallet-well"), node => ({node, stack: node.querySelector(".wallet-stack"),
        counter: node.querySelector(".stack-qty"), layers: [], drawnCount: -1, drawnAmount: -1, drawnMode: "", drawnName: ""})),
      deeds: Array.from(ledger.querySelectorAll(".deed-pile"), node => ({node, counter: node.querySelector(".bonus-count"), count: -1})),
      seals: ledger.querySelector(".guest-seals"), guestsKey: "",
      bookmark, crowned: false, nameValue: null, reserveKey: null, papers: new Map(), assetLabel: "", total: 0,
      walletDirty: true, wasPreviewOwner: false};
  }

  function drawBonus(ref, color, count) {
    if (count === ref.count) return;
    ref.node.classList.toggle("filled", count > 0);
    ref.node.classList.toggle("empty", count === 0);
    setAttr(ref.node, "title", `${gemNames[color]}永久加成 +${count}`);
    setText(ref.counter, count || "");
    ref.count = count;
  }

  function markSeat(index, refs) {
    const host = byId("seat-" + index);
    const active = (turnHandoff || state.phase !== "over") && (turnHandoff?.player ?? state.active) === index;
    const winner = !turnHandoff && state.phase === "over" && (state.winner === index || state.winner === "tie");
    host.classList.toggle("is-active", active);
    host.classList.toggle("is-winner", winner);
    if (active || winner) {
      const crown = state.finalRound || winner;
      if (refs.crowned !== crown) { refs.bookmark.innerHTML = crown ? icon("crown") : ""; refs.crowned = crown; }
      if (!refs.bookmark.parentNode) refs.ledger.append(refs.bookmark);
    } else if (refs.bookmark.parentNode) refs.bookmark.remove();
    const finalHand = !turnHandoff && active && state.finalRound && state.phase === "action" && index !== state.first;
    if (!finalHand) refs.ledger.querySelector(".last-hand-ribbon")?.remove();
    if (finalHand && !lastHandShown) {
      lastHandShown = true;
      const ribbon = makeNode("span","last-hand-ribbon");
      ribbon.textContent = "最后一手";
      ribbon.setAttribute("aria-hidden","true");
      ribbon.addEventListener("animationend", () => ribbon.remove(), {once:true});
      refs.ledger.append(ribbon);
    }
  }

  function refreshScore(index) {
    const label = ledgers[index]?.points;
    if (label) setText(label, Math.max(0, engine.score(state,index) - BoardMotion.pointsInFlight(index)));
    return label;
  }

  function drawSeat(index) {
    const host = byId("seat-" + index);
    let refs = ledgers[index];
    if (refs?.ledger.parentNode !== host) refs = ledgers[index] = mountSeat(index, host);
    const player = state.players[index];
    const name = playerName(index);
    markSeat(index, refs);
    const renamed = refs.nameValue !== name;
    if (renamed) {
      refs.nameValue = name;
      refs.walletDirty = true;
      setText(refs.name, name);
      setAttr(refs.name, "aria-label", `查看${name}的资产`);
      setAttr(host, "aria-label", (index ? "二号席，" : "一号席，") + name);
      setAttr(refs.wallet, "aria-label", name + "的筹码");
    }
    refs.total = total(player.tokens);
    refreshScore(index);
    refs.points.nextElementSibling.hidden = !!state.cities;
    const voucher = refs.ledger.querySelector(".virtual-stock"), gold = state.orient ? Orient.goldCards(state,index).length : 0;
    if (gold) setText(voucher,"金券 ×"+gold);
    voucher.hidden = !gold;
    refs.wells.forEach((well, color) => {
      const count = player.tokens[color];
      if (well.layers.length === count && well.drawnCount === count) return;
      refs.walletDirty = true;
      setCoinLayers(well, color, count, "wallet-chip");
      well.node.classList.toggle("filled", !!count);
      well.node.classList.toggle("empty", !count);
    });

    const discounts = engine.bonuses(state, index);
    refs.deeds.forEach((ref, color) => drawBonus(ref, color, discounts[color]));
    const assetLabel = discounts.map((count, color) => gemNames[color] + " +" + count).join("、");
    if (renamed || refs.assetLabel !== assetLabel) {
      refs.assetLabel = assetLabel;
      setAttr(refs.deedGrid, "aria-label", `${name}的永久加成，${assetLabel}，查看发展卡`);
    }
    const reserveKey = player.reserved.join(",");
    if (refs.reserveKey !== reserveKey) {
      const papers = new Map();
      refs.reserve.forEach((slot, i) => {
        const id = player.reserved[i];
        let paper = refs.papers.get(id) || null;
        if (id && !paper) {
          const meta = Lan.back(id);
          paper = pocketPaper(meta.tier,meta.pile);
        }
        if (paper) papers.set(id, paper);
        if (slot.firstElementChild !== paper) slot.replaceChildren(...(paper ? [paper] : []));
        slot.classList.toggle("held", !!id);
        slot.classList.toggle("vacant", !id);
      });
      refs.papers = papers;
    }
    if (renamed || refs.reserveKey !== reserveKey) {
      setAttr(refs.bag, "aria-label", `查看${name}的预留牌，已预留${player.reserved.length}张`);
    }
    refs.reserveKey = reserveKey;
    const guestsKey = player.nobles.join(",");
    refs.ledger.classList.toggle("has-portrait-row", state.players.some(p=>p.nobles.length>0));
    if (refs.guestsKey !== guestsKey) {
      syncNobles(refs.seals, player.nobles, guestSeal);
      setAttr(refs.seals, "aria-hidden", player.nobles.length ? null : "true");
      refs.guestsKey = guestsKey;
    }
  }

  function paintWalletWell(well, color, name, mode, amount) {
    const count = well.layers.length;
    if (well.drawnCount === count && well.drawnAmount === amount && well.drawnMode === mode && well.drawnName === name) return;
    well.drawnCount = count;
    well.drawnAmount = amount;
    well.drawnMode = mode;
    well.drawnName = name;
    const resting = count - amount;
    const paying = mode === "pay" && amount > 0;
    const returning = mode === "return" && amount > 0;
    supportAt(well.node, amount, resting);
    well.node.classList.toggle("will-pay", paying);
    well.node.classList.toggle("will-return", returning);
    setAttr(well.node, "data-pay", paying ? amount : null);
    setAttr(well.node, "aria-pressed", mode === "return" ? !!amount : null);
    const label = mode === "return" ? `${gemNames[color]}，槽内${resting}枚，待归还${amount}枚` :
      paying ? `${gemNames[color]}，将支付${amount}枚，余${resting}枚` : `${name}的${gemNames[color]}，${count}枚`;
    setAttr(well.node, "aria-label", label);
    setAttr(well.node, "title", `${gemNames[color]} ${count}枚`);
    well.layers.forEach((coin, level) => {
      coin.classList.toggle("is-paying-chip", paying && level >= resting);
      coin.classList.toggle("is-returning", returning && level >= resting);
    });
  }

  function projectWallet(mode, amounts, cardId) {
    ledgers.forEach((refs, player) => {
      const current = player === state.active;
      // Once a previous player hands off, its unselected wallet need not be touched on later taps.
      if (!current && !refs.wasPreviewOwner && !refs.walletDirty) return;
      refs.wasPreviewOwner = current;
      refs.walletDirty = false;
      const projection = current && amounts ? total(amounts) : 0;
      const returning = current && state.phase === "discard";
      const paying = current && mode === "pay" && !!amounts;
      const bonus = paying && cardId ? engine.cards[cardId]?.bonus : -1;
      refs.deeds.forEach((deed, color) => deed.node.classList.toggle("will-gain", color === bonus));
      for (let color = 0; color < refs.wells.length; color++) {
        refs.wells[color].node.classList.toggle("will-receive", current && mode === "take" && !!amounts?.[color]);
        const amount = (paying || (returning && mode === "return")) ? amounts?.[color] || 0 : 0;
        paintWalletWell(refs.wells[color], color, playerName(player), returning ? "return" : paying && amount ? "pay" : "rest", amount);
      }
      const after = refs.total + (mode === "take" && !returning ? projection : -projection);
      refs.purse.classList.toggle("paying", paying);
      refs.purse.classList.toggle("excess", returning || (current && mode === "take") ? after > 10 : false);
      setText(refs.projected, projection ? " → " + after : "");
    });
    // The same tap may reparent coins and start their flight. Count the seated layers once afterwards.
    BoardMotion.queueChipCounts();
  }

  const previewTake = tokens => projectWallet("take", tokens);
  const previewPay = (tokens, cardId) => projectWallet("pay", tokens, cardId);
  const previewReturn = tokens => projectWallet("return", tokens);

  function announceTurn(visit) {
    if (turnHandoff) return;
    const name = playerName(state.active);
    const phase = {action: "轮到" + name + "。", discard: name + "归还多余筹码。", noble: name + "选择贵族。", effect:name + "完成扩展行动。", over: "对局结束。"};
    const turn = (state.finalRound && state.phase !== "over" ? "最后一轮。" : "") + phase[state.phase];
    if (!visit && state === announcedState && turn === announcedTurn) return;
    announcedState = state;
    announcedTurn = turn;
    const message = visit + turn;
    const status = byId("turn-status");
    if (status.textContent !== message) status.textContent = message;
  }

  function drawToolbar() {
    const toolbar = byId("toolbar");
    toolbar.innerHTML = `<button type="button" data-open="rules" aria-label="游戏规则" title="游戏规则">${icon("book")}</button>
      <button type="button" data-open="settings" aria-label="对局设置" title="对局设置">${icon("gear")}</button>`;
  }

  function bindPieceGestures(surface) {
    let press = null;
    let suppressReleaseClick = false;
    function clearContact() {
      if (press?.contact) {
        press.contact.classList.remove("is-contacted");
        press.piece.classList.remove("touch-lift");
        press.piece.style.removeProperty("--contact-support");
        press.contact = null;
      }
    }
    function stopPress() {
      if (press) clearTimeout(press.timer);
      clearContact();
      press = null;
    }
    surface.addEventListener("pointerdown", event => {
      stopPress();
      suppressReleaseClick = false;
      if (!event.isPrimary || event.button !== 0 || computerTurn() || waitingForFriend()) return;
